        </Card>

        <Card className="p-6">
          <p className="eyebrow">
            Recommended next step
          </p>
          <h3 className="mt-2 section-title">
            Resolve the family account fast
          </h3>
          <p className="mt-3 text-[13px] leading-relaxed text-muted">
