            exportConfig={{
              filename: "admissions-documents.csv",
              headers: ["Learner", "Document", "File", "Uploaded On", "Verification"],
              rows: filteredDocuments.map((document) => [
                document.learnerName,
                document.documentType,
                document.fileName,
                document.uploadedOn,
                formatDocumentStatus(document.verificationStatus),
              ]),
            }}
            actions={
              <Button onClick={() => openDocumentUploadModal()}>
                <FileUp className="h-4 w-4" />
                Upload document
              </Button>
            }
          />
        ) : null}

        {activeSection === "class-allocation" ? (
          <div className="space-y-6">
            <OpsTable
              title="Class allocation"
              subtitle={
                transportEnabled
                  ? "Assign class, stream, dormitory, and transport route once registration is complete."
                  : "Assign class, stream, and dormitory once registration is complete."
              }
              rows={dataset.allocations}
              columns={allocationColumns}
              getRowId={(row) => row.id}
              totalRows={dataset.allocations.length}
              page={1}
              pageSize={50}
              onPageChange={() => undefined}
              loading={isDatasetLoading}
              loadingLabel="Loading live class allocations..."
              actions={
                <Button onClick={() => setAllocationModalOpen(true)}>
                  <CheckCheck className="h-4 w-4" />
                  Assign allocation
                </Button>
              }
            />
          </div>
        ) : null}

        {activeSection === "transfers" ? (
          <div className="space-y-6">
            <OpsTable
              title="Transfers"
              subtitle="Incoming and outgoing learner transfers with reason and school history visible to the admissions office."
              rows={dataset.transfers}
              columns={transferColumns}
              getRowId={(row) => row.id}
              totalRows={dataset.transfers.length}
              page={1}
              pageSize={50}
              onPageChange={() => undefined}
              loading={isDatasetLoading}
              loadingLabel="Loading live transfer register..."
              actions={
                <Button onClick={() => setTransferModalOpen(true)}>
                  <RefreshCcw className="h-4 w-4" />
                  New transfer
                </Button>
              }
            />
          </div>
        ) : null}

        {activeSection === "reports" ? (
          <div className="space-y-6">
            <section className="grid gap-6 xl:grid-cols-2">
              {reports.map((report) => (
                <Card key={report.id} className="p-5">
                  <p className="text-xs font-semibold uppercase tracking-[0.18em] text-muted">
                    Report
                  </p>
                  <h3 className="mt-2 text-lg font-semibold text-foreground">{report.title}</h3>
                  <p className="mt-2 text-sm leading-6 text-muted">{report.description}</p>
                  <div className="mt-5 flex flex-wrap gap-3">
                    <Button
                      variant="secondary"
                      onClick={() => void exportAdmissionsReport(report)}
                      disabled={activeActionId === `${report.id}-export`}
                    >
                      {activeActionId === `${report.id}-export`
                        ? "Exporting..."
                        : `Export ${report.filename.replace(".csv", "")}`}
                    </Button>
                  </div>
                  <div className="mt-5 rounded-xl border border-border bg-surface-muted px-4 py-4">
                    <p className="text-xs uppercase tracking-[0.18em] text-muted">Preview row</p>
                    <p className="mt-2 text-sm text-foreground">
                      {report.rows[0]?.join(" · ") ?? "No rows available yet."}
                    </p>
                  </div>
                </Card>
              ))}
            </section>

            <WorkflowCard
              eyebrow="Reporting rules"
              title="Keep admissions reporting practical"
              description="Reports should answer common office questions immediately without extra cleanup."
              items={[
                {
                  id: "report-rule-1",
                  title: "Applications status mix",
                  detail: "Which files are pending, approved, rejected, or fully registered?",
                },
                {
                  id: "report-rule-2",
                  title: "Document compliance",
                  detail: "Which learners are blocked by missing or unverified documents?",
                },
                {
                  id: "report-rule-3",
                  title: "Allocation completion",
                  detail: transportEnabled
                    ? "Which admitted learners still need stream, dormitory, or route assignment?"
                    : "Which admitted learners still need stream or dormitory assignment?",
                },
              ]}
            />
          </div>
        ) : null}
      </ModuleShell>

      <Modal
        open={documentUploadModalOpen}
        title="Upload admissions document"
        description="Attach a scanned file to an applicant record. New uploads enter pending verification before approval."
        onClose={() => setDocumentUploadModalOpen(false)}
        footer={
          <>
            <Button variant="secondary" onClick={() => setDocumentUploadModalOpen(false)}>
              Cancel
            </Button>
            <Button onClick={submitDocumentUpload} disabled={isSavingDocumentUpload}>
              {isSavingDocumentUpload ? "Uploading..." : "Upload document"}
            </Button>
          </>
        }
      >
        <div className="grid gap-4 md:grid-cols-2">
          <FieldWrapper label="Applicant" error={documentUploadErrors.applicationId}>
            <select
              className={fieldClassName}
              value={documentUploadForm.applicationId}
              onChange={(event) =>
                setDocumentUploadForm((current) => ({
                  ...current,
                  applicationId: event.target.value,
                }))
              }
            >
              <option value="">Select applicant file</option>
              {dataset.applications.map((application) => (
                <option key={application.id} value={application.id}>
                  {application.applicantName} ({application.applicationNumber})
                </option>
              ))}
            </select>
          </FieldWrapper>

          <FieldWrapper label="Document type" error={documentUploadErrors.documentType}>
            <select
              className={fieldClassName}
              value={documentUploadForm.documentType}
              onChange={(event) =>
                setDocumentUploadForm((current) => ({
                  ...current,
                  documentType: event.target.value,
                }))
              }
            >
              <option value="">Select document type</option>
              {admissionsDocumentTypes.map((documentType) => (
                <option key={documentType} value={documentType}>
                  {documentType}
                </option>
              ))}
            </select>
          </FieldWrapper>

          <div className="md:col-span-2">
            <FieldWrapper label="Document file" error={documentUploadErrors.fileName}>
              <input
                type="file"
                accept=".pdf,.jpg,.jpeg,.png"
                className={fieldClassName}
                onChange={(event) => {
                  const file = event.target.files?.[0] ?? null;
                  setDocumentUploadForm((current) => ({
                    ...current,
                    file,
                    fileName: file?.name ?? "",
                  }));
                }}
              />
            </FieldWrapper>
          </div>

          <div className="md:col-span-2">
            <Card className="p-4">
              {selectedDocumentUploadApplication ? (
                <div className="grid gap-3 md:grid-cols-3">
                  <div>
                    <p className="text-xs uppercase tracking-[0.18em] text-muted">Class</p>
                    <p className="mt-1 text-sm font-semibold text-foreground">
                      {selectedDocumentUploadApplication.classApplying}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs uppercase tracking-[0.18em] text-muted">Parent contact</p>
                    <p className="mt-1 text-sm font-semibold text-foreground">
                      {selectedDocumentUploadApplication.parentPhone}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs uppercase tracking-[0.18em] text-muted">Application status</p>
                    <div className="mt-1">
                      <StatusPill
                        label={formatApplicationStatus(selectedDocumentUploadApplication.status)}
                        tone={getApplicationTone(selectedDocumentUploadApplication.status)}
                      />
                    </div>
                  </div>
                </div>
              ) : (
                <p className="text-sm leading-6 text-muted">
                  Select an applicant file to show the class, parent contact, and approval state
                  before uploading.
                </p>
              )}
            </Card>
          </div>
        </div>
      </Modal>

      <Modal
        open={allocationModalOpen}
        title="Assign class allocation"
        description="Complete the final onboarding steps after registration."
        onClose={() => setAllocationModalOpen(false)}
        footer={
          <>
            <Button variant="secondary" onClick={() => setAllocationModalOpen(false)}>
              Cancel
            </Button>
            <Button onClick={submitAllocation} disabled={isSavingAllocation}>
              {isSavingAllocation ? "Saving..." : "Save allocation"}
            </Button>
          </>
        }
      >
        <div className="grid gap-4 md:grid-cols-2">
          <FieldWrapper label="Student" error={allocationErrors.studentId}>
            <select
              className={fieldClassName}
              value={allocationForm.studentId}
              onChange={(event) =>
                setAllocationForm((current) => ({ ...current, studentId: event.target.value }))
              }
            >
              <option value="">Select learner</option>
              {dataset.students.map((student) => (
                <option key={student.id} value={student.id}>
                  {student.fullName} ({student.admissionNumber})
                </option>
              ))}
            </select>
          </FieldWrapper>
          <FieldWrapper label="Class" error={allocationErrors.className}>
            <input
              className={fieldClassName}
              value={allocationForm.className}
              onChange={(event) =>
                setAllocationForm((current) => ({ ...current, className: event.target.value }))
              }
              placeholder="Class name"
            />
          </FieldWrapper>
          <FieldWrapper label="Stream" error={allocationErrors.streamName}>
            <input
              className={fieldClassName}
              value={allocationForm.streamName}
              onChange={(event) =>
                setAllocationForm((current) => ({ ...current, streamName: event.target.value }))
              }
              placeholder="Stream name"
            />
          </FieldWrapper>
          <FieldWrapper label="Dormitory" error={allocationErrors.dormitoryName}>
            <input
              className={fieldClassName}
              value={allocationForm.dormitoryName}
              onChange={(event) =>
                setAllocationForm((current) => ({ ...current, dormitoryName: event.target.value }))
              }
              placeholder="Dormitory or boarding house"
            />
          </FieldWrapper>
          {transportEnabled ? (
            <div className="md:col-span-2">
              <FieldWrapper label="Transport route" error={allocationErrors.transportRoute}>
                <input
                  className={fieldClassName}
                  value={allocationForm.transportRoute}
                  onChange={(event) =>
                    setAllocationForm((current) => ({ ...current, transportRoute: event.target.value }))
                  }
                  placeholder="Transport route name"
                />
              </FieldWrapper>
            </div>
          ) : null}
        </div>
      </Modal>

      <Modal
        open={transferModalOpen}
        title="Create transfer record"
        description="Log an incoming or outgoing learner transfer into the admissions workflow."
        onClose={() => setTransferModalOpen(false)}
        footer={
          <>
            <Button variant="secondary" onClick={() => setTransferModalOpen(false)}>
              Cancel
            </Button>
            <Button onClick={submitTransfer} disabled={isSavingTransfer}>
              {isSavingTransfer ? "Saving..." : "Save transfer"}
            </Button>
          </>
        }
      >
        <div className="grid gap-4 md:grid-cols-2">
          <FieldWrapper label="Learner name" error={transferErrors.learnerName}>
            <input
              className={fieldClassName}
              value={transferForm.learnerName}
              onChange={(event) =>
                setTransferForm((current) => ({ ...current, learnerName: event.target.value }))
              }
              placeholder="Learner name"
            />
          </FieldWrapper>
          <FieldWrapper label="Admission number" error={transferErrors.admissionNumber}>
            <input
              className={fieldClassName}
              value={transferForm.admissionNumber}
              onChange={(event) =>
                setTransferForm((current) => ({ ...current, admissionNumber: event.target.value }))
              }
              placeholder="Admission number"
            />
          </FieldWrapper>
          <FieldWrapper label="Direction">
            <select
              className={fieldClassName}
              value={transferForm.direction}
              onChange={(event) =>
                setTransferForm((current) => ({
                  ...current,
                  direction: event.target.value as TransferFormState["direction"],
                }))
              }
            >
              <option value="incoming">Incoming</option>
              <option value="outgoing">Outgoing</option>
            </select>
          </FieldWrapper>
          <FieldWrapper label="School name" error={transferErrors.schoolName}>
            <input
              className={fieldClassName}
              value={transferForm.schoolName}
              onChange={(event) =>
                setTransferForm((current) => ({ ...current, schoolName: event.target.value }))
              }
              placeholder="School name"
            />
          </FieldWrapper>
          <div className="md:col-span-2">
            <FieldWrapper label="Reason" error={transferErrors.reason}>
              <textarea
                className={textAreaClassName}
                value={transferForm.reason}
                onChange={(event) =>
                  setTransferForm((current) => ({ ...current, reason: event.target.value }))
                }
                placeholder="Reason for transfer"
              />
            </FieldWrapper>
          </div>
        </div>
      </Modal>
    </>
  );
}

"use client";
import { DocxOperationalWorkspace } from "@/components/school/docx-operational-workspace";

import { useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLiveTenantSession } from "@/hooks/use-live-tenant-session";
import type { DashboardRole, DashboardSnapshot } from "@/lib/dashboard/types";
import { fetchDeanDatasetLive } from "@/lib/modules/dean-live";
import { createEmptyDeanDataset } from "@/lib/modules/dean-data";
import { PageHeader } from "@/components/ui/page-header";
import { Card } from "@/components/ui/card";
import { buildSchoolErpModel } from "@/lib/dashboard/erp-model";
import { 
  AcademicCalendarWorkspace, 
  SubjectsWorkspace, 
  SyllabusCoverageWorkspace, 
  TimetableOversightWorkspace 
} from "./dean-academic-workspaces";
import { 
  DepartmentsWorkspace, 
  TeacherWorkloadWorkspace, 
  LessonPlansWorkspace, 
  LessonLogsWorkspace 
} from "./dean-staff-workspaces";
import {
  ContinuousAssessmentWorkspace,
  ExamReviewWorkspace,
  ExamPerformanceAnalyticsWorkspace,
  ReportCardOversightWorkspace
} from "./dean-assessment-workspaces";
import {
  AcademicInterventionsWorkspace,
  StudentAcademicSupportWorkspace,
  DepartmentReviewsWorkspace,
  TeacherAcademicReportsWorkspace
} from "./dean-intervention-workspaces";
import {
  AcademicReportsWorkspace,
  MessagesNoticesWorkspace,
  ApprovalsFollowUpsWorkspace,
  MyTeachingWorkspace,
  DeanSettingsWorkspace
} from "./dean-admin-workspaces";

export function DeanModuleScreen({
  role,
  moduleName,
  snapshot,
  online,
}: {
  role: DashboardRole;
  moduleName: string;
  snapshot: DashboardSnapshot;
  online: boolean;
}) {
  const model = useMemo(
    () => buildSchoolErpModel({ role, tenant: snapshot.tenant, online }),
    [online, role, snapshot.tenant],
  );

  const liveSession = useLiveTenantSession(snapshot.tenant.id);
  const liveDeanQuery = useQuery({
    queryKey: ["dean-module", liveSession.session?.tenantId],
    queryFn: () => fetchDeanDatasetLive(liveSession.session!),
    enabled: Boolean(liveSession.session),
  });

  const dataset = liveDeanQuery.data ?? createEmptyDeanDataset();
  const isLoading = Boolean(liveSession.session && liveDeanQuery.isLoading);

  const workspaces: Record<string, React.ReactNode> = {
    "command-center": <CommandCenterWorkspace model={model} dataset={dataset} isLoading={isLoading} />,
    "academic-calendar": <AcademicCalendarWorkspace dataset={dataset} />,
    "departments": <DepartmentsWorkspace dataset={dataset} />,
    "subjects": <SubjectsWorkspace dataset={dataset} />,
    "teacher-workload": <TeacherWorkloadWorkspace dataset={dataset} />,
    "timetable-oversight": <TimetableOversightWorkspace dataset={dataset} />,
    "lesson-plans": <LessonPlansWorkspace dataset={dataset} />,
    "lesson-logs": <LessonLogsWorkspace dataset={dataset} />,
    "syllabus-coverage": <SyllabusCoverageWorkspace dataset={dataset} />,
    "continuous-assessment": <ContinuousAssessmentWorkspace dataset={dataset} />,
    "exam-review": <ExamReviewWorkspace dataset={dataset} />,
    "performance-analytics": <ExamPerformanceAnalyticsWorkspace dataset={dataset} />,
    "academic-interventions": <AcademicInterventionsWorkspace dataset={dataset} />,
    "department-reviews": <DepartmentReviewsWorkspace dataset={dataset} />,
    "teacher-academic-reports": <TeacherAcademicReportsWorkspace dataset={dataset} />,
    "student-academic-support": <StudentAcademicSupportWorkspace dataset={dataset} />,
    "report-card-oversight": <ReportCardOversightWorkspace dataset={dataset} />,
    "academic-reports": <AcademicReportsWorkspace dataset={dataset} />,
    "messages-notices": <MessagesNoticesWorkspace dataset={dataset} />,
    "approvals-follow-ups": <ApprovalsFollowUpsWorkspace dataset={dataset} />,
    "my-teaching": <MyTeachingWorkspace dataset={dataset} />,
    "dean-settings": <DeanSettingsWorkspace dataset={dataset} />,
  };

  const content = workspaces[moduleName] || <DocxOperationalWorkspace moduleId={moduleName} />;

  if (isLoading && !liveDeanQuery.data) {
    return (
      <div className="flex min-h-[400px] items-center justify-center">
        <p className="text-sm text-muted">Loading academic data...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {content}
    </div>
  );
}

import type { DeanDataset } from "@/lib/modules/dean-data";

function CommandCenterWorkspace({ model, dataset, isLoading }: { model: any; dataset: DeanDataset; isLoading: boolean }) {
  const coverageBehind = dataset.syllabusCoverage.filter(c => c.riskLevel !== "on-track").length;
  const missingLogs = dataset.lessonLogs.filter(l => l.logStatus !== "submitted").length;
  const pendingReviews = dataset.departmentReviews.filter(r => r.deanReviewStatus === "pending").length;

  return (
    <div className="space-y-6">
      <PageHeader
        eyebrow="Command Center"
        title="Dean of Academics"
        description="Monitor active syllabus gaps, missing logs, and academic interventions today."
      />
      <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        <Card className="p-5">
          <p className="eyebrow">Syllabus Coverage</p>
          <p className="mt-3 metric-value">{dataset.syllabusCoverage.length > 0 ? "76%" : "N/A"}</p>
          <p className="mt-2 text-[13px] text-muted">{coverageBehind} class-subjects behind expected pace</p>
        </Card>
        <Card className="p-5">
          <p className="eyebrow">Missing Lesson Logs</p>
          <p className="mt-3 metric-value text-danger">{missingLogs}</p>
          <p className="mt-2 text-[13px] text-muted">Requires immediate follow-up</p>
        </Card>
        <Card className="p-5">
          <p className="eyebrow">Pending HOD Reviews</p>
          <p className="mt-3 metric-value">{pendingReviews}</p>
          <p className="mt-2 text-[13px] text-muted">Departments awaiting Dean review</p>
        </Card>
      </section>

      {dataset.risks.length > 0 ? (
        <Card className="p-5 overflow-x-auto">
          <p className="font-semibold text-foreground mb-4">Academic Risks</p>
          <table className="w-full text-left text-sm border-collapse">
            <thead>
              <tr className="border-b text-muted">
                <th className="pb-3 pr-4 font-medium">Risk ID</th>
                <th className="pb-3 pr-4 font-medium">Class / Subject</th>
                <th className="pb-3 pr-4 font-medium">Risk Type</th>
                <th className="pb-3 pr-4 font-medium">Severity</th>
                <th className="pb-3 font-medium">Status</th>
              </tr>
            </thead>
            <tbody>
              {dataset.risks.map((risk) => (
                <tr key={risk.id} className="border-b last:border-0 hover:bg-surface-muted transition-colors">
                  <td className="py-3 pr-4">{risk.id}</td>
                  <td className="py-3 pr-4">{risk.classStream} · {risk.subject}</td>
                  <td className="py-3 pr-4">{risk.riskType}</td>
                  <td className="py-3 pr-4">{risk.severity}</td>
                  <td className="py-3">{risk.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Card>
      ) : (
        <Card className="flex min-h-[300px] flex-col items-center justify-center p-8 text-center mt-6">
          <p className="text-sm font-semibold text-foreground">No critical academic risks today</p>
          <p className="mt-2 max-w-md text-sm text-muted">
            Your command center table goes here. Everything looks on track right now.
          </p>
        </Card>
      )}
    </div>
  );
}

