import { downloadCsvFile, openPrintDocument } from "@/lib/dashboard/export";

interface MarkVersionRow {
  id?: string;
  mark_id?: string | null;
  original_score?: number | string | null;
  correction_score?: number | string | null;
  reason?: string | null;
  corrected_by_user_id?: string | null;
  approval_state?: string | null;
}

interface ApiResponse<T> {
  data?: T;
}

export function ModerationWorkspace({ model }: { model: unknown }) {
  void model;
  const [notice, setNotice] = useState<string | null>(null);
  const [savingAction, setSavingAction] = useState<string | null>(null);
  const { data: versionsResponse, isLoading, error, refetch } = useSchoolQuery<ApiResponse<MarkVersionRow[]> | MarkVersionRow[]>("/exams/mark-versions");
  const versions = Array.isArray(versionsResponse) ? versionsResponse : versionsResponse?.data;
  const visibleVersions = Array.isArray(versions) ? versions : [];

  function versionKey(row: MarkVersionRow, index: number) {
    return row.id ?? `${row.mark_id ?? "mark"}-${index}`;
  }

  function exportIssues(rows: MarkVersionRow[]) {
    downloadCsvFile({
      filename: `mark-moderation-issues-${new Date().toISOString().slice(0, 10)}.csv`,
      headers: ["Mark ID", "Original score", "Correction score", "Reason", "Assigned to", "Status"],
      rows: rows.map((row, index) => [
        row.mark_id ?? "",
        String(row.original_score ?? ""),
        String(row.correction_score ?? ""),
        row.reason ?? "",
        row.corrected_by_user_id ?? "",
        row.approval_state ?? "pending",
      ]),
    });
    setNotice(`Moderation issue CSV downloaded with ${rows.length} issue${rows.length === 1 ? "" : "s"}.`);
  }

  async function moderateMarkRows(rows: MarkVersionRow[], action: "approve" | "return_for_correction", reason?: string) {
    const markIds = rows.map((row) => row.mark_id).filter((id): id is string => Boolean(id));
    if (!markIds.length) {
      setNotice("No persisted mark rows are available for moderation.");
      return;
    }
    setSavingAction(action);
    try {
      const body = action === "approve"
        ? { action: "approve", mark_ids: markIds }
        : { action: "return_for_correction", mark_ids: markIds, reason: reason ?? "Returned by Exams Manager for teacher correction." };
      const result = await requestDashboardApi<{ updated_count?: number }>("/api/exams/marks/moderate", {
        method: "POST",
        body,
      });
      await refetch();
      const updatedCount = Number(result.updated_count ?? 0);
      setNotice(`${updatedCount} mark row${updatedCount === 1 ? "" : "s"} ${action === "approve" ? "approved" : "returned for correction"}.`);
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Could not complete mark moderation.");
    } finally {
      setSavingAction(null);
    }
  }

  function previewModerationRow(row: MarkVersionRow, title: string) {
    openPrintDocument({
      eyebrow: "Exam moderation",
      title,
      subtitle: `Mark ${row.mark_id ?? "unassigned"}`,
      rows: [
        { label: "Original score", value: String(row.original_score ?? "-") },
        { label: "Correction score", value: String(row.correction_score ?? "-") },
        { label: "Reason", value: String(row.reason ?? "No reason recorded") },
        { label: "Corrected by", value: String(row.corrected_by_user_id ?? "Unassigned") },
        { label: "Approval state", value: String(row.approval_state ?? "pending") },
      ],
      footer: "Moderation detail preview generated from current school mark correction records.",
    });
    setNotice(`${title} print preview generated for mark ${row.mark_id ?? "unassigned"}.`);
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <PageHeader
          eyebrow="Validation"
          title="Moderation & Validation"
          description="Detect incorrect, suspicious, incomplete, or inconsistent results before publishing."
        />
        <div className="flex flex-wrap gap-2">
          <Button variant="outline" disabled={!!savingAction} onClick={() => void moderateMarkRows(visibleVersions, "return_for_correction", "Bulk correction request from Exams Manager moderation.")}>{savingAction === "return_for_correction" ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Mail className="mr-2 h-4 w-4" />} Send Correction Requests</Button>
          <Button variant="outline" onClick={() => exportIssues(visibleVersions)}><Download className="mr-2 h-4 w-4" /> Export Issues</Button>
          <Button disabled={!!savingAction} onClick={() => void moderateMarkRows(visibleVersions, "approve")}>{savingAction === "approve" ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <PlayCircle className="mr-2 h-4 w-4" />} Run Full Moderation</Button>
        </div>
      </div>

      {notice ? <div className="rounded-md border border-blue-200 bg-blue-50 p-3 text-sm font-semibold text-blue-900">{notice}</div> : null}

      <section className="grid gap-4 md:grid-cols-3 lg:grid-cols-6">
        {[
          { label: "Pending Issues", value: String(visibleVersions.filter((row) => !["approved", "reviewed"].includes((row.approval_state ?? "").toLowerCase())).length), type: "warning" },
          { label: "Returned", value: String(visibleVersions.filter((row) => ["rejected", "returned"].includes((row.approval_state ?? "").toLowerCase())).length), type: "destructive" },
          { label: "Assigned", value: String(visibleVersions.filter((row) => Boolean(row.corrected_by_user_id)).length), type: "default" },
          { label: "Approved Exceptions", value: String(visibleVersions.filter((row) => ["approved", "reviewed"].includes((row.approval_state ?? "").toLowerCase())).length), type: "default" },
          { label: "Reviewed", value: String(visibleVersions.filter((row) => Boolean(row.approval_state)).length), type: "default" },
          { label: "Loaded Rows", value: String(visibleVersions.length), type: "default" },
        ].map((card, idx) => (
          <Card key={idx} className="p-4">
            <p className="text-xs font-medium text-muted-foreground">{card.label}</p>
            <p className={`mt-2 text-2xl font-bold text-${card.type === "default" ? "foreground" : card.type}`}>{card.value}</p>
          </Card>
        ))}
      </section>

      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Severity</TableHead>
                <TableHead>Issue Type</TableHead>
                <TableHead>Subject</TableHead>
                <TableHead>Student</TableHead>
                <TableHead>Detected Problem</TableHead>
                <TableHead>Assigned To</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading && (
                <TableRow>
                  <TableCell colSpan={8} className="text-center py-10">
                    <Loader2 className="h-6 w-6 animate-spin text-muted-foreground mx-auto mb-2" />
                    <p className="text-muted-foreground">Loading mark moderation requests...</p>
                  </TableCell>
                </TableRow>
              )}
              {error && (
                <TableRow>
                  <TableCell colSpan={8} className="text-center py-10 text-destructive">
                    Error loading requests: {error.message}
                  </TableCell>
                </TableRow>
              )}
              {!isLoading && !error && (!versions || !Array.isArray(versions) || versions.length === 0) && (
                <TableRow>
                  <TableCell colSpan={8} className="text-center py-10 text-muted-foreground">
                    No pending moderation requests.
                  </TableCell>
                </TableRow>
              )}
              {!isLoading && !error && Array.isArray(versions) && versions.map((row, idx) => {
                const key = versionKey(row, idx);
                const status = row.approval_state ?? "pending";
                return (
                  <TableRow key={key}>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <div className={`w-2 h-2 rounded-full ${status === "pending" || status === "returned" ? "bg-warning" : "bg-success"}`} />
                        <span className="font-medium">Medium</span>
                      </div>
                    </TableCell>
                    <TableCell className="font-medium">Mark Correction</TableCell>
                    <TableCell>Mark ID: {row.mark_id}</TableCell>
                    <TableCell>Score: {row.original_score} -&gt; {row.correction_score}</TableCell>
                    <TableCell className="text-muted-foreground">{row.reason}</TableCell>
                    <TableCell>{row.corrected_by_user_id}</TableCell>
                    <TableCell>
                      <Badge variant={status === "approved_exception" ? "success" : status === "returned" ? "destructive" : "outline"}>{status}</Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon">
                            <MoreHorizontal className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => previewModerationRow(row, "Moderation issue detail")}><Eye className="mr-2 h-4 w-4" /> View Issue</DropdownMenuItem>
                          <DropdownMenuItem onClick={() => previewModerationRow(row, "Mark correction detail")}><Edit className="mr-2 h-4 w-4" /> Open Mark</DropdownMenuItem>
                          <DropdownMenuItem onClick={() => void moderateMarkRows([row], "return_for_correction", "Assigned back to teacher for correction from moderation.")}><UserCheck className="mr-2 h-4 w-4" /> Assign to Teacher</DropdownMenuItem>
                          <DropdownMenuItem onClick={() => void moderateMarkRows([row], "return_for_correction", "Returned by Exams Manager for correction.")}><Mail className="mr-2 h-4 w-4" /> Return for Correction</DropdownMenuItem>
                          <DropdownMenuItem onClick={() => void moderateMarkRows([row], "approve")}><CheckCircle className="mr-2 h-4 w-4" /> Approve Exception</DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </div>
      </Card>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { PageHeader } from "@/components/ui/page-header";
import { Card } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { MoreHorizontal, Plus, Copy, Upload, Edit, Trash2, Settings, Loader2 } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { requestDashboardApi } from "@/lib/dashboard/api-client";

interface AssessmentComponentRow {
  id?: string;
  assessment_id: string;
  component_name: string;
  component_code: string;
  max_score: number;
  weight: number;
}

interface AssessmentRow {
  id?: string;
  name?: string;
}

interface ApiResponse<T> {
  data?: T;
}

interface ComponentFormValue {
  assessment_id: string;
  component_name: string;
  component_code: string;
  max_score: string;
  weight: string;
}

function readRows<T>(response: ApiResponse<T[]> | T[] | undefined): T[] {
  const rows = Array.isArray(response) ? response : response?.data;
  return Array.isArray(rows) ? rows : [];
}

function parseCsvLine(line: string): string[] {
  const values: string[] = [];
  let value = "";
  let quoted = false;
  for (let index = 0; index < line.length; index += 1) {
    const character = line[index];
    if (character === '"' && quoted && line[index + 1] === '"') {
      value += '"';
      index += 1;
    } else if (character === '"') {
      quoted = !quoted;
    } else if (character === "," && !quoted) {
      values.push(value.trim());
      value = "";
    } else {
      value += character;
    }
  }
  values.push(value.trim());
  return values;
}

function ComponentDialog({
  open,
  component,
  assessments,
  onClose,
  onSave,
}: {
  open: boolean;
  component: AssessmentComponentRow | null;
  assessments: AssessmentRow[];
  onClose: () => void;
  onSave: (value: ComponentFormValue) => Promise<void>;
}) {
  const [form, setForm] = useState<ComponentFormValue>({
    assessment_id: "",
    component_name: "",
    component_code: "",
    max_score: "100",
    weight: "100",
  });
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  useEffect(() => {
    if (!open) return;
    setForm({
      assessment_id: component?.assessment_id ?? assessments.find((row) => row.id)?.id ?? "",
      component_name: component?.component_name ?? "",
      component_code: component?.component_code ?? "",
      max_score: String(component?.max_score ?? 100),
      weight: String(component?.weight ?? 100),
    });
    setFormError(null);
  }, [open, component, assessments]);

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const maxScore = Number(form.max_score);
    const weight = Number(form.weight);
    if (!form.assessment_id || !form.component_name.trim() || !form.component_code.trim()) {
      setFormError("Assessment, component name, and component code are required.");
      return;
    }
    if (!Number.isFinite(maxScore) || maxScore <= 0 || !Number.isFinite(weight) || weight <= 0 || weight > 100) {
      setFormError("Maximum score must be positive and weight must be between 0 and 100.");
      return;
    }
    setSaving(true);
    setFormError(null);
    try {
      await onSave(form);
      onClose();
    } catch (error) {
      setFormError(error instanceof Error ? error.message : "Could not save the assessment component.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={(nextOpen) => { if (!nextOpen) onClose(); }}>
      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-lg">
        <form onSubmit={submit}>
          <DialogHeader>
            <DialogTitle>{component?.id ? "Edit component" : "Add assessment component"}</DialogTitle>
            <DialogDescription>Configure the paper code, score ceiling, and contribution to the assessment.</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="component-assessment">Assessment</Label>
              <select
                id="component-assessment"
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                value={form.assessment_id}
                disabled={Boolean(component?.id)}
                onChange={(event) => setForm((current) => ({ ...current, assessment_id: event.target.value }))}
                required
              >
                <option value="">Select assessment</option>
                {assessments.filter((row): row is AssessmentRow & { id: string } => Boolean(row.id)).map((row) => (
                  <option key={row.id} value={row.id}>{row.name || row.id}</option>
                ))}
              </select>
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="component-name">Component name</Label>
                <Input id="component-name" value={form.component_name} onChange={(event) => setForm((current) => ({ ...current, component_name: event.target.value }))} placeholder="Paper 1 Theory" required />
              </div>
              <div className="space-y-2">
                <Label htmlFor="component-code">Component code</Label>
                <Input id="component-code" value={form.component_code} onChange={(event) => setForm((current) => ({ ...current, component_code: event.target.value.toUpperCase() }))} placeholder="P1" required />
              </div>
              <div className="space-y-2">
                <Label htmlFor="component-max-score">Maximum score</Label>
                <Input id="component-max-score" type="number" min="0.01" step="0.01" value={form.max_score} onChange={(event) => setForm((current) => ({ ...current, max_score: event.target.value }))} required />
              </div>
              <div className="space-y-2">
                <Label htmlFor="component-weight">Weight (%)</Label>
                <Input id="component-weight" type="number" min="0.01" max="100" step="0.01" value={form.weight} onChange={(event) => setForm((current) => ({ ...current, weight: event.target.value }))} required />
              </div>
            </div>
            {formError ? <p role="alert" className="text-sm font-medium text-destructive">{formError}</p> : null}
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose} disabled={saving}>Cancel</Button>
            <Button type="submit" disabled={saving}>
              {saving ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
              Save component
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

export function PapersComponentsWorkspace({ model }: { model: unknown }) {
  void model;
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [savingAction, setSavingAction] = useState<string | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [selectedComponent, setSelectedComponent] = useState<AssessmentComponentRow | null>(null);
  const { data: componentsResponse, isLoading, error, refetch } = useSchoolQuery<ApiResponse<AssessmentComponentRow[]> | AssessmentComponentRow[]>("/exams/assessment-components");
  const { data: assessmentsResponse } = useSchoolQuery<ApiResponse<AssessmentRow[]> | AssessmentRow[]>("/exams/assessments");
  const components = readRows(componentsResponse);
  const assessments = readRows(assessmentsResponse);

  function openCreate(component: AssessmentComponentRow | null = null) {
    setSelectedComponent(component);
    setDialogOpen(true);
  }

  async function saveComponent(value: ComponentFormValue) {
    const editing = Boolean(selectedComponent?.id);
    const endpoint = editing
      ? `/api/exams/assessment-components/${encodeURIComponent(selectedComponent!.id!)}`
      : "/api/exams/assessment-components";
    await requestDashboardApi(endpoint, {
      method: editing ? "PATCH" : "POST",
      body: {
        ...value,
        max_score: Number(value.max_score),
        weight: Number(value.weight),
      },
    });
    await refetch();
    setNotice(`${value.component_name} ${editing ? "updated" : "created"}.`);
  }

  async function duplicateComponent(row: AssessmentComponentRow) {
    setSavingAction(`duplicate:${row.id ?? row.component_code}`);
    try {
      await requestDashboardApi("/api/exams/assessment-components", {
        method: "POST",
        body: {
          assessment_id: row.assessment_id,
          component_name: `${row.component_name} Copy`,
          component_code: `${row.component_code}-COPY-${Date.now().toString().slice(-5)}`,
          max_score: Number(row.max_score),
          weight: Number(row.weight),
        },
      });
      await refetch();
      setNotice(`${row.component_name} duplicated and saved.`);
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Could not duplicate the component.");
    } finally {
      setSavingAction(null);
    }
  }

  async function deleteComponent(row: AssessmentComponentRow) {
    if (!row.id || !window.confirm(`Delete ${row.component_name}? Existing marks that depend on this component may block deletion.`)) return;
    setSavingAction(`delete:${row.id}`);
    try {
      await requestDashboardApi(`/api/exams/assessment-components/${encodeURIComponent(row.id)}`, { method: "DELETE" });
      await refetch();
      setNotice(`${row.component_name} deleted.`);
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Could not delete the component.");
    } finally {
      setSavingAction(null);
    }
  }

  async function importComponents(file: File | null | undefined) {
    if (!file) return;
    setSavingAction("import");
    try {
      const lines = (await file.text()).replace(/^\uFEFF/, "").split(/\r?\n/).filter((line) => line.trim());
      if (lines.length < 2) throw new Error("The CSV must include a header and at least one component row.");
      const headers = parseCsvLine(lines[0]).map((value) => value.toLowerCase());
      const requiredHeaders = ["assessment_id", "component_code", "component_name", "max_score", "weight"];
      const missingHeaders = requiredHeaders.filter((header) => !headers.includes(header));
      if (missingHeaders.length) throw new Error(`Missing CSV columns: ${missingHeaders.join(", ")}.`);

      let imported = 0;
      const failures: string[] = [];
      for (let index = 1; index < lines.length; index += 1) {
        const values = parseCsvLine(lines[index]);
        const row = Object.fromEntries(headers.map((header, column) => [header, values[column] ?? ""]));
        try {
          await requestDashboardApi("/api/exams/assessment-components", {
            method: "POST",
            body: {
              assessment_id: row.assessment_id,
              component_code: row.component_code,
              component_name: row.component_name,
              max_score: Number(row.max_score),
              weight: Number(row.weight),
            },
          });
          imported += 1;
        } catch (error) {
          failures.push(`row ${index + 1}: ${error instanceof Error ? error.message : "save failed"}`);
        }
      }
      await refetch();
      setNotice(failures.length
        ? `Imported ${imported} component(s). ${failures.length} failed: ${failures.slice(0, 3).join("; ")}`
        : `Imported ${imported} component(s) from ${file.name}.`);
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Could not import assessment components.");
    } finally {
      setSavingAction(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col items-start justify-between gap-4 sm:flex-row sm:items-center">
        <PageHeader eyebrow="Exam Setup" title="Papers & Components" description="Configure paper structures, score ceilings, and assessment weighting." />
        <div className="flex flex-wrap gap-2">
          <Button variant="outline" disabled={Boolean(savingAction)} onClick={() => fileInputRef.current?.click()}><Upload className="mr-2 h-4 w-4" /> Import CSV</Button>
          <input ref={fileInputRef} className="hidden" type="file" accept=".csv,text/csv" onChange={(event) => void importComponents(event.target.files?.[0])} />
          <Button variant="outline" disabled={components.length === 0 || Boolean(savingAction)} onClick={() => { const first = components[0]; if (first) openCreate({ ...first, id: undefined, component_name: `${first.component_name} Copy`, component_code: `${first.component_code}-COPY` }); }}><Copy className="mr-2 h-4 w-4" /> Copy Structure</Button>
          <Button variant="outline" disabled={Boolean(savingAction)} onClick={() => fileInputRef.current?.click()}><Settings className="mr-2 h-4 w-4" /> Bulk Configure</Button>
          <Button disabled={Boolean(savingAction) || assessments.length === 0} onClick={() => openCreate()}><Plus className="mr-2 h-4 w-4" /> Add Component</Button>
        </div>
      </div>

      {notice ? <div role="status" className="rounded-md border border-blue-200 bg-blue-50 p-3 text-sm font-semibold text-blue-900">{notice}</div> : null}
      {assessments.length === 0 && !isLoading ? <div className="rounded-md border border-amber-200 bg-amber-50 p-3 text-sm text-amber-950">Create an exam assessment before adding paper components.</div> : null}

      <Card className="overflow-hidden p-0">
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Assessment</TableHead>
                <TableHead>Component</TableHead>
                <TableHead>Code</TableHead>
                <TableHead>Maximum score</TableHead>
                <TableHead>Weight</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? <TableRow><TableCell colSpan={7} className="py-10 text-center"><Loader2 className="mx-auto mb-2 h-6 w-6 animate-spin text-muted-foreground" />Loading components...</TableCell></TableRow> : null}
              {error ? <TableRow><TableCell colSpan={7} className="py-10 text-center text-destructive">Error loading components: {error.message}</TableCell></TableRow> : null}
              {!isLoading && !error && components.length === 0 ? <TableRow><TableCell colSpan={7} className="py-10 text-center text-muted-foreground">No paper components exist yet. Add a component or import a CSV to configure the first assessment.</TableCell></TableRow> : null}
              {!isLoading && !error ? components.map((row) => (
                <TableRow key={row.id ?? `${row.assessment_id}-${row.component_code}`}>
                  <TableCell className="font-medium">{assessments.find((assessment) => assessment.id === row.assessment_id)?.name ?? row.assessment_id}</TableCell>
                  <TableCell>{row.component_name}</TableCell>
                  <TableCell>{row.component_code}</TableCell>
                  <TableCell>{row.max_score}</TableCell>
                  <TableCell>{row.weight}%</TableCell>
                  <TableCell><Badge variant="outline">Configured</Badge></TableCell>
                  <TableCell className="text-right">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild><Button variant="ghost" size="icon" aria-label={`Actions for ${row.component_name}`}><MoreHorizontal className="h-4 w-4" /></Button></DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => openCreate(row)}><Edit className="mr-2 h-4 w-4" /> Edit Component</DropdownMenuItem>
                        <DropdownMenuItem disabled={Boolean(savingAction)} onClick={() => void duplicateComponent(row)}><Copy className="mr-2 h-4 w-4" /> Duplicate</DropdownMenuItem>
                        <DropdownMenuItem className="text-destructive" disabled={!row.id || Boolean(savingAction)} onClick={() => void deleteComponent(row)}><Trash2 className="mr-2 h-4 w-4" /> Delete</DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              )) : null}
            </TableBody>
          </Table>
        </div>
      </Card>

      <ComponentDialog open={dialogOpen} component={selectedComponent} assessments={assessments} onClose={() => setDialogOpen(false)} onSave={saveComponent} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { DataTable } from "@/components/ui/data-table";
import { toast } from "sonner";
import { Card } from "@/components/ui/card";

interface MarksEntryTableProps {
  tenantId?: string;
  examSeriesId: string;
  assessmentId: string;
  classSectionId: string;
  subjectId: string;
  academicTermId: string;
}

export function MarksEntryTable({
  tenantId,
  examSeriesId,
  assessmentId,
  classSectionId,
  subjectId,
  academicTermId,
}: MarksEntryTableProps) {
  const queryClient = useQueryClient();
  const [editingStudentId, setEditingStudentId] = useState<string | null>(null);
  const [editScore, setEditScore] = useState<string>("");

  const marksQuery = useQuery({
    queryKey: ["exam-marks", tenantId, examSeriesId, subjectId, classSectionId],
    queryFn: async () => {
      const res = await fetch(`/api/exams/marks?exam_series_id=${examSeriesId}&subject_id=${subjectId}&class_section_id=${classSectionId}${tenantId ? `&tenant_id=${tenantId}` : ""}`);
      if (!res.ok) throw new Error("Failed to load marks");
      return res.json();
    },
  });

  const enterMarkMutation = useMutation({
    mutationFn: async ({ studentId, score }: { studentId: string; score: number }) => {
      const res = await fetch(`/api/exams/marks/enter`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          exam_series_id: examSeriesId,
          assessment_id: assessmentId,
          academic_term_id: academicTermId,
          class_section_id: classSectionId,
          subject_id: subjectId,
          student_id: studentId,
          score,
          tenant_id: tenantId,
        }),
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.message || "Failed to save mark");
      }
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["exam-marks", tenantId, examSeriesId, subjectId, classSectionId] });
      setEditingStudentId(null);
      setEditScore("");
    },
    onError: (err: any) => {
      toast.error(`Error saving mark: ${err.message}`);
    }
  });

  const handleSave = (studentId: string) => {
    const score = Number(editScore);
    if (isNaN(score) || score < 0) {
      toast.error("Please enter a valid positive number for the score.");
      return;
    }
    enterMarkMutation.mutate({ studentId, score });
  };

  return (
    <Card className="p-5 space-y-4">
      <h3 className="font-semibold text-lg text-foreground">Marks Entry</h3>
      {marksQuery.isLoading ? (
        <div className="h-32 flex items-center justify-center border rounded-[var(--radius)]">Loading marks...</div>
      ) : (
        <DataTable
          columns={[
            { id: "student", header: "Student", render: (row: any) => row.student_name || row.student_id },
            { 
              id: "score", 
              header: "Score", 
              render: (row: any) => {
                if (editingStudentId === row.student_id) {
                  return (
                    <div className="flex items-center gap-2">
                      <input 
                        type="number" 
                        value={editScore}
                        onChange={(e) => setEditScore(e.target.value)}
                        className="input-base w-20"
                      />
                      <Button size="sm" onClick={() => handleSave(row.student_id)} disabled={enterMarkMutation.isPending}>Save</Button>
                      <Button size="sm" variant="ghost" onClick={() => setEditingStudentId(null)}>Cancel</Button>
                    </div>
                  );
                }
                return row.score ?? "-";
              }
            },
            {
              id: "status",
              header: "Status",
              render: (row: any) => row.status || "Draft"
            },
            {
              id: "actions",
              header: "Actions",
              render: (row: any) => (
                <Button 
                  size="sm" 
                  variant="outline" 
                  onClick={() => {
                    setEditingStudentId(row.student_id);
                    setEditScore(row.score?.toString() || "");
                  }}
                  disabled={row.status === "locked" || row.status === "published" || row.status === "reviewed"}
                >
                  Edit
                </Button>
              )
            }
          ]}
          rows={marksQuery.data?.items || []}
          getRowKey={(row: any) => row.id || row.student_id}
        />
      )}
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

interface ReportCardGeneratorProps {
  tenantId?: string;
  examSeriesId: string;
}

export function ReportCardGenerator({ tenantId, examSeriesId }: ReportCardGeneratorProps) {
  const queryClient = useQueryClient();
  const [generateError, setGenerateError] = useState<string | null>(null);

  const readinessQuery = useQuery({
    queryKey: ["exam-readiness", tenantId, examSeriesId],
    queryFn: async () => {
      const res = await fetch(`/api/exams/series/${examSeriesId}/readiness${tenantId ? `?tenant_id=${tenantId}` : ""}`);
      if (!res.ok) throw new Error("Failed to load readiness status");
      return res.json();
    },
  });

  const generateMutation = useMutation({
    mutationFn: async () => {
      setGenerateError(null);
      const res = await fetch(`/api/exams/series/publish`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          exam_series_id: examSeriesId,
          tenant_id: tenantId,
        }),
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.message || "Failed to generate report cards");
      }
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["exam-readiness", tenantId, examSeriesId] });
      toast.success("Report-card publishing request accepted. Refresh readiness to confirm generated artifacts and parent portal visibility.");
    },
    onError: (err: any) => {
      setGenerateError(err.message);
    }
  });

  if (readinessQuery.isLoading) return <div>Checking exam readiness...</div>;
  if (readinessQuery.isError) return <div className="text-red-500">Error loading readiness.</div>;

  const readiness = readinessQuery.data;

  return (
    <div className="space-y-4 bg-white p-6 rounded shadow border">
      <h3 className="font-semibold text-lg">Generate Report Cards</h3>

      {!readiness.ready ? (
        <div className="bg-red-50 p-4 border border-red-200 rounded text-red-800">
          <p className="font-medium mb-2">Exam Series is NOT ready for publishing.</p>
          <ul className="list-disc ml-5 text-sm space-y-1">
            {readiness.issues.map((issue: string, idx: number) => (
              <li key={idx}>{issue}</li>
            ))}
          </ul>
        </div>
      ) : (
        <div className="bg-green-50 p-4 border border-green-200 rounded text-green-800">
          <p className="font-medium">All marks are approved. The exam series is ready for report card generation.</p>
        </div>
      )}

      {generateError && (
        <div className="text-red-600 text-sm mt-2 font-medium">
          Error: {generateError}
        </div>
      )}

      <div className="pt-4 border-t">
        <Button 
          onClick={() => generateMutation.mutate()} 
          disabled={!readiness.ready || generateMutation.isPending}
          className="w-full sm:w-auto"
        >
          {generateMutation.isPending ? "Generating..." : "Generate & Publish Report Cards"}
        </Button>
        <p className="text-xs text-gray-500 mt-2">
          This action will lock all marks and publish report cards to the parent portal after backend generation completes.
        </p>
      </div>
    </div>
  );
}

