        throw new Error(
          payload && "message" in payload && payload.message
            ? payload.message
            : "Reconciliation export could not be prepared.",
        );
      }

      downloadTextFile({
        filename: payload.filename,
        content: payload.csv,
        mimeType: payload.content_type,
