"use client";

import { useEffect, useState } from "react";
import { SchoolExperienceRole } from "@/lib/experiences/school-data";
import { SchoolPageHeader } from "@/components/school/school-page-header";
import { DataTable } from "@/components/ui/data-table";
import { Button } from "@/components/ui/button";
import { Modal } from "@/components/ui/modal";
import { buildBillingApiPath, toMinorUnits } from "@/lib/billing/billing-utils";
import { StatusPill } from "@/components/ui/status-pill";
import { requestDashboardApi } from "@/lib/dashboard/api-client";

type SchoolRouteMode = "hosted" | "public";

export function WaiversDiscountsWorkspace({
  role,
  tenantSlug,
}: {
  role: SchoolExperienceRole;
  tenantSlug?: string | null;
  routeMode?: SchoolRouteMode;
  activeSection?: string;
}) {
  const [waivers, setWaivers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const [showModal, setShowModal] = useState(false);
  const [formDraft, setFormDraft] = useState({ studentId: "", amount: "", reason: "" });
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  async function loadWaivers() {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(
        buildBillingApiPath("/api/billing/waivers", tenantSlug),
        { cache: "no-store" }
      );

      if (!response.ok) {
        throw new Error("Unable to load fee waivers for this school.");
      }

      const data = await response.json();
      setWaivers(Array.isArray(data) ? data : data?.items ?? data?.waivers ?? []);
    } catch (e: any) {
      setError(e.message || "An error occurred");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadWaivers();
  }, [tenantSlug]);

  async function handleApplyWaiver(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!formDraft.studentId || !formDraft.amount || !formDraft.reason) {
      setSubmitError("Please fill out all fields.");
      return;
    }
    const amountMinor = toMinorUnits(formDraft.amount);
    if (!amountMinor) {
      setSubmitError("Enter a valid waiver amount greater than zero.");
      return;
    }
    setSubmitError(null);
    setSubmitting(true);

    try {
      const response = await requestDashboardApi<{ message?: string; waiver?: any; request?: any }>("/finance/waivers", {
        method: "POST",
        body: {
          student_id: formDraft.studentId.trim(),
          student_name: formDraft.studentId.trim(),
          amount_minor: amountMinor,
          reason: formDraft.reason.trim(),
          source_dashboard: "accountant-waivers-discounts-workspace",
        },
      });

      setShowModal(false);
      setFormDraft({ studentId: "", amount: "", reason: "" });
      await loadWaivers();
      setNotice(response?.message ?? "Fee waiver request submitted.");
    } catch (e: any) {
      setSubmitError(e.message || "Failed to submit fee waiver request.");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="space-y-6">
      <SchoolPageHeader
        eyebrow="Accountant"
        title="Waivers & Discounts"
        description="Manage fee waivers, discounts, and bursary allocations."
        actions={
          <Button onClick={() => setShowModal(true)} disabled={loading}>
            Apply Waiver
          </Button>
        }
      />

      <div className="rounded-md border border-slate-200 bg-white p-6 shadow-sm">
        {notice ? (
          <div className="mb-4 rounded-md bg-emerald-50 p-4 text-sm text-emerald-700">
            {notice}
          </div>
        ) : null}
        {error ? (
          <div className="rounded-md bg-red-50 p-4 text-sm text-red-600">
            {error}
          </div>
        ) : (
          <DataTable
            rows={waivers}
            getRowKey={(row: any) => row.id || `${row.created_at}-${row.student_name}-${row.amount}`}
            columns={[
              { id: "created_at", header: "Date", render: (row: any) => row.created_at },
              { id: "student_name", header: "Student", render: (row: any) => row.student_name },
              { id: "amount", header: "Amount", render: (row: any) => row.amount },
              { id: "reason", header: "Reason", render: (row: any) => row.reason },
              {
                id: "status",
                header: "Status",
                render: (row: any) => <StatusPill tone={row.status === "approved" ? "ok" : "warning"} label={row.status} />,
              },
            ]}
            emptyMessage="No waivers or discounts found."
          />
        )}
      </div>

      <Modal open={showModal} onClose={() => setShowModal(false)} title="Apply Fee Waiver">
        <form onSubmit={handleApplyWaiver} className="space-y-4 py-4">
          {submitError && (
            <div className="rounded bg-red-50 p-3 text-sm text-red-600">
              {submitError}
            </div>
          )}

          <div className="space-y-1">
            <label className="text-sm font-medium">Student ID / Name</label>
            <input
              type="text"
              className="w-full rounded border border-slate-300 p-2 text-sm"
              value={formDraft.studentId}
              onChange={(e) => setFormDraft({ ...formDraft, studentId: e.target.value })}
              placeholder="e.g. STU-123"
            />
          </div>

          <div className="space-y-1">
            <label className="text-sm font-medium">Amount (KES)</label>
            <input
              type="number"
              className="w-full rounded border border-slate-300 p-2 text-sm"
              value={formDraft.amount}
              onChange={(e) => setFormDraft({ ...formDraft, amount: e.target.value })}
              placeholder="0.00"
            />
          </div>

          <div className="space-y-1">
            <label className="text-sm font-medium">Reason</label>
            <textarea
              className="w-full rounded border border-slate-300 p-2 text-sm"
              value={formDraft.reason}
              onChange={(e) => setFormDraft({ ...formDraft, reason: e.target.value })}
              placeholder="e.g. Merit scholarship"
              rows={3}
            />
          </div>

          <div className="flex justify-end space-x-3 pt-4 border-t border-slate-100">
            <Button type="button" variant="outline" onClick={() => setShowModal(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={submitting}>
              {submitting ? "Applying..." : "Apply Waiver"}
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { useState } from "react";
import { BookOpen, Layers, Calendar, Plus, Settings2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";

export function ClassesStreamsWorkspace() {
  const [activeTab, setActiveTab] = useState<"sections" | "years">("sections");

  const { data: yearsList, refetch: refetchYears } = useSchoolQuery<any[]>("/api/academics/academic-years", { enabled: activeTab === "years" });
  const { data: termsList, refetch: refetchTerms } = useSchoolQuery<any[]>("/api/academics/academic-terms", { enabled: activeTab === "years" });
  const { data: classSectionsList, refetch: refetchSections } = useSchoolQuery<any[]>("/api/academics/class-sections", { enabled: activeTab === "sections" });

  const createYearMutation = useSchoolMutation("/api/academics/years");
  const createTermMutation = useSchoolMutation("/api/academics/terms");
  const createSectionMutation = useSchoolMutation("/api/academics/class-sections");

  const [newYearName, setNewYearName] = useState("");
  const [newYearStart, setNewYearStart] = useState("");
  const [newYearEnd, setNewYearEnd] = useState("");

  const handleCreateYear = async () => {
    if (!newYearName || !newYearStart || !newYearEnd) return;
    await createYearMutation.mutateAsync({ name: newYearName, starts_on: newYearStart, ends_on: newYearEnd });
    setNewYearName(""); setNewYearStart(""); setNewYearEnd("");
    refetchYears();
  };

  const [newSecName, setNewSecName] = useState("");
  const [newSecGrade, setNewSecGrade] = useState("");
  const [newSecCapacity, setNewSecCapacity] = useState(30);

  const handleCreateSection = async () => {
    if (!newSecName || !newSecGrade) return;
    // Assuming academic_year_id is required. We'll grab the first year or empty for now if no years exist.
    // In a real app, there'd be a dropdown for the current academic year.
    const yearId = yearsList?.[0]?.id || "";
    await createSectionMutation.mutateAsync({ 
      academic_year_id: yearId, 
      name: newSecName, 
      grade_level: newSecGrade, 
      capacity: newSecCapacity 
    });
    setNewSecName(""); setNewSecGrade(""); setNewSecCapacity(30);
    refetchSections();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 tracking-tight">Classes & Streams</h2>
          <p className="text-sm text-slate-500 mt-1">Manage academic structure, years, terms, and classes.</p>
        </div>
      </div>

      <div className="flex items-center gap-2 border-b border-slate-200 pb-0">
        <button
          onClick={() => setActiveTab("sections")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "sections" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <Layers className="w-4 h-4" />
          Class Sections
        </button>
        <button
          onClick={() => setActiveTab("years")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "years" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <Calendar className="w-4 h-4" />
          Academic Calendar
        </button>
      </div>

      {activeTab === "sections" && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <Card className="p-4 border border-slate-200">
              <h3 className="font-medium text-slate-900 mb-4 flex items-center gap-2">
                <Plus className="w-4 h-4" />
                Add Class Section
              </h3>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Name</label>
                  <input 
                    type="text" 
                    placeholder="e.g. Form 1 East"
                    value={newSecName} onChange={e => setNewSecName(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Grade Level</label>
                  <input 
                    type="text" 
                    placeholder="e.g. Form 1"
                    value={newSecGrade} onChange={e => setNewSecGrade(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Capacity</label>
                  <input 
                    type="number" 
                    value={newSecCapacity} onChange={e => setNewSecCapacity(Number(e.target.value))}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <Button onClick={handleCreateSection} disabled={createSectionMutation.isPending || !newSecName || !newSecGrade} className="w-full">
                  Create Class
                </Button>
              </div>
            </Card>
          </div>
          <div className="lg:col-span-2">
            <Card className="border border-slate-200 overflow-hidden">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-3 font-medium">Name</th>
                    <th className="px-4 py-3 font-medium">Grade</th>
                    <th className="px-4 py-3 font-medium">Capacity</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {classSectionsList?.length === 0 ? (
                    <tr><td colSpan={3} className="px-4 py-8 text-center text-slate-500">No classes defined yet.</td></tr>
                  ) : (
                    classSectionsList?.map((sec: any) => (
                      <tr key={sec.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-4 py-3 font-medium text-slate-900">{sec.name}</td>
                        <td className="px-4 py-3">{sec.grade_level}</td>
                        <td className="px-4 py-3 text-slate-500">{sec.capacity || 'Not set'}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </Card>
          </div>
        </div>
      )}

      {activeTab === "years" && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <Card className="p-4 border border-slate-200">
              <h3 className="font-medium text-slate-900 mb-4 flex items-center gap-2">
                <Plus className="w-4 h-4" />
                Add Academic Year
              </h3>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Year Name</label>
                  <input 
                    type="text" 
                    placeholder="e.g. 2026-2027"
                    value={newYearName} onChange={e => setNewYearName(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-700">Starts On</label>
                    <input 
                      type="date" 
                      value={newYearStart} onChange={e => setNewYearStart(e.target.value)}
                      className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-700">Ends On</label>
                    <input 
                      type="date" 
                      value={newYearEnd} onChange={e => setNewYearEnd(e.target.value)}
                      className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                    />
                  </div>
                </div>
                <Button onClick={handleCreateYear} disabled={createYearMutation.isPending || !newYearName || !newYearStart || !newYearEnd} className="w-full">
                  Create Year
                </Button>
              </div>
            </Card>
          </div>
          <div className="lg:col-span-2 space-y-4">
            <Card className="border border-slate-200 overflow-hidden">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-3 font-medium">Academic Year</th>
                    <th className="px-4 py-3 font-medium">Starts On</th>
                    <th className="px-4 py-3 font-medium">Ends On</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {yearsList?.length === 0 ? (
                    <tr><td colSpan={3} className="px-4 py-8 text-center text-slate-500">No academic years defined yet.</td></tr>
                  ) : (
                    yearsList?.map((yr: any) => (
                      <tr key={yr.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-4 py-3 font-medium text-slate-900">{yr.name}</td>
                        <td className="px-4 py-3">{new Date(yr.starts_on).toLocaleDateString()}</td>
                        <td className="px-4 py-3">{new Date(yr.ends_on).toLocaleDateString()}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </Card>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { AlertTriangle, CheckCircle, Search, ArrowRight, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { requestDashboardApi } from "@/lib/dashboard/api-client";

type DataQualityAnomaly = {
  id?: string;
  severity?: "critical" | "warning" | string;
  title?: string;
  module?: string;
  count?: number;
};

export function DataQualityWorkspace() {
  const { data: insightsData, isLoading } = useSchoolQuery<any>("/api/ai-insights/dashboard");
  const [scanBusy, setScanBusy] = useState(false);
  const [fixingId, setFixingId] = useState<string | null>(null);

  const anomalies: DataQualityAnomaly[] = insightsData?.items || [];
  const criticalCount = anomalies.filter((a) => a.severity === "critical").length;
  const warningCount = anomalies.filter((a) => a.severity === "warning").length;
  const score = Math.max(0, 100 - (criticalCount * 2) - (warningCount * 0.5));

  const runFullScan = async () => {
    setScanBusy(true);
    try {
      await requestDashboardApi("/admin-command/principal/reports/generate", {
        method: "POST",
        body: {
          title: "Data quality full scan",
          type: "data_quality_full_scan",
          source_dashboard: "admin-data-quality",
          filters: {
            current_score: score,
            critical_count: criticalCount,
            warning_count: warningCount,
            anomaly_count: anomalies.length,
          },
        },
      });
      toast.success("Data quality scan requested. The generated report will be available in principal reports.");
    } catch (error: any) {
      toast.error(error?.message || "Failed to request data quality scan.");
    } finally {
      setScanBusy(false);
    }
  };

  const requestAnomalyFix = async (anomaly: DataQualityAnomaly) => {
    const anomalyId = anomaly.id || `${anomaly.module || "system"}-${anomaly.title || "anomaly"}`;
    setFixingId(anomalyId);
    try {
      await requestDashboardApi("/admin-command/principal/settings/action", {
        method: "POST",
        body: {
          action: "data_quality_fix_requested",
          title: "Data quality fix requested",
          message: `Fix requested for ${anomaly.title || "a detected data quality anomaly"}.`,
          source_dashboard: "admin-data-quality",
          anomaly_id: anomalyId,
          module: anomaly.module || "System",
          severity: anomaly.severity || "warning",
          affected_records: anomaly.count || 1,
          payload: anomaly,
        },
      });
      toast.success("Fix request recorded and sent to the principal/system monitor workflow.");
    } catch (error: any) {
      toast.error(error?.message || "Failed to request anomaly fix.");
    } finally {
      setFixingId(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 tracking-tight">Data Quality & Audit</h2>
          <p className="text-sm text-slate-500 mt-1">Identify and resolve missing information and operational anomalies.</p>
        </div>
        <div className="flex items-center gap-3">
          <Button variant="outline" className="gap-2" onClick={runFullScan} disabled={scanBusy || isLoading}>
            {scanBusy ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
            {scanBusy ? "Requesting Scan..." : "Run Full Scan"}
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card className="p-6 border border-slate-200">
          <div className="flex items-center justify-between mb-2">
            <h3 className="font-medium text-slate-900">Overall Health</h3>
            <CheckCircle className="w-5 h-5 text-emerald-500" />
          </div>
          <div className="text-3xl font-semibold text-slate-900 mb-1">
            {isLoading ? <span className="animate-pulse bg-slate-200 h-8 w-16 block rounded"></span> : `${score}%`}
          </div>
          <p className="text-sm text-slate-500">Data completeness score</p>
        </Card>
        
        <Card className="p-6 border border-slate-200 bg-rose-50/50">
          <div className="flex items-center justify-between mb-2">
            <h3 className="font-medium text-slate-900">Critical Issues</h3>
            <AlertTriangle className="w-5 h-5 text-rose-500" />
          </div>
          <div className="text-3xl font-semibold text-rose-600 mb-1">
             {isLoading ? <span className="animate-pulse bg-rose-200 h-8 w-16 block rounded"></span> : criticalCount}
          </div>
          <p className="text-sm text-rose-600/80">Requires immediate attention</p>
        </Card>

        <Card className="p-6 border border-slate-200 bg-orange-50/50">
          <div className="flex items-center justify-between mb-2">
            <h3 className="font-medium text-slate-900">Warnings</h3>
            <AlertTriangle className="w-5 h-5 text-orange-500" />
          </div>
          <div className="text-3xl font-semibold text-orange-600 mb-1">
             {isLoading ? <span className="animate-pulse bg-orange-200 h-8 w-16 block rounded"></span> : warningCount}
          </div>
          <p className="text-sm text-orange-600/80">Recommended to fix</p>
        </Card>
      </div>

      <Card className="border border-slate-200 overflow-hidden mt-6">
        <div className="p-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
          <h3 className="font-medium text-slate-900">Detected Anomalies</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-slate-500 uppercase border-b border-slate-200">
              <tr>
                <th className="px-4 py-3 font-medium min-w-[200px]">Issue</th>
                <th className="px-4 py-3 font-medium">Module</th>
                <th className="px-4 py-3 font-medium">Affected Records</th>
                <th className="px-4 py-3 font-medium text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr>
                  <td colSpan={4} className="px-4 py-8 text-center text-slate-500 animate-pulse">Loading anomalies...</td>
                </tr>
              ) : anomalies.length > 0 ? anomalies.map((anomaly) => {
                const anomalyId = anomaly.id || `${anomaly.module || "system"}-${anomaly.title || "anomaly"}`;
                return (
                <tr key={anomalyId} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      <AlertTriangle className={`w-4 h-4 shrink-0 ${anomaly.severity === "critical" ? "text-rose-500" : "text-orange-500"}`} />
                      <span className="font-medium text-slate-900">{anomaly.title}</span>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-slate-500">
                    <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-700">
                      {anomaly.module || 'System'}
                    </span>
                  </td>
                  <td className="px-4 py-3 font-medium text-slate-900">{anomaly.count || 1}</td>
                  <td className="px-4 py-3 text-right">
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-8 gap-1 text-slate-600 hover:text-slate-900"
                      onClick={() => requestAnomalyFix(anomaly)}
                      disabled={fixingId === anomalyId}
                    >
                      {fixingId === anomalyId ? "Recording..." : "Fix Now"}
                      {fixingId === anomalyId ? <Loader2 className="w-3 h-3 animate-spin" /> : <ArrowRight className="w-3 h-3" />}
                    </Button>
                  </td>
                </tr>
                );
              }) : (
                <tr>
                  <td colSpan={4} className="px-4 py-8 text-center text-emerald-600 font-medium">
                    <CheckCircle className="w-8 h-8 text-emerald-500 mx-auto mb-2" />
                    No anomalies found!
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}

