import { useState, useEffect } from "react";
import { ClipboardCheck } from "lucide-react";
import { Panel } from "../shared";
import { useClassTeacherAttendance, useResolvedClassTeacherStreamId, useSaveAttendance } from "@/lib/data/class-teacher-hooks";

export function AttendanceWorkspace() {
  const { streamId } = useResolvedClassTeacherStreamId();
  const { data, isLoading, error } = useClassTeacherAttendance(streamId);
  const saveMutation = useSaveAttendance();
  const [localData, setLocalData] = useState<any[]>([]);

  useEffect(() => {
    if (data) setLocalData(Array.isArray(data) ? data : (data as any).records || []);
  }, [data]);

  if (isLoading) {
    return (
      <Panel title="Attendance" description="Daily class roll call. This is one of the most important Class Teacher tasks." icon={ClipboardCheck}>
        <div className="flex justify-center p-12"><div className="h-8 w-8 animate-spin rounded-full border-4 border-[#1D4ED8] border-t-transparent"></div></div>
      </Panel>
    );
  }

  if (error || !data) {
    return (
      <Panel title="Attendance" description="Daily class roll call. This is one of the most important Class Teacher tasks." icon={ClipboardCheck}>
        <div className="rounded-xl border border-rose-200 bg-rose-50 p-4 text-rose-700 font-bold">Failed to load attendance.</div>
      </Panel>
    );
  }

  const handleStatusChange = (id: string, newStatus: string) => {
    setLocalData(prev => prev.map(item => item.id === id ? { ...item, attendance: newStatus } : item));
  };

  const handleReasonChange = (id: string, newReason: string) => {
    setLocalData(prev => prev.map(item => item.id === id ? { ...item, reason: newReason } : item));
  };

  const handleMarkAllPresent = () => {
    setLocalData(prev => prev.map(item => ({ ...item, attendance: "present", reason: "" })));
  };

  const handleSubmit = () => {
    saveMutation.mutate({ streamId, records: localData });
  };

  return (
    <Panel title="Attendance" description="Daily class roll call. This is one of the most important Class Teacher tasks." icon={ClipboardCheck}>
      <div className="mb-4 flex gap-2">
        <button onClick={handleMarkAllPresent} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white">Mark All Present</button>
        <button onClick={handleSubmit} disabled={saveMutation.isPending} className="rounded-lg border border-transparent bg-emerald-600 px-4 py-2 text-sm font-black text-white disabled:opacity-50">
          {saveMutation.isPending ? "Submitting..." : "Submit Final"}
        </button>
      </div>
      {saveMutation.isSuccess && (
        <div className={`mb-4 rounded border p-2 text-sm font-bold ${
          (saveMutation.data as any)?._offline 
            ? "border-yellow-200 bg-yellow-50 text-yellow-700" 
            : "border-emerald-200 bg-emerald-50 text-emerald-700"
        }`}>
          {(saveMutation.data as any)?._offline 
            ? "Attendance saved offline! It will sync automatically when connection returns." 
            : "Attendance saved successfully!"}
        </div>
      )}
      <div className="overflow-hidden rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-left text-sm text-[#071D49]">
          <thead className="bg-[#F8FAFC]">
            <tr>
              <th className="p-3 font-semibold">Adm No.</th>
              <th className="p-3 font-semibold">Name</th>
              <th className="p-3 font-semibold">Attendance</th>
              <th className="p-3 font-semibold">Reason</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {localData.map((record) => (
              <tr key={record.id}>
                <td className="p-3">{record.admissionNo}</td>
                <td className="p-3 font-bold">{record.name}</td>
                <td className="p-3">
                  <select 
                    value={record.attendance} 
                    onChange={(e) => handleStatusChange(record.id, e.target.value)}
                    className="rounded border border-[#D8E0EC] p-1 text-sm bg-white"
                  >
                    <option value="present">Present</option>
                    <option value="absent">Absent</option>
                    <option value="late">Late</option>
                  </select>
                </td>
                <td className="p-3">
                  <input 
                    type="text" 
                    value={record.reason}
                    onChange={(e) => handleReasonChange(record.id, e.target.value)}
                    className="w-full rounded border border-[#D8E0EC] p-1 text-sm" 
                    placeholder="e.g. sick" 
                    disabled={record.attendance === "present"}
                  />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

import { MessageCircle } from "lucide-react";
import { useState, type FormEvent } from "react";
import { Panel, StatusChip, sendClassTeacherCommunication } from "../shared";
import { useClassTeacherCommunication, useResolvedClassTeacherStreamId } from "@/lib/data/class-teacher-hooks";
import { usePermissions } from "@/components/providers/permission-context";
import { Modal } from "@/components/ui/modal";

type ComposerMode = "class_announcement" | "individual_parent";

function CreateAnnouncementModal({ mode, onClose }: { mode: ComposerMode; onClose: () => void }) {
  const [submitting, setSubmitting] = useState(false);
  const isIndividual = mode === "individual_parent";

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      const formData = new FormData(e.currentTarget);
      const sent = await sendClassTeacherCommunication({
        audience: mode,
        learnerId: String(formData.get("learnerId") || "").trim() || undefined,
        subject: String(formData.get("subject") || (isIndividual ? "Parent message" : "Class announcement")),
        message: String(formData.get("message") || ""),
        sendSms: formData.get("sendSms") === "on",
        source: "class-teacher-communication-workspace",
      });
      if (sent) onClose();
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Modal title={isIndividual ? "Send Parent Message" : "Add Class Announcement"} open={true} onClose={onClose} size="md">
      <form onSubmit={handleSubmit} className="p-6 space-y-4">
        {isIndividual ? (
          <div>
            <label className="block text-sm font-bold text-[#071D49] mb-1">Learner or guardian reference</label>
            <input name="learnerId" required className="w-full rounded-xl border border-[#D8E0EC] p-3 text-sm outline-none focus:border-[#071D49]" placeholder="Learner admission number, guardian name, or portal reference" />
          </div>
        ) : null}
        <div>
          <label className="block text-sm font-bold text-[#071D49] mb-1">Subject</label>
          <input name="subject" required className="w-full rounded-xl border border-[#D8E0EC] p-3 text-sm outline-none focus:border-[#071D49]" placeholder={isIndividual ? "Parent follow-up" : "Class announcement"} />
        </div>
        <div>
          <label className="block text-sm font-bold text-[#071D49] mb-1">Message</label>
          <textarea name="message" required rows={4} className="w-full rounded-xl border border-[#D8E0EC] p-3 text-sm outline-none focus:border-[#071D49]" placeholder={isIndividual ? "Write the parent message..." : "Write your announcement here..."}></textarea>
        </div>
        <div className="flex items-center gap-2">
          <input name="sendSms" type="checkbox" id="sms" className="h-4 w-4 rounded border-[#D8E0EC]" />
          <label htmlFor="sms" className="text-sm font-bold text-[#071D49]">Also send as SMS to Parents</label>
        </div>
        <div className="mt-6 flex justify-end gap-3 pt-4 border-t border-[#D8E0EC]">
          <button type="button" onClick={onClose} className="rounded-xl px-4 py-2 text-sm font-bold text-[#64748B]">Cancel</button>
          <button disabled={submitting} type="submit" className="rounded-xl bg-[#071D49] px-6 py-2 text-sm font-black text-white">
            {submitting ? "Sending..." : isIndividual ? "Send Message" : "Publish Announcement"}
          </button>
        </div>
      </form>
    </Modal>
  );
}

export function CommunicationWorkspace() {
  const { streamId } = useResolvedClassTeacherStreamId();
  const { hasPermission } = usePermissions();
  const [composerMode, setComposerMode] = useState<ComposerMode | null>(null);
  const { data, isLoading, error } = useClassTeacherCommunication(streamId);

  if (isLoading) {
    return (
      <Panel title="Parent Communication" description="Message history with parents of learners in your class." icon={MessageCircle}>
        <div className="flex justify-center p-12"><div className="h-8 w-8 animate-spin rounded-full border-4 border-[#1D4ED8] border-t-transparent"></div></div>
      </Panel>
    );
  }

  if (error || !data) {
    return (
      <Panel title="Parent Communication" description="Message history with parents of learners in your class." icon={MessageCircle}>
        <div className="rounded-xl border border-rose-200 bg-rose-50 p-4 text-rose-700 font-bold">Failed to load communication records.</div>
      </Panel>
    );
  }

  return (
    <Panel title="Parent Communication" description="Message history with parents of learners in your class." icon={MessageCircle}>
      <div className="mb-4 flex gap-2 justify-end">
         {hasPermission('school_communication:write') && (
           <button type="button" onClick={() => setComposerMode("class_announcement")} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white">Add Class Announcement</button>
         )}
         <button type="button" className="rounded-lg bg-[#1D4ED8] px-4 py-2 text-sm font-black text-white" onClick={() => setComposerMode("individual_parent")}>Send Individual Message</button>
      </div>
      <div className="overflow-hidden rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-left text-sm text-[#071D49]">
          <thead className="bg-[#F8FAFC]">
            <tr>
              <th className="p-3 font-semibold">Date</th>
              <th className="p-3 font-semibold">Recipient</th>
              <th className="p-3 font-semibold">Type</th>
              <th className="p-3 font-semibold">Message</th>
              <th className="p-3 font-semibold">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {(Array.isArray(data) ? data : []).map((row: any) => (
              <tr key={row.id}>
                <td className="p-3">{row.date}</td>
                <td className="p-3 font-bold">{row.recipient}</td>
                <td className="p-3">{row.type}</td>
                <td className="p-3 max-w-xs truncate">{row.message}</td>
                <td className="p-3"><StatusChip label={row.status} tone={row.status === 'Delivered' ? 'success' : 'neutral'}/></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {composerMode && <CreateAnnouncementModal mode={composerMode} onClose={() => setComposerMode(null)} />}
    </Panel>
  );
}

import { useState } from "react";
import { ShieldAlert } from "lucide-react";
import { Panel, StatusChip } from "../shared";
import { useClassTeacherDiscipline, useClassTeacherRegister, useReportDisciplineIncident, useResolvedClassTeacherStreamId } from "@/lib/data/class-teacher-hooks";

export function DisciplineWorkspace() {
  const { streamId } = useResolvedClassTeacherStreamId();
  const { data, isLoading, error } = useClassTeacherDiscipline(streamId);
  const { data: registerData, isLoading: isRegisterLoading } = useClassTeacherRegister(streamId);
  const reportMutation = useReportDisciplineIncident();

  const [showForm, setShowForm] = useState(false);
  const [selectedLearnerId, setSelectedLearnerId] = useState("");
  const [issue, setIssue] = useState("");
  const [severity, setSeverity] = useState("low");
  const learners = Array.isArray(registerData) ? registerData : [];

  if (isLoading) {
    return (
      <Panel title="Discipline & Behaviour" description="Track discipline issues originating from your class." icon={ShieldAlert}>
        <div className="flex justify-center p-12"><div className="h-8 w-8 animate-spin rounded-full border-4 border-[#1D4ED8] border-t-transparent"></div></div>
      </Panel>
    );
  }

  if (error || !data) {
    return (
      <Panel title="Discipline & Behaviour" description="Track discipline issues originating from your class." icon={ShieldAlert}>
        <div className="rounded-xl border border-rose-200 bg-rose-50 p-4 text-rose-700 font-bold">Failed to load discipline records.</div>
      </Panel>
    );
  }

  const handleReport = () => {
    if (!selectedLearnerId || !issue.trim()) return;

    reportMutation.mutate({
      streamId,
      payload: {
        studentId: selectedLearnerId,
        description: issue.trim(),
        severity
      }
    }, {
      onSuccess: () => {
        setShowForm(false);
        setSelectedLearnerId("");
        setIssue("");
        setSeverity("low");
      }
    });
  };

  return (
    <Panel title="Discipline & Behaviour" description="Track discipline issues originating from your class." icon={ShieldAlert}>
      <div className="mb-4 flex justify-end">
         <button onClick={() => setShowForm(!showForm)} className="rounded-lg bg-[#1D4ED8] px-4 py-2 text-sm font-black text-white">
           {showForm ? "Cancel" : "Log New Incident"}
         </button>
      </div>

      {reportMutation.isSuccess && <div className="mb-4 rounded border border-emerald-200 bg-emerald-50 p-2 text-sm text-emerald-700 font-bold">Discipline incident reported successfully!</div>}

      {showForm && (
        <div className="mb-6 rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <h3 className="mb-4 font-bold text-[#071D49]">New Discipline Incident</h3>
          <div className="flex flex-col gap-4">
            <label className="flex flex-col gap-1 text-xs font-black uppercase tracking-wide text-[#4B5563]">
              Learner
              <select className="rounded border border-[#D8E0EC] bg-white p-2 text-sm normal-case text-[#071D49]" value={selectedLearnerId} onChange={e => setSelectedLearnerId(e.target.value)}>
                <option value="">{isRegisterLoading ? "Loading learners..." : "Select learner"}</option>
                {learners.map((learner: any) => (
                  <option key={learner.id} value={String(learner.id)}>
                    {learner.name || learner.admissionNo || learner.id}
                  </option>
                ))}
              </select>
            </label>
            <textarea className="rounded border border-[#D8E0EC] p-2 text-sm" placeholder="Incident description" value={issue} onChange={e => setIssue(e.target.value)} />
            <select className="rounded border border-[#D8E0EC] p-2 text-sm bg-white" value={severity} onChange={e => setSeverity(e.target.value)}>
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
              <option value="critical">Critical</option>
            </select>
            <button onClick={handleReport} disabled={reportMutation.isPending || !selectedLearnerId || !issue.trim()} className="self-end rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white disabled:opacity-50">
              {reportMutation.isPending ? "Submitting..." : "Submit Report"}
            </button>
          </div>
        </div>
      )}

      <div className="overflow-hidden rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-left text-sm text-[#071D49]">
          <thead className="bg-[#F8FAFC]">
            <tr>
              <th className="p-3 font-semibold">Date</th>
              <th className="p-3 font-semibold">Learner</th>
              <th className="p-3 font-semibold">Issue</th>
              <th className="p-3 font-semibold">Severity</th>
              <th className="p-3 font-semibold">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {(Array.isArray(data) ? data : []).map((row: any) => (
              <tr key={row.id}>
                <td className="p-3">{row.date}</td>
                <td className="p-3 font-bold">{row.learner}</td>
                <td className="p-3">{row.issue}</td>
                <td className="p-3">
                  <span className={`rounded px-2 py-1 text-xs font-bold ${row.severity === 'Minor' ? 'bg-amber-100 text-amber-800' : 'bg-rose-100 text-rose-800'}`}>
                    {row.severity}
                  </span>
                </td>
                <td className="p-3"><StatusChip label={row.status} tone={row.status === 'Open' ? 'warning' : 'neutral'}/></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

