"use client";
import { useState, useEffect } from "react";
import { Settings } from "lucide-react";
import { Panel } from "./shared";

export function DeputySettingsWorkspace() {
  const [teachingEnabled, setTeachingEnabled] = useState(true);
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);

  useEffect(() => {
    // Load from local storage on mount
    const saved = localStorage.getItem("myshule_deputy_settings");
    if (saved) {
      const parsed = JSON.parse(saved);
      setTeachingEnabled(parsed.teachingEnabled ?? true);
      setNotificationsEnabled(parsed.notificationsEnabled ?? true);
    }
  }, []);

  const handleToggleTeaching = () => {
    const newVal = !teachingEnabled;
    setTeachingEnabled(newVal);
    saveSettings(newVal, notificationsEnabled);
    // Dispatch a global event so the sidebar can re-render
    window.dispatchEvent(new CustomEvent("myshule:deputy-teaching-toggle", { detail: { enabled: newVal } }));
  };

  const handleToggleNotifications = () => {
    const newVal = !notificationsEnabled;
    setNotificationsEnabled(newVal);
    saveSettings(teachingEnabled, newVal);
  };

  const saveSettings = (teaching: boolean, notifs: boolean) => {
    localStorage.setItem("myshule_deputy_settings", JSON.stringify({
      teachingEnabled: teaching,
      notificationsEnabled: notifs
    }));
  };

  return (
    <Panel title="Dashboard Settings" description="Personalize your dashboard preferences." icon={Settings}>
      <div className="max-w-2xl space-y-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-white p-6">
          <h3 className="text-lg font-bold text-[#071D49] mb-4">Workspace Preferences</h3>
          
          <div className="flex items-center justify-between py-3 border-b border-[#D8E0EC]">
            <div>
              <div className="font-semibold text-[#071D49]">Show Teaching Workspace</div>
              <div className="text-sm text-[#64748B]">Enable this if you have classes assigned to you.</div>
            </div>
            <label className="relative inline-flex cursor-pointer items-center">
              <input type="checkbox" className="peer sr-only" checked={teachingEnabled} onChange={handleToggleTeaching} />
              <div className="peer h-6 w-11 rounded-full bg-slate-200 after:absolute after:left-[2px] after:top-[2px] after:h-5 after:w-5 after:rounded-full after:border after:border-gray-300 after:bg-white after:transition-all after:content-[''] peer-checked:bg-blue-600 peer-checked:after:translate-x-full peer-checked:after:border-white peer-focus:outline-none"></div>
            </label>
          </div>

          <div className="flex items-center justify-between py-3">
            <div>
              <div className="font-semibold text-[#071D49]">Receive Immediate Notifications</div>
              <div className="text-sm text-[#64748B]">Get alerts for discipline, attendance, and welfare cases.</div>
            </div>
            <label className="relative inline-flex cursor-pointer items-center">
              <input type="checkbox" className="peer sr-only" checked={notificationsEnabled} onChange={handleToggleNotifications} />
              <div className="peer h-6 w-11 rounded-full bg-slate-200 after:absolute after:left-[2px] after:top-[2px] after:h-5 after:w-5 after:rounded-full after:border after:border-gray-300 after:bg-white after:transition-all after:content-[''] peer-checked:bg-blue-600 peer-checked:after:translate-x-full peer-checked:after:border-white peer-focus:outline-none"></div>
            </label>
          </div>
          
        </div>
      </div>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { UsersRound } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { requestDutyReport, manageDutyRoster } from "./api-client";

export type StaffDutyRecord = {
  id: string;
  staffName: string;
  dutyArea: string;
  time: string;
  status: "Present" | "Missing" | "Requested";
  reportStatus: "Pending" | "Submitted";
};

type StaffDutyData = {
  metrics: {
    total_staff: number;
  };
  duties: StaffDutyRecord[];
};

export function DeputyStaffDutyWorkspace() {
  const queryClient = useQueryClient();
  const { data, isLoading, refetch } = useSchoolQuery<StaffDutyData>('/admin-command/deputy/staff-duty');

  const [showManageModal, setShowManageModal] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [rosterData, setRosterData] = useState({ staffName: '', dutyArea: '', time: '' });

  const requestMutation = useSchoolMutation<{ id: string }, { id: string }>(
    ({ id }) => `/admin-command/deputy/staff-duty/${id}/request-report`,
    'POST',
    {
      onSuccess: () => queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/staff-duty'] })
    }
  );

  const duties = data?.duties || [];

  const handleRequestReport = async (id: string, staffName: string) => {
    try {
      await requestDutyReport(id);
      queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/staff-duty'] });
      toast.success(`Report requested from ${staffName}.`);
    } catch (e: any) {
      toast.error(e.message || "Failed to request report.");
    }
  };

  const handleManageRoster = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      await manageDutyRoster(rosterData);
      toast.success("Duty roster updated successfully");
      setShowManageModal(false);
      setRosterData({ staffName: '', dutyArea: '', time: '' });
      refetch();
    } catch (error) {
      toast.error("Failed to update duty roster");
    } finally {
      setIsSubmitting(false);
    }
  };

  const getStatusTone = (st: string): Tone => {
    if (st === "Present") return "success";
    if (st === "Requested") return "warning";
    return "danger";
  };

  return (
    <>
      <Panel title="Staff Duty & Supervision" description="Staff duty rosters, supervision zones, and presence." icon={UsersRound} actions={
        <button onClick={() => setShowManageModal(true)} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition">Manage Roster</button>
      }>
        <div className="grid gap-4 md:grid-cols-2 mb-6">
          <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
            <div className="text-sm font-semibold text-[#64748B]">Total Staff</div>
            <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total_staff || 0}</div>
          </div>
        </div>
        <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
          <table className="w-full text-sm text-left whitespace-nowrap">
            <thead className="bg-[#F8FAFC] text-[#071D49]">
              <tr>
