function isLiveCounsellingDashboard(value: CounsellingDashboard | Record<string, unknown> | null): value is CounsellingDashboard {
  return Boolean(
    value
    && typeof value.active_referrals === "number"
    && typeof value.upcoming_sessions === "number"
    && typeof value.high_risk_students === "number"
    && typeof value.followups_due === "number",
  );
}

function buildLiveKpis(dashboard: CounsellingDashboard | null) {
  if (!dashboard) {
    return kpis;
  }

  return kpis.map((item) => {
    if (item.label === "Active Counselling Cases") {
      return {
        ...item,
        value: String(dashboard.active_referrals),
        detail: `${dashboard.active_referrals} active referrals, ${dashboard.improvement_cases} improvement plans, ${dashboard.followups_due} follow-ups overdue.`,
        sub: "Live counselling API",
      };
    }

    if (item.label === "High Risk Students") {
      return {
        ...item,
        value: String(dashboard.high_risk_students),
        detail: `${dashboard.high_risk_students} learners flagged by live counselling risk signals and repeat referrals.`,
        sub: `${dashboard.repeat_referrals} repeat referrals`,
      };
    }

    if (item.label === "Sessions Today") {
      return {
        ...item,
        value: String(dashboard.upcoming_sessions),
        detail: `${dashboard.upcoming_sessions} upcoming counselling sessions loaded from the school schedule.`,
        sub: "Live calendar queue",
      };
    }

    return item;
  });
}

function counsellingActionEndpoint(action: string) {
  const normalized = action.toLowerCase();

  if (/session|notes|reschedule|approve/.test(normalized)) {
    return "/api/admin-command/guidance-counselling/sessions";
  }

  if (/guardian|parent/.test(normalized)) {
    return "/api/admin-command/guidance-counselling/parent-engagement";
  }

  if (/check-in|follow/.test(normalized)) {
    return "/api/admin-command/guidance-counselling/follow-ups";
  }

  if (/clinic|refer|escalate|principal|boarding|emergency|alert/.test(normalized)) {
    return "/api/admin-command/guidance-counselling/referrals";
  }

  return "/api/admin-command/guidance-counselling/welfare-notes";
}

async function persistCounsellingWorkflowAction(action: string, payload: Record<string, unknown>) {
  return requestDashboardApi(counsellingActionEndpoint(action), {
    method: "POST",
    body: {
      ...payload,
      action,
      source_dashboard: "guidance-counselling-command",
    },
  });
}

export function GuidanceCounsellingCommandCenter({
  routeMode,
  tenantSlug,
  liveDataEnabled = true,
}: {
  routeMode: GuidanceRouteMode;
  tenantSlug?: string | null;
  liveDataEnabled?: boolean;
}) {
  const [now, setNow] = useState<Date | null>(null);
  const [liveDashboard, setLiveDashboard] = useState<CounsellingDashboard | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [notice, setNotice] = useState("Counselling desk ready for referrals, sessions, follow-ups, and parent meetings.");
  const [sessionDialogOpen, setSessionDialogOpen] = useState(false);
  const [activeTimelineAction, setActiveTimelineAction] = useState<CounsellingTimelineAction | null>(null);
  const [activeInterventionAction, setActiveInterventionAction] = useState<CounsellingInterventionAction | null>(null);
  const kpiItems = useMemo(() => buildLiveKpis(liveDashboard), [liveDashboard]);
  const searchResults = useMemo(() => {
    const query = searchTerm.trim().toLowerCase();
    if (!query) return [];

    return guidanceSearchRecords.filter((record) =>
      [record.label, record.detail, record.sectionId].some((value) => value.toLowerCase().includes(query)),
    );
  }, [searchTerm]);

  useEffect(() => {
    const updateClock = () => setNow(new Date());
    const animationFrame = window.requestAnimationFrame(updateClock);
    const timer = window.setInterval(updateClock, 60_000);

    return () => {
      window.cancelAnimationFrame(animationFrame);
      window.clearInterval(timer);
    };
  }, []);

  useEffect(() => {
    if (!tenantSlug || !liveDataEnabled) {
      return;
    }

    let cancelled = false;

    async function loadLiveCounsellingDashboard() {
      const dashboard = await fetchCounsellingDashboard(tenantSlug as string);

      if (!cancelled && isLiveCounsellingDashboard(dashboard)) {
        setLiveDashboard(dashboard);
      }
    }

    void loadLiveCounsellingDashboard().catch(() => {
      if (!cancelled) {
        setLiveDashboard(null);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [liveDataEnabled, tenantSlug]);

  function openSearchRecord(record: GuidanceSearchRecord) {
    setSearchTerm("");
    setNotice(`${record.label} counselling search loaded ${record.sectionId} section: ${record.detail}.`);

    if (typeof document !== "undefined") {
      const target = document.getElementById(record.sectionId);
      target?.scrollIntoView?.({ behavior: "smooth", block: "start" });
    }
  }

  function openQuickAddSession() {
    setSessionDialogOpen(true);
    setNotice("Quick-add counselling session form opened. Save the session to persist it and notify the welfare chain.");
  }

  function openTimelineAction(action: CounsellingTimelineAction) {
    setActiveTimelineAction(action);
    setNotice(`${action.action} selected for ${action.item.title}. Save the timeline action to persist it.`);
  }

  function openInterventionAction(action: CounsellingInterventionAction) {
    setActiveInterventionAction(action);
    setNotice(`${action.label} intervention selected. Save the intervention action to persist it.`);
  }

  async function saveCounsellingSession() {
    const schoolId = getCurrentSchoolId();
    try {
      await persistCounsellingWorkflowAction("quick_add_session", {
        summary: "Quick-add counselling session for same-school welfare follow-up.",
        sessionType: "Quick-add counselling session",
      });
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Counselling session could not be saved.");
      return;
    }

    publishSchoolOperationalEvent({
      schoolId,
      type: "COUNSELLING_SESSION_RECORDED",
      module: "counselling",
      actorRole: "School Counsellor",
      title: "Quick-add counselling session saved",
      body: "School Counsellor recorded a quick-add counselling session for same-school welfare follow-up.",
      entityId: "counselling-session-quick-add",
      severity: "info",
      payload: {
        source: "quick-add-session",
        dashboard: "guidance-counselling",
        sessionType: "Quick-add counselling session",
      },
      notifications: [
        {
          audienceRoles: ["Deputy Principal", "Class Teacher", "Principal"],
          title: "Counselling session recorded",
          body: "A counselling session was saved for welfare follow-up.",
          severity: "info",
          relatedModule: "counselling",
          relatedRecordId: "counselling-session-quick-add",
          requiresAction: false,
          requestStatus: "Completed",
        },
      ],
    });

    setSessionDialogOpen(false);
    setNotice(
      `${schoolId} quick-add counselling session saved: counselling-session-quick-add, Deputy/Class Teacher/Principal notified for welfare follow-up.`,
    );
  }

  async function saveTimelineAction() {
    if (!activeTimelineAction) return;

    const schoolId = getCurrentSchoolId();
    const entityId = `counselling-timeline-${activeTimelineAction.item.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
    try {
      await persistCounsellingWorkflowAction(activeTimelineAction.action, {
        id: entityId,
        summary: `${activeTimelineAction.action} for ${activeTimelineAction.item.title}`,
        notes: activeTimelineAction.item.detail,
        itemTitle: activeTimelineAction.item.title,
        itemTime: activeTimelineAction.item.time,
        severity: activeTimelineAction.item.tone,
      });
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Counselling timeline action could not be saved.");
      return;
    }

    publishSchoolOperationalEvent({
      schoolId,
      type: "COUNSELLING_TIMELINE_ACTION_RECORDED",
      module: "counselling",
      actorRole: "School Counsellor",
      title: `${activeTimelineAction.action} saved for ${activeTimelineAction.item.title}`,
      body: `School Counsellor recorded ${activeTimelineAction.action.toLowerCase()} for ${activeTimelineAction.item.title}.`,
      entityId,
      severity: activeTimelineAction.item.tone === "critical" ? "critical" : "info",
      payload: {
        source: "timeline-action",
        dashboard: "guidance-counselling",
        action: activeTimelineAction.action,
        itemTitle: activeTimelineAction.item.title,
        itemDetail: activeTimelineAction.item.detail,
        itemTime: activeTimelineAction.item.time,
      },
      notifications: [
        {
          audienceRoles: ["Deputy Principal", "Class Teacher", "Principal"],
          title: `${activeTimelineAction.action} recorded`,
          body: `${activeTimelineAction.action} was saved for ${activeTimelineAction.item.title}.`,
          severity: activeTimelineAction.item.tone === "critical" ? "critical" : "info",
          relatedModule: "counselling",
          relatedRecordId: entityId,
          requiresAction: activeTimelineAction.item.tone === "critical",
          requestStatus: "Completed",
        },
      ],
    });

    setNotice(`${activeTimelineAction.action} saved for ${activeTimelineAction.item.title}.`);
    setActiveTimelineAction(null);
  }

  async function saveInterventionAction() {
    if (!activeInterventionAction) return;

    const schoolId = getCurrentSchoolId();
    const entityId = `counselling-intervention-${activeInterventionAction.label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
    const isUrgent = /emergency|principal|guardian/i.test(activeInterventionAction.label);
    try {
      await persistCounsellingWorkflowAction(activeInterventionAction.label, {
        id: entityId,
        summary: `${activeInterventionAction.label} counselling intervention`,
        reason: `Recorded from ${activeInterventionAction.source} counselling controls.`,
        urgency: isUrgent ? "critical" : "normal",
      });
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Counselling intervention action could not be saved.");
      return;
    }

    publishSchoolOperationalEvent({
      schoolId,
      type: "COUNSELLING_INTERVENTION_ACTION_RECORDED",
      module: "counselling",
      actorRole: "School Counsellor",
      title: `${activeInterventionAction.label} saved for counselling intervention`,
      body: `School Counsellor recorded ${activeInterventionAction.label.toLowerCase()} from ${activeInterventionAction.source} counselling controls.`,
      entityId,
      severity: isUrgent ? "critical" : "info",
      payload: {
        source: activeInterventionAction.source,
        dashboard: "guidance-counselling",
        action: activeInterventionAction.label,
      },
      notifications: [
        {
          audienceRoles: ["Principal", "Deputy Principal", "Nurse", "Class Teacher"],
          title: `${activeInterventionAction.label} recorded`,
          body: `${activeInterventionAction.label} was saved for a same-school counselling intervention.`,
          severity: isUrgent ? "critical" : "info",
          relatedModule: "counselling",
          relatedRecordId: entityId,
          requiresAction: isUrgent,
          requestStatus: "Completed",
        },
      ],
    });

    setNotice(`${activeInterventionAction.label} saved for counselling intervention.`);
    setActiveInterventionAction(null);
  }

  return (
    <div id="top" data-route-mode={routeMode} className="min-h-screen bg-[#F4F7FA] pb-24 lg:pb-6">
      <div className="grid gap-5 p-3 md:p-5 xl:grid-cols-[300px_minmax(0,1fr)]">
        <Sidebar />
        <main className="min-w-0 space-y-5">
          <TopNav
            now={now}
            searchTerm={searchTerm}
            searchResults={searchResults}
            onQuickAddSession={openQuickAddSession}
            onSearchResult={openSearchRecord}
            onSearchTermChange={setSearchTerm}
          />
          <div role="status" className="rounded-2xl border border-[#C8D5EA] bg-white px-4 py-3 text-sm font-black text-[#071D49] shadow-[0_12px_30px_rgba(7,29,73,0.08)]">
            {notice}
          </div>
          {sessionDialogOpen ? (
            <div
              role="dialog"
              aria-modal="true"
              aria-label="Counselling session action"
              className="rounded-[24px] border border-[#C8D5EA] bg-white p-5 text-[#071D49] shadow-[0_18px_55px_rgba(7,29,73,0.12)]"
            >
              <p className="text-xs font-black uppercase tracking-[0.16em] text-[#5F6F89]">Same-school counselling record</p>
              <h2 className="mt-2 text-xl font-black">Quick-add counselling session</h2>
              <p className="mt-2 max-w-3xl text-sm font-semibold leading-6 text-[#5F6F89]">
                This records a counselling session, notifies the relevant school leadership and class follow-up roles, and keeps the event scoped to the current school workspace.
              </p>
