        <Topbar
          searchTerm={searchTerm}
          onSearchTermChange={setSearchTerm}
        />
        <div className="flex-1 overflow-y-auto p-4 lg:p-6 space-y-6">
          {notice && (
            <div className="rounded-xl bg-blue-50 border border-blue-200 p-3 text-sm font-semibold text-blue-800 flex justify-between items-center">
              {notice}
              <button onClick={() => setNotice("")} className="text-blue-500 hover:text-blue-700">
