          </h3>
          <div className="flex flex-wrap gap-2">
            {allergies.map((allergy: string, idx: number) => (
               <span key={idx} className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md text-sm font-medium bg-rose-100 text-rose-700">
