          </div>
          <div className="flex items-center gap-2">
            <input type="checkbox" name="show_attendance" id="show_attendance" defaultChecked className="rounded border-gray-300" />
            <label htmlFor="show_attendance" className="text-sm font-medium">Show Attendance Metrics</label>
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmittingReportCard}>
              {isSubmittingReportCard && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Profile
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { Card } from "@/components/ui/card";
import { AlertCircle, CalendarClock, UserX, UserMinus } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Modal } from "@/components/ui/modal";
import { Loader2 } from "lucide-react";
import { usePermissions } from "@/components/providers/permission-context";
import { requestDashboardApi } from "@/lib/dashboard/api-client";

type PrincipalAttendanceData = {
  status: "active" | "degraded" | "setup_required";
  present: number;
  absent: number;
  late: number;
  chronicAbsenteeism: number;
  attendanceTrend: Array<{ label: string; value: number }>;
  recentAbsences: Array<{ id: string; student_name: string; admission_number: string | null; date: string; status: string; reason: string | null }>;
  students: Array<{ id: string; name: string; admission_number: string | null; class: string }>;
};

export function PrincipalAttendanceWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<PrincipalAttendanceData>('/admin-command/principal/attendance');
  const { hasPermission } = usePermissions();
  
  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  const handleLogAbsence = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    
    try {
      await requestDashboardApi('/admin-command/attendance/absences', {
        method: "POST",
        body: {
          studentId: formData.get("studentId"),
          date: formData.get("date"),
          reason: formData.get("reason"),
          isExcused: formData.get("isExcused") === "on",
        }
      });
      setIsAbsenceModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to log absence");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Attendance Overview</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Present Today</div>
          <div className="mt-2 text-2xl font-black text-green-500">{data.present}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Absent Today</div>
          <div className="mt-2 text-2xl font-black text-red-500">{data.absent}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Late Arrivals</div>
          <div className="mt-2 text-2xl font-black text-orange-500">{data.late}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Chronic Absenteeism</div>
          <div className="mt-2 text-2xl font-black text-white">{data.chronicAbsenteeism}%</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-6">Weekly Attendance Rate</h2>
          <div className="flex-1 flex items-end gap-2 mt-4 min-h-[200px]">
            {data.attendanceTrend?.map((item) => (
              <div key={item.label} className="flex-1 flex flex-col items-center gap-2 group">
                <div className="w-full relative bg-white/5 rounded-t-sm" style={{ height: "150px" }}>
                  <div 
                    className="absolute bottom-0 w-full bg-green-500/50 rounded-t-sm transition-all duration-500 group-hover:bg-green-400/60"
                    style={{ height: `${item.value}%` }}
                  >
                    <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-opacity">
                      {item.value}%
                    </div>
                  </div>
                </div>
                <span className="text-xs text-white/50">{item.label}</span>
              </div>
            ))}
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Recent Absences</h2>
            {hasPermission('attendance:write') && (
              <Button size="sm" variant="outline" className="text-xs bg-red-500/20 text-red-400 px-3 py-1.5 rounded hover:bg-red-500/30 transition-colors flex items-center gap-1" onClick={() => setIsAbsenceModalOpen(true)}>
                <UserMinus className="h-3 w-3 mr-1" />
                Log Absence
              </Button>
            )}
          </div>
          
          {(!data.recentAbsences || data.recentAbsences.length === 0) ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <UserMinus className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60 mb-4">No recent absences reported</p>
              {hasPermission('attendance:write') && (
                <Button size="sm" variant="outline" onClick={() => setIsAbsenceModalOpen(true)}>
                  <UserMinus className="h-4 w-4 mr-2" /> Log Absence
                </Button>
              )}
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              {data.recentAbsences.map((absence) => (
                <div key={absence.id} className="rounded-lg border border-white/10 bg-white/5 p-4">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <h4 className="font-medium text-white">{absence.student_name}</h4>
                      <p className="text-sm text-white/60">
                        {absence.admission_number || "No admission number"} - {absence.date}
                      </p>
                      {absence.reason && <p className="mt-1 text-xs text-white/50">{absence.reason}</p>}
                    </div>
                    <span className="rounded-full bg-red-500/15 px-2 py-1 text-xs font-semibold capitalize text-red-300">
                      {absence.status.replace("_", " ")}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <Modal open={isAbsenceModalOpen} onClose={() => setIsAbsenceModalOpen(false)} title="Log Absence">
        <form onSubmit={handleLogAbsence} className="space-y-4">
          {formError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {formError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-medium">Student</label>
            <select name="studentId" required className="w-full border rounded p-2 text-sm bg-white text-black">
              <option value="">Select a student...</option>
              {data.students?.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.name} {s.admission_number ? `(${s.admission_number})` : ""} - {s.class}
                </option>
              ))}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Date</label>
            <input type="date" name="date" required defaultValue={new Date().toISOString().split('T')[0]} className="w-full border rounded p-2 text-sm" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Reason</label>
            <textarea name="reason" required rows={3} className="w-full border rounded p-2 text-sm" placeholder="Why is the student absent?" />
          </div>
          <label className="flex items-center gap-2">
            <input type="checkbox" name="isExcused" className="rounded" />
            <span className="text-sm">Excused Absence</span>
          </label>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Save Record
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { AlertCircle, LayoutDashboard, Settings2, Plus, Loader2, Users } from "lucide-react";
import { toast } from "sonner";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { Modal } from "@/components/ui/modal";
import { Button } from "@/components/ui/button";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { usePermissions } from "@/components/providers/permission-context";

type PrincipalClassesData = {
  status: "active" | "degraded" | "setup_required";
  totalClasses: number;
  totalStreams: number;
  averageClassSize: number;
  capacityUtilization: number;
  classDistribution: Array<{ label: string; value: number }>;
  recentAdjustments: Array<any>;
};

export function PrincipalClassesStreamsWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<PrincipalClassesData>('/admin-command/principal/classes');
  const { data: yearsData } = useSchoolQuery<any[]>('/academics/academic-years');
  const { data: classesData } = useSchoolQuery<any[]>('/academics/class-sections');
  const { hasPermission } = usePermissions();

  const [isClassModalOpen, setIsClassModalOpen] = useState(false);
  const [isStreamModalOpen, setIsStreamModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  const hasYears = yearsData && yearsData.length > 0;
  const hasClasses = classesData && classesData.length > 0;

  const handleCreateClass = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/class-sections', {
        method: "POST",
        body: {
          academic_year_id: formData.get("academic_year_id"),
          name: formData.get("name"),
          grade_level: formData.get("grade_level"),
          capacity: formData.get("capacity") ? Number(formData.get("capacity")) : undefined,
        }
      });
      setIsClassModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to create class section");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCreateStream = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/class-streams', {
        method: "POST",
        body: {
          class_section_id: formData.get("class_section_id"),
          name: formData.get("name"),
          capacity: formData.get("capacity") ? Number(formData.get("capacity")) : undefined,
        }
      });
      setIsStreamModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to create stream");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleArchiveClass = async (id: string) => {
    if (!confirm("Are you sure you want to archive this class?")) return;
    try {
      await requestDashboardApi(`/academics/class-sections/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      toast.error(err.message || "Failed to archive class");
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Classes Overview</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-end gap-2">
        {hasPermission('academics:write') && (
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsClassModalOpen(true)}
              disabled={!hasYears}
              title={!hasYears ? "Cannot create a class before an academic year exists" : ""}
            >
              <Plus className="h-4 w-4 mr-2" />
              Create Class Section
            </Button>
            <Button 
              variant="outline" 
              onClick={() => setIsStreamModalOpen(true)}
              disabled={!hasClasses}
              title={!hasClasses ? "Cannot create a stream before a class section exists" : ""}
            >
              <Plus className="h-4 w-4 mr-2" />
              Create Stream
            </Button>
          </>
        )}
      </div>

      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Total Streams</div>
          <div className="mt-2 text-2xl font-black text-white">{data.totalStreams}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Total Classes</div>
          <div className="mt-2 text-2xl font-black text-white">{data.totalClasses}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Average Size</div>
          <div className="mt-2 text-2xl font-black text-white">{data.averageClassSize} students</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Capacity Utilization</div>
          <div className="mt-2 text-2xl font-black text-blue-400">{data.capacityUtilization}%</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-6">Population Distribution</h2>
          <div className="flex-1 flex items-end gap-2 mt-4 min-h-[200px]">
            {(!data.classDistribution || data.classDistribution.length === 0) ? (
              <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5 w-full">
                <Users className="h-10 w-10 text-white/20 mb-3" />
                <p className="text-white/60 mb-1">No classes found</p>
                <p className="text-xs text-white/40 mb-4">Create a class section to see distribution</p>
                {hasPermission('academics:write') && (
                  <Button 
                    variant="outline" 
                    size="sm"
                    onClick={() => setIsClassModalOpen(true)}
                    disabled={!hasYears}
                    title={!hasYears ? "Cannot create a class before an academic year exists" : ""}
                  >
                    <Plus className="h-4 w-4 mr-2" />
                    Create First Class
                  </Button>
                )}
              </div>
            ) : (
              data.classDistribution.map((item) => (
                <div key={item.label} className="flex-1 flex flex-col items-center gap-2 group">
                  <div className="w-full relative bg-white/5 rounded-t-sm" style={{ height: "150px" }}>
                    <div 
                      className="absolute bottom-0 w-full bg-indigo-500/50 rounded-t-sm transition-all duration-500 group-hover:bg-indigo-400/60"
                      style={{ height: `${Math.min((item.value / 400) * 100, 100)}%` }}
                    >
                      <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-opacity">
                        {item.value}
                      </div>
                    </div>
                  </div>
                  <span className="text-xs text-white/50">{item.label}</span>
                </div>
              ))
            )}
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Class Sections</h2>
          </div>
          
          {!classesData || classesData.length === 0 ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <LayoutDashboard className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60 mb-4">No classes configured</p>
              {hasPermission('academics:write') && (
                <Button 
                  variant="outline" 
                  size="sm"
                  onClick={() => setIsClassModalOpen(true)}
                  disabled={!hasYears}
                  title={!hasYears ? "Cannot create a class before an academic year exists" : ""}
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Create Class Section
                </Button>
              )}
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              {classesData.map((c: any) => (
                <div key={c.id} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10">
                  <div>
                    <div className="font-medium text-white">{c.name}</div>
                    <div className="text-xs text-white/50">Capacity: {c.capacity || 'N/A'}</div>
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" variant="outline" className="text-red-400 border-red-500/20 hover:bg-red-500/20" onClick={() => handleArchiveClass(c.id)}>
                      Archive
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <Modal open={isClassModalOpen} onClose={() => setIsClassModalOpen(false)} title="Create Class Section">
        <form onSubmit={handleCreateClass} className="space-y-4">
          {formError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {formError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Academic Year</label>
            <select name="academic_year_id" required className="input-base">
              <option value="">Select Academic Year...</option>
              {yearsData?.map(year => (
                <option key={year.id} value={year.id}>{year.name}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-semibold text-foreground">Class Name</label>
              <input name="name" required className="input-base" placeholder="e.g. Form 1" />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-semibold text-foreground">Grade Level</label>
              <input name="grade_level" required className="input-base" placeholder="e.g. 9" />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Capacity</label>
            <input type="number" name="capacity" required className="input-base" defaultValue={40} />
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Class
            </Button>
          </div>
        </form>
      </Modal>

      <Modal open={isStreamModalOpen} onClose={() => setIsStreamModalOpen(false)} title="Create Stream">
        <form onSubmit={handleCreateStream} className="space-y-4">
          {formError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {formError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Class Section</label>
            <select name="class_section_id" required className="input-base">
              <option value="">Select Class Section...</option>
              {classesData?.map(c => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Stream Name</label>
            <input name="name" required className="input-base" placeholder="e.g. Red, North, A" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Capacity</label>
            <input type="number" name="capacity" required className="input-base" defaultValue={40} />
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Stream
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { AlertCircle, MessageSquare, Send, Plus, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { Modal } from "@/components/ui/modal";
import { Button } from "@/components/ui/button";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { usePermissions } from "@/components/providers/permission-context";

type PrincipalCommunicationData = {
  status: "active" | "degraded" | "setup_required";
  smsBalance: number;
  messagesSentToday: number;
  failedDeliveries: number;
  pendingMessages: number;
  communicationTrend: Array<{ label: string; value: number }>;
  recentBroadcasts: Array<any>;
};

export function PrincipalCommunicationWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<PrincipalCommunicationData>('/admin-command/principal/communication');
  const { data: templatesData } = useSchoolQuery<any[]>('/admin-command/communication-templates');
  const { hasPermission } = usePermissions();

  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  const [isBroadcastModalOpen, setIsBroadcastModalOpen] = useState(false);
  const [isSubmittingBroadcast, setIsSubmittingBroadcast] = useState(false);
  const [broadcastFormError, setBroadcastFormError] = useState("");
  const [broadcastAudience, setBroadcastAudience] = useState("ALL_PARENTS");

  const handleCreateTemplate = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/admin-command/communication-templates', {
        method: "POST",
        body: {
          name: formData.get("name"),
          type: formData.get("type"),
          content: formData.get("content"),
        }
      });
      setIsTemplateModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to create template");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCreateBroadcast = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmittingBroadcast(true);
    setBroadcastFormError("");
    const formData = new FormData(e.currentTarget);
    const channels = [];
    if (formData.get("channel_sms") === "on") channels.push("SMS");
    if (formData.get("channel_email") === "on") channels.push("EMAIL");

    if (channels.length === 0) {
      setBroadcastFormError("Please select at least one channel");
      setIsSubmittingBroadcast(false);
      return;
    }

    try {
      await requestDashboardApi('/admin-command/communication-broadcasts', {
        method: "POST",
        body: {
          audience: formData.get("audience"),
          targetClass: formData.get("targetClass"),
          message: formData.get("message"),
          channels: channels,
        }
      });
      setIsBroadcastModalOpen(false);
      refetch();
    } catch (err: any) {
      setBroadcastFormError(err.message || "Failed to send broadcast");
    } finally {
      setIsSubmittingBroadcast(false);
    }
  };

  const handleArchiveTemplate = async (id: string) => {
    if (!confirm("Are you sure you want to archive this template?")) return;
    try {
      await requestDashboardApi(`/admin-command/communication-templates/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      toast.error(err.message || "Failed to archive template");
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Communication Overview</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Messages Sent Today</div>
          <div className="mt-2 text-2xl font-black text-white">{data.messagesSentToday}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Failed Deliveries</div>
          <div className="mt-2 text-2xl font-black text-red-500">{data.failedDeliveries}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Pending Outbox</div>
          <div className="mt-2 text-2xl font-black text-yellow-500">{data.pendingMessages}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">SMS Balance</div>
          <div className="mt-2 text-2xl font-black text-green-500">{data.smsBalance}</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-6">Weekly Broadcast Volume</h2>
          <div className="flex-1 flex items-end gap-2 mt-4 min-h-[200px]">
            {data.communicationTrend?.map((item) => (
              <div key={item.label} className="flex-1 flex flex-col items-center gap-2 group">
                <div className="w-full relative bg-white/5 rounded-t-sm" style={{ height: "150px" }}>
                  <div 
                    className="absolute bottom-0 w-full bg-cyan-500/50 rounded-t-sm transition-all duration-500 group-hover:bg-cyan-400/60"
                    style={{ height: `${Math.min(item.value, 150)}%` }} // Max height cap for chart aesthetics
                  >
                    <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-opacity">
                      {item.value}
                    </div>
                  </div>
                </div>
                <span className="text-xs text-white/50">{item.label}</span>
              </div>
            ))}
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Recent Broadcasts</h2>
            {hasPermission('communication:write') && (
              <Button size="sm" variant="outline" className="text-xs bg-white/10 text-white px-3 py-1.5 rounded hover:bg-white/20 transition-colors flex items-center gap-1" onClick={() => setIsBroadcastModalOpen(true)}>
                <Send className="h-3 w-3 mr-1" />
                New Message
              </Button>
            )}
          </div>

          {(!data.recentBroadcasts || data.recentBroadcasts.length === 0) ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <MessageSquare className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60 mb-4">No recent broadcasts sent</p>
              {hasPermission('communication:write') && (
                <Button size="sm" variant="outline" onClick={() => setIsBroadcastModalOpen(true)}>
                  <Send className="h-4 w-4 mr-2" /> Send Broadcast
                </Button>
              )}
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              <div className="text-white/60 text-sm py-4">Broadcasts will appear here.</div>
            </div>
          )}
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full mt-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Communication Templates</h2>
            <Button size="sm" variant="outline" onClick={() => setIsTemplateModalOpen(true)}>
              <Plus className="h-4 w-4 mr-1" /> Add Template
            </Button>
          </div>
          {!templatesData || templatesData.length === 0 ? (
            <div className="text-white/60 text-sm py-4 text-center">No communication templates configured yet.</div>
          ) : (
            <div className="space-y-2">
              {templatesData.map((template: any) => (
                <div key={template.id} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10">
                  <div>
                    <div className="font-medium text-white">{template.name}</div>
                    <div className="text-xs text-white/50">{template.type}</div>
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" variant="outline" className="text-red-400 border-red-500/20 hover:bg-red-500/20" onClick={() => handleArchiveTemplate(template.id)}>
                      Archive
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <Modal open={isTemplateModalOpen} onClose={() => setIsTemplateModalOpen(false)} title="Create Template">
        <form onSubmit={handleCreateTemplate} className="space-y-4">
          {formError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {formError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-medium">Name</label>
            <input name="name" required className="w-full border rounded p-2 text-sm" placeholder="e.g. Fee Reminder" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Type</label>
            <select name="type" required className="w-full border rounded p-2 text-sm bg-white text-black">
              <option value="SMS">SMS</option>
              <option value="EMAIL">Email</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Content</label>
            <textarea name="content" required className="w-full border rounded p-2 text-sm" placeholder="Message content... Use {{student_name}} for variables." />
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Template
            </Button>
          </div>
        </form>
      </Modal>

      <Modal open={isBroadcastModalOpen} onClose={() => setIsBroadcastModalOpen(false)} title="Send Broadcast">
        <form onSubmit={handleCreateBroadcast} className="space-y-4">
          {broadcastFormError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {broadcastFormError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-medium">Audience</label>
            <select 
              name="audience" 
              required 
              value={broadcastAudience}
              onChange={e => setBroadcastAudience(e.target.value)}
              className="w-full border border-slate-200 rounded p-2 text-sm bg-white text-black focus:outline-none focus:ring-1 focus:ring-slate-950"
            >
              <option value="ALL_PARENTS">All Parents</option>
              <option value="ALL_STAFF">All Staff</option>
              <option value="SPECIFIC_CLASS">Specific Class</option>
            </select>
          </div>
          {broadcastAudience === "SPECIFIC_CLASS" && (
            <div className="space-y-2">
              <label className="text-sm font-medium">Class / Grade Name</label>
              <input type="text" name="targetClass" placeholder="e.g. Form 1A" required className="w-full border border-slate-200 rounded p-2 text-sm bg-white text-black focus:outline-none focus:ring-1 focus:ring-slate-950" />
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-medium">Channels</label>
            <div className="flex gap-4">
              <label className="flex items-center gap-2">
                <input type="checkbox" name="channel_sms" defaultChecked className="rounded" />
                <span className="text-sm">SMS</span>
              </label>
              <label className="flex items-center gap-2">
                <input type="checkbox" name="channel_email" defaultChecked className="rounded" />
                <span className="text-sm">Email</span>
              </label>
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Message</label>
            <textarea name="message" required rows={4} className="w-full border rounded p-2 text-sm" placeholder="Write your broadcast message..." />
            <p className="text-xs text-gray-500">Variables like {"{{student_name}}"} will be replaced automatically.</p>
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmittingBroadcast}>
              {isSubmittingBroadcast && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Send Broadcast
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { Card } from "@/components/ui/card";
import { AlertCircle, AlertTriangle, ShieldAlert } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Modal } from "@/components/ui/modal";
import { Loader2 } from "lucide-react";
import { usePermissions } from "@/components/providers/permission-context";
import { requestDashboardApi } from "@/lib/dashboard/api-client";

type PrincipalDisciplineData = {
  status: "active" | "degraded" | "setup_required";
  openCases: number;
  criticalCases: number;
  escalations: number;
  incidentTrend: Array<{ label: string; value: number }>;
  recentIncidents: Array<{ id: string; title: string; severity: string; status: string; date: string }>;
  students: Array<{ id: string; name: string; admission_number: string | null; class: string }>;
};

export function PrincipalDisciplineWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<PrincipalDisciplineData>('/admin-command/principal/discipline');
  const { hasPermission } = usePermissions();

  const [isIncidentModalOpen, setIsIncidentModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  const handleReportIncident = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);

    try {
      await requestDashboardApi('/admin-command/discipline/incidents', {
        method: "POST",
        body: {
          studentId: formData.get("studentId"),
          category: formData.get("category"),
          severity: formData.get("severity"),
          description: formData.get("description"),
        }
      });
      setIsIncidentModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to report incident");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Discipline Overview</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Status</div>
          <div className="mt-2 text-2xl font-black text-white capitalize">{data.status}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Open Cases</div>
          <div className="mt-2 text-2xl font-black text-white">{data.openCases}</div>
        </Card>
        <Card className="border border-red-500/20 bg-red-500/5 p-5">
          <div className="text-sm font-semibold text-red-400">Critical Severity</div>
          <div className="mt-2 text-2xl font-black text-red-500">{data.criticalCases}</div>
        </Card>
        <Card className="border border-orange-500/20 bg-orange-500/5 p-5">
          <div className="text-sm font-semibold text-orange-400">Escalated to Principal</div>
          <div className="mt-2 text-2xl font-black text-orange-500">{data.escalations}</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-6">Incident Trend</h2>
          <div className="flex-1 flex items-end gap-2 mt-4 min-h-[200px]">
            {data.incidentTrend?.map((item) => {
              const maxVal = Math.max(...(data.incidentTrend?.map(i => i.value) || [1]), 1);
              return (
                <div key={item.label} className="flex-1 flex flex-col items-center gap-2 group">
                  <div className="w-full relative bg-white/5 rounded-t-sm" style={{ height: "150px" }}>
                    <div 
                      className="absolute bottom-0 w-full bg-red-500/50 rounded-t-sm transition-all duration-500 group-hover:bg-red-400/60"
                      style={{ height: `${(item.value / maxVal) * 100}%` }}
                    >
                      <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-opacity">
                        {item.value}
                      </div>
                    </div>
                  </div>
                  <span className="text-xs text-white/50">{item.label}</span>
                </div>
              );
            })}
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Recent Incidents</h2>
            {hasPermission('discipline:write') && (
              <Button size="sm" variant="outline" className="text-xs bg-red-500/20 text-red-400 px-3 py-1.5 rounded hover:bg-red-500/30 transition-colors flex items-center gap-1" onClick={() => setIsIncidentModalOpen(true)}>
                <ShieldAlert className="h-3 w-3 mr-1" />
                Report Incident
              </Button>
            )}
          </div>

          {(!data.recentIncidents || data.recentIncidents.length === 0) ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <AlertTriangle className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60 mb-4">No recent incidents reported</p>
              {hasPermission('discipline:write') && (
                <Button size="sm" variant="outline" onClick={() => setIsIncidentModalOpen(true)}>
                  <ShieldAlert className="h-4 w-4 mr-2" /> Report Incident
                </Button>
              )}
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              {data.recentIncidents.map((incident) => (
                <div key={incident.id} className="p-4 rounded-lg bg-white/5 border border-white/10 hover:bg-white/10 transition-colors">
                  <div className="flex items-center justify-between">
                    <div>
                      <h4 className="font-medium text-white">{incident.title}</h4>
                      <p className="text-sm text-white/60">{incident.date} • {incident.id.split('-')[0]}</p>
                    </div>
                    <div className="text-right">
                      <div className={`font-bold capitalize ${incident.severity === 'critical' ? 'text-red-500' : incident.severity === 'high' ? 'text-orange-500' : 'text-yellow-500'}`}>
                        {incident.severity}
                      </div>
                      <div className="text-xs text-white/40 capitalize">{incident.status}</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <Modal open={isIncidentModalOpen} onClose={() => setIsIncidentModalOpen(false)} title="Report Incident">
        <form onSubmit={handleReportIncident} className="space-y-4">
          {formError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {formError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-medium">Student Involved</label>
            <select name="studentId" required className="w-full border rounded p-2 text-sm bg-white text-black">
              <option value="">Select a student...</option>
              {data.students?.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.name} {s.admission_number ? `(${s.admission_number})` : ""} - {s.class}
                </option>
              ))}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Incident Category</label>
            <select name="category" required className="w-full border rounded p-2 text-sm bg-white text-black">
              <option value="TRUANCY">Truancy / Absenteeism</option>
              <option value="BULLYING">Bullying</option>
              <option value="DISRUPTION">Classroom Disruption</option>
              <option value="VANDALISM">Vandalism</option>
              <option value="THEFT">Theft</option>
              <option value="OTHER">Other</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Severity</label>
            <select name="severity" required className="w-full border rounded p-2 text-sm bg-white text-black">
              <option value="MINOR">Minor</option>
              <option value="MAJOR">Major</option>
              <option value="CRITICAL">Critical</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Description</label>
            <textarea name="description" required rows={3} className="w-full border rounded p-2 text-sm" placeholder="Provide details about the incident..." />
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Report Incident
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { Card } from "@/components/ui/card";
import { AlertCircle, FileText, CheckCircle2 } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Modal } from "@/components/ui/modal";
import { Loader2 } from "lucide-react";
import { usePermissions } from "@/components/providers/permission-context";

type PrincipalExamsData = {
  status: "active" | "degraded" | "setup_required";
  activeExams: number;
  reportsPending: number;
  missingMarksAlerts: number;
  averageScore: number;
  performanceTrend: Array<{ label: string; value: number }>;
  recentResults: Array<any>;
};

export function PrincipalExamsReportsWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<PrincipalExamsData>('/admin-command/principal/exams');
  const academicSetupData: any = { academicYears: [], terms: [] };
  const { hasPermission } = usePermissions();
  
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  const handleApproveAllReports = async () => {
    const results = Array.isArray(data?.recentResults) ? data.recentResults : [];
    const examIds = results
      .map((result: any) => result.exam_id ?? result.examId ?? result.id)
      .filter(Boolean);

    if (examIds.length === 0) {
      setFormError("No report-card batch is available for approval.");
      return;
    }

    setIsSubmitting(true);
    setFormError("");
    try {
      await Promise.all(examIds.map((examId: string) => requestDashboardApi(`/admin-command/principal/exams-report-cards/${examId}/approve`, { method: "POST" })));
      await refetch();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : "Failed to approve report-card batches.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCreateExam = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    
    try {
      await requestDashboardApi('/admin-command/exams/cycles', {
        method: "POST",
        body: {
          name: formData.get("name"),
          academicYearId: formData.get("academicYearId"),
          termId: formData.get("termId"),
          examType: formData.get("examType"),
        }
      });
      setIsExamModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to create exam series");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Exams Overview</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Reports Pending Approval</div>
          <div className="mt-2 text-2xl font-black text-yellow-500">{data.reportsPending}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Missing Marks Alerts</div>
          <div className="mt-2 text-2xl font-black text-red-500">{data.missingMarksAlerts}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">School Average Score</div>
          <div className="mt-2 text-2xl font-black text-white">{data.averageScore}%</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="flex justify-between items-start">
            <div>
              <div className="text-sm font-semibold text-white/70">Active Exams</div>
              <div className="mt-2 text-2xl font-black text-white">{data.activeExams}</div>
            </div>
            {hasPermission('exams:write') && (
              <Button size="sm" variant="outline" className="text-xs bg-white/10 text-white" onClick={() => setIsExamModalOpen(true)}>
                + New Exam
              </Button>
            )}
          </div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-6">Exam Performance Trend</h2>
          <div className="flex-1 flex items-end gap-2 mt-4 min-h-[200px]">
            {data.performanceTrend?.map((item) => (
              <div key={item.label} className="flex-1 flex flex-col items-center gap-2 group">
                <div className="w-full relative bg-white/5 rounded-t-sm" style={{ height: "150px" }}>
                  <div 
                    className="absolute bottom-0 w-full bg-purple-500/50 rounded-t-sm transition-all duration-500 group-hover:bg-purple-400/60"
                    style={{ height: `${item.value}%` }}
                  >
                    <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-opacity">
                      {item.value}%
                    </div>
                  </div>
                </div>
                <span className="text-xs text-white/50">{item.label}</span>
              </div>
            ))}
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Pending Reports Action</h2>
            <button type="button" disabled={isSubmitting} onClick={handleApproveAllReports} className="text-xs bg-white/10 text-white px-3 py-1.5 rounded hover:bg-white/20 transition-colors flex items-center gap-1 disabled:opacity-50">
              <CheckCircle2 className="h-3 w-3" />
              {isSubmitting ? "Approving..." : "Approve All"}
            </button>
          </div>
          
          {(!data.recentResults || data.recentResults.length === 0) ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <FileText className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60">No recent exam results to review</p>
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              {/* Report tasks will go here */}
            </div>
          )}
        </Card>
      </div>

      <Modal open={isExamModalOpen} onClose={() => setIsExamModalOpen(false)} title="Create Exam Series">
        <form onSubmit={handleCreateExam} className="space-y-4">
          {formError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {formError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-medium">Exam Name</label>
            <input type="text" name="name" required className="w-full border rounded p-2 text-sm" placeholder="e.g. Term 1 Midterms" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Academic Year</label>
            <select name="academicYearId" required className="w-full border rounded p-2 text-sm bg-white text-black">
              <option value="">Select Academic Year</option>
              {/* @ts-ignore */}
              {academicSetupData?.academicYears?.map((y: any) => (
                <option key={y.id} value={y.id}>{y.name}</option>
              ))}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Term / Semester</label>
            <select name="termId" required className="w-full border rounded p-2 text-sm bg-white text-black">
              <option value="">Select Term</option>
              {/* @ts-ignore */}
              {academicSetupData?.terms?.map((t: any) => (
                <option key={t.id} value={t.id}>{t.name}</option>
              ))}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Exam Type</label>
            <select name="examType" required className="w-full border rounded p-2 text-sm bg-white text-black">
              <option value="OPENER">Opener Exam</option>
              <option value="MIDTERM">Midterm</option>
              <option value="ENDTERM">End of Term</option>
              <option value="MOCK">Mock Exam</option>
              <option value="CAT">Continuous Assessment</option>
              <option value="PROJECT">Project Work</option>
            </select>
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Exam Series
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { AlertCircle, Wallet, TrendingUp, Download, PieChart, Receipt, Plus, Loader2, CheckCircle2 } from "lucide-react";
import { toast } from "sonner";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { Modal } from "@/components/ui/modal";
import { Button } from "@/components/ui/button";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { usePermissions } from "@/components/providers/permission-context";

type PrincipalWorkspaceData = {
  status: "active" | "degraded" | "setup_required";
  collectionsToday: string;
  outstandingInvoices: string;
  collectionData: Array<{ label: string; value: number; amount: string }>;
  pendingWaivers: Array<{ id: string; student: string; class: string; amount: string; reason: string; date: string }>;
};

export function PrincipalFinanceOverviewWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<PrincipalWorkspaceData>('/admin-command/principal/finance-overview');
  const { data: feeCategoriesData } = useSchoolQuery<any[]>('/finance/fee-categories');
  const { hasPermission, isLoading: permissionsLoading } = usePermissions();

  const [isFeeCategoryModalOpen, setIsFeeCategoryModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  const [isWaiverModalOpen, setIsWaiverModalOpen] = useState(false);
  const [isSubmittingWaiver, setIsSubmittingWaiver] = useState(false);
  const [waiverFormError, setWaiverFormError] = useState("");

  const handleCreateFeeCategory = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/finance/fee-categories', {
        method: "POST",
        body: {
          name: formData.get("name"),
          description: formData.get("description"),
          amount_minor: 0, // Placeholder, normally part of the form
          currency_code: "KES"
        }
      });
      setIsFeeCategoryModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to create fee category");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleAddWaiver = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmittingWaiver(true);
    setWaiverFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/finance/waivers', {
        method: "POST",
        body: {
          student_id: formData.get("student_id"),
          amount_minor: Math.round(parseFloat(formData.get("amount") as string) * 100),
          reason: formData.get("reason"),
          student_name: "Lookup Required", // Or fetch from student selection
          class_name: "Lookup Required"
        }
      });
      setIsWaiverModalOpen(false);
      refetch();
    } catch (err: any) {
      setWaiverFormError(err.message || "Failed to add waiver");
    } finally {
      setIsSubmittingWaiver(false);
    }
  };

  const handleArchiveFeeCategory = async (id: string) => {
    if (!confirm("Are you sure you want to archive this fee category?")) return;
    try {
      await requestDashboardApi(`/finance/fee-categories/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      toast.error(err.message || "Failed to archive fee category");
    }
  };

  const handleWaiverDecision = async (id: string, approved: boolean) => {
    try {
      await requestDashboardApi(`/finance/waivers/${id}/approve`, {
        method: "POST",
        body: { approved },
      });
      toast.success(`Waiver ${approved ? "approved" : "rejected"}.`);
      refetch();
    } catch (err: any) {
      toast.error(err.message || `Failed to ${approved ? "approve" : "reject"} waiver`);
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Finance Overview</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-4">
        {/* Summary Cards */}
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Status</div>
          <div className="mt-2 text-2xl font-black text-white capitalize">{data.status}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Collections Today</div>
          <div className="mt-2 text-2xl font-black text-white">{data.collectionsToday}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Outstanding Invoices</div>
          <div className="mt-2 text-2xl font-black text-white">{data.outstandingInvoices}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Pending Waivers</div>
          <div className="mt-2 text-2xl font-black text-white">{data.pendingWaivers?.length || 0}</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-6">Collection Trend</h2>
          <div className="flex-1 flex items-end gap-2 mt-4 min-h-[200px]">
            {data.collectionData?.map((item) => (
              <div key={item.label} className="flex-1 flex flex-col items-center gap-2 group">
                <div className="w-full relative bg-white/5 rounded-t-sm" style={{ height: "150px" }}>
                  <div 
                    className="absolute bottom-0 w-full bg-blue-500/50 rounded-t-sm transition-all duration-500 group-hover:bg-blue-400/60"
                    style={{ height: `${item.value}%` }}
                  >
                    <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-opacity">
                      {item.amount}
                    </div>
                  </div>
                </div>
                <span className="text-xs text-white/50">{item.label}</span>
              </div>
            ))}
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-4">Pending Waivers</h2>
          {(!data.pendingWaivers || data.pendingWaivers.length === 0) ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <CheckCircle2 className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60 mb-4">No pending waivers</p>
              {permissionsLoading ? (
                <Button size="sm" variant="outline" disabled>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" /> Checking access
                </Button>
              ) : hasPermission('finance:write') ? (
                <Button size="sm" variant="outline" onClick={() => setIsWaiverModalOpen(true)}>
                  <Plus className="h-4 w-4 mr-2" /> Add Waiver
                </Button>
              ) : null}
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              {data.pendingWaivers.map((waiver) => (
                <div key={waiver.id} className="p-4 rounded-lg bg-white/5 border border-white/10 hover:bg-white/10 transition-colors">
                  <div className="flex items-center justify-between">
                    <div>
                      <h4 className="font-medium text-white">{waiver.student}</h4>
                      <p className="text-sm text-white/60">{waiver.class} • {waiver.reason}</p>
                    </div>
                    <div className="text-right">
                      <div className="font-bold text-white">{waiver.amount}</div>
                      <div className="text-xs text-white/40">{waiver.date}</div>
                    </div>
                  </div>
                  <div className="mt-3 flex gap-2">
                    <button type="button" onClick={() => handleWaiverDecision(waiver.id, true)} className="text-xs bg-green-500/20 text-green-400 px-3 py-1.5 rounded hover:bg-green-500/30 transition-colors">Approve</button>
                    <button type="button" onClick={() => handleWaiverDecision(waiver.id, false)} className="text-xs bg-red-500/20 text-red-400 px-3 py-1.5 rounded hover:bg-red-500/30 transition-colors">Reject</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full mt-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Fee Categories</h2>
            <Button size="sm" variant="outline" onClick={() => setIsFeeCategoryModalOpen(true)}>
              <Plus className="h-4 w-4 mr-1" /> Add Category
            </Button>
          </div>
          {!feeCategoriesData || feeCategoriesData.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-6 text-center">
              <p className="text-white/60 text-sm mb-4">No fee categories configured yet.</p>
              <Button size="sm" variant="outline" onClick={() => setIsFeeCategoryModalOpen(true)}>
                <Plus className="h-4 w-4 mr-2" /> Add Category
              </Button>
            </div>
          ) : (
            <div className="space-y-2">
              {feeCategoriesData.map((category: any) => (
                <div key={category.id} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10">
                  <div>
                    <div className="font-medium text-white">{category.name}</div>
                    <div className="text-xs text-white/50">{category.description || 'No description'}</div>
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" variant="outline" className="text-red-400 border-red-500/20 hover:bg-red-500/20" onClick={() => handleArchiveFeeCategory(category.id)}>
                      Archive
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <Modal open={isFeeCategoryModalOpen} onClose={() => setIsFeeCategoryModalOpen(false)} title="Create Fee Category">
        <form onSubmit={handleCreateFeeCategory} className="space-y-4">
          {formError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {formError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Name</label>
            <input name="name" required className="input-base" placeholder="e.g. Tuition Fee" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Description</label>
            <textarea name="description" className="input-base" placeholder="Optional details..." />
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Category
            </Button>
          </div>
        </form>
      </Modal>

      <Modal open={isWaiverModalOpen} onClose={() => setIsWaiverModalOpen(false)} title="Add Waiver">
        <form onSubmit={handleAddWaiver} className="space-y-4">
          {waiverFormError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {waiverFormError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Student ID</label>
            <input name="student_id" required className="input-base" placeholder="e.g. STU-1234" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Amount</label>
            <input type="number" name="amount" required min="0" step="0.01" className="input-base" placeholder="e.g. 5000" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Reason</label>
            <textarea name="reason" required className="input-base" placeholder="Reason for waiver..." />
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmittingWaiver}>
              {isSubmittingWaiver && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Submit Waiver
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { Card } from "@/components/ui/card";
import { AlertCircle, Activity, Users, FileText } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useDashboardEventBus } from "@/lib/dashboard-communication/dashboard-communication-provider";
import { useEffect } from "react";
import { DashboardEngine } from "@/components/dashboard/dashboard-engine";

type PrincipalOverviewData = {
  status: "active" | "degraded" | "setup_required";
  totalStudents: number;
  totalStaff: number;
  activeIssues: number;
  pendingApprovals: number;
  recentActivity: Array<{ label: string; time: string }>;
};

import { useQueryClient } from "@tanstack/react-query";
import { getCurrentSchoolId } from "@/lib/school/school-operational-store";

export function PrincipalOverviewWorkspace() {
  const { data, isLoading, error } = useSchoolQuery<PrincipalOverviewData>('/admin-command/principal/overview');
  const queryClient = useQueryClient();
  const eventBus = useDashboardEventBus();

  useEffect(() => {
    // Subscribe to the global Event Bus
    const unsubscribe = eventBus.subscribe("STUDENT_ADMITTED", (event) => {
      // When a student is admitted somewhere else in the app, instantly update the metric
      const activeTenantId = getCurrentSchoolId();
      queryClient.setQueryData<PrincipalOverviewData>(
        ["school", activeTenantId || "session", '/admin-command/principal/overview'],
        (currentData) => {
          if (!currentData) return currentData;
          return {
            ...currentData,
            totalStudents: currentData.totalStudents + 1,
            recentActivity: [
              {
                label: "New Student Admitted",
                time: "Just now"
              },
              ...currentData.recentActivity
            ]
          };
        }
      );
    });

    return () => unsubscribe();
  }, [eventBus, queryClient]);

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div>
          <p className="text-xs font-black uppercase tracking-[0.16em] text-cyan-200">School activity today</p>
          <h2 className="mt-1 text-2xl font-black text-white">Live principal operations</h2>
        </div>
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Principal Overview</h2>
        </div>
      </Card>
    );
  }

  const totalStudents = Number(data.totalStudents ?? 0);
  const totalStaff = Number(data.totalStaff ?? 0);
  const pendingApprovals = Number(data.pendingApprovals ?? 0);
  const activeIssues = Number(data.activeIssues ?? 0);

  return (
    <div className="space-y-6">
      <div>
        <p className="text-xs font-black uppercase tracking-[0.16em] text-cyan-200">School activity today</p>
        <h2 className="mt-1 text-2xl font-black text-white">Live principal operations</h2>
      </div>
      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Total Students</div>
          <div className="mt-2 text-2xl font-black text-white">{totalStudents}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Total Staff</div>
          <div className="mt-2 text-2xl font-black text-white">{totalStaff}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Pending Approvals</div>
          <div className="mt-2 text-2xl font-black text-rose-400">{pendingApprovals}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Active Issues</div>
          <div className="mt-2 text-2xl font-black text-yellow-500">{activeIssues}</div>
        </Card>
      </div>
      <div className="mt-8">
        <h2 className="text-xl font-bold text-white mb-6">Operational Dashboard</h2>
        <DashboardEngine role="principal" />
      </div>
    </div>
  );
}

"use client";

import { Card } from "@/components/ui/card";
import { AlertCircle, BarChart3, FileText, Download, Star, Plus, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Modal } from "@/components/ui/modal";
import { usePermissions } from "@/components/providers/permission-context";

type PrincipalReportsData = {
  status: "active" | "degraded" | "setup_required";
  availableReports: number;
  favoriteReports: number;
  recentlyGenerated: number;
  categories: Array<{ name: string; count: number }>;
  scheduledReports: Array<{ title: string; schedule: string }>;
};

export function PrincipalReportsWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<PrincipalReportsData>('/admin-command/principal/reports');
  const { hasPermission } = usePermissions();

  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [isSubmittingCat, setIsSubmittingCat] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isSubmittingSched, setIsSubmittingSched] = useState(false);

  const handleCreateCategory = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmittingCat(true);
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/admin-command/reports/categories', {
        method: "POST",
        body: { name: formData.get("name") }
      });
      setIsCategoryModalOpen(false);
      refetch();
    } catch (err: any) {
      toast.error(err.message || "Failed to create category");
    } finally {
      setIsSubmittingCat(false);
    }
  };

  const handleScheduleReport = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmittingSched(true);
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/admin-command/reports/schedule', {
        method: "POST",
        body: { title: formData.get("title"), schedule: formData.get("schedule") }
      });
      setIsScheduleModalOpen(false);
      refetch();
    } catch (err: any) {
      toast.error(err.message || "Failed to schedule report");
    } finally {
      setIsSubmittingSched(false);
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Reports Overview</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-3">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Available Reports</div>
          <div className="mt-2 text-2xl font-black text-white">{data.availableReports}</div>
        </Card>
        <Card className="border border-cyan-500/30 bg-cyan-500/10 p-5">
          <div className="text-sm font-semibold text-cyan-200">Favorites</div>
          <div className="mt-2 text-2xl font-black text-cyan-400">{data.favoriteReports}</div>
        </Card>
        <Card className="border border-emerald-500/30 bg-emerald-500/10 p-5">
          <div className="text-sm font-semibold text-emerald-200">Generated This Month</div>
          <div className="mt-2 text-2xl font-black text-emerald-400">{data.recentlyGenerated}</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full min-h-[300px]">
          <div className="flex items-center justify-between mb-6 border-b border-white/10 pb-4">
            <h2 className="text-xl font-bold text-white">Report Categories</h2>
            {hasPermission('reports:write') && (
              <Button size="sm" variant="outline" onClick={() => setIsCategoryModalOpen(true)}>
                <Plus className="h-4 w-4 mr-1" /> Add Category
              </Button>
            )}
          </div>

          {(!data.categories || data.categories.length === 0) ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <BarChart3 className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60 mb-4">No report categories available.</p>
              {hasPermission('reports:write') && (
                <Button size="sm" variant="outline" onClick={() => setIsCategoryModalOpen(true)}>
                  <Plus className="h-4 w-4 mr-2" /> Create Category
                </Button>
              )}
            </div>
          ) : (
            <div className="space-y-4 flex-1 overflow-y-auto pr-2">
              {data.categories.map((cat, idx) => (
                <div key={idx} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10 hover:bg-white/10 transition cursor-pointer">
                  <div className="flex items-center gap-3">
                    <div className="flex-shrink-0 w-10 h-10 rounded-full bg-blue-500/20 flex items-center justify-center border border-blue-500/30">
                      <FileText className="h-5 w-5 text-blue-400" />
                    </div>
                    <p className="font-medium text-white">{cat.name}</p>
                  </div>
                  <div className="text-sm font-bold text-white/60">
                    {cat.count} reports
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full min-h-[300px]">
          <div className="flex items-center justify-between mb-6 border-b border-white/10 pb-4">
            <h2 className="text-xl font-bold text-white">Scheduled Reports</h2>
            {hasPermission('reports:write') && (
              <Button size="sm" variant="outline" onClick={() => setIsScheduleModalOpen(true)}>
                <Plus className="h-4 w-4 mr-1" /> Schedule
              </Button>
            )}
          </div>

          {(!data.scheduledReports || data.scheduledReports.length === 0) ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <Download className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60 mb-4">No automated reports scheduled.</p>
              {hasPermission('reports:write') && (
                <Button size="sm" variant="outline" onClick={() => setIsScheduleModalOpen(true)}>
                  <Plus className="h-4 w-4 mr-2" /> Schedule Report
                </Button>
              )}
            </div>
          ) : (
            <div className="space-y-4 flex-1 overflow-y-auto pr-2">
              {data.scheduledReports.map((report, idx) => (
                <div key={idx} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10">
                  <div className="flex items-center gap-3">
                    <div className="flex-shrink-0 w-8 h-8 rounded-full bg-indigo-500/20 flex items-center justify-center">
                      <Star className="h-4 w-4 text-indigo-400" />
                    </div>
                    <p className="font-medium text-white text-sm">{report.title}</p>
                  </div>
                  <div className="text-xs text-white/60 bg-white/10 px-2 py-1 rounded-full">
                    {report.schedule}
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <Modal open={isCategoryModalOpen} onClose={() => setIsCategoryModalOpen(false)} title="Create Report Category">
        <form onSubmit={handleCreateCategory} className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">Category Name</label>
            <input name="name" required className="w-full border rounded p-2 text-sm" placeholder="e.g. Financial Reports, Academic Summaries" />
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmittingCat}>
              {isSubmittingCat && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Category
            </Button>
          </div>
        </form>
      </Modal>

      <Modal open={isScheduleModalOpen} onClose={() => setIsScheduleModalOpen(false)} title="Schedule Report">
        <form onSubmit={handleScheduleReport} className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">Report Title</label>
            <input name="title" required className="w-full border rounded p-2 text-sm" placeholder="e.g. Weekly Attendance Summary" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Schedule (Cron/Frequency)</label>
            <select name="schedule" required className="w-full border rounded p-2 text-sm bg-white text-black">
              <option value="Daily">Daily</option>
              <option value="Weekly">Weekly</option>
              <option value="Monthly">Monthly</option>
              <option value="End of Term">End of Term</option>
            </select>
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmittingSched}>
              {isSubmittingSched && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Schedule Report
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { Card } from "@/components/ui/card";
import { AlertCircle, Building2, Mail, Phone, MapPin, CheckCircle2 } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useState, useRef } from "react";
import { requestDashboardApi } from "@/lib/dashboard/api-client";

type SchoolProfileData = {
  status: "active" | "degraded" | "setup_required";
  schoolName: string;
  subdomain: string;
  region: string | null;
  registrationStatus: string;
  curriculum: string;
  schoolType: string;
  logoUrl?: string | null;
  contactInfo: {
    email: string;
    phone: string;
  };
};

export function PrincipalSchoolProfileWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<SchoolProfileData>('/admin-command/principal/school-profile');
  const [isUploading, setIsUploading] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    setUploadError(null);

    const formData = new FormData();
    formData.append('logo', file);

    try {
      await requestDashboardApi('/admin-command/principal/school-profile/logo', {
        method: 'POST',
        body: formData
      });
      refetch();
    } catch (err: any) {
      setUploadError(err.message || 'Failed to upload logo');
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-48 bg-white/5 rounded-xl border border-white/10" />
          <div className="grid gap-4 md:grid-cols-2">
            <div className="h-32 bg-white/5 rounded-xl border border-white/10" />
            <div className="h-32 bg-white/5 rounded-xl border border-white/10" />
          </div>
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load School Profile</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <Card className="border border-white/10 bg-white/5 p-6 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-6 flex flex-col items-end gap-4 opacity-80">
          {data.logoUrl ? (
            <img src={data.logoUrl} alt="School Logo" className="h-24 w-24 object-contain rounded-lg border border-white/10" />
          ) : (
            <Building2 className="h-24 w-24 text-white/10" />
          )}
          <div className="flex flex-col items-end gap-2">
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*"
              onChange={handleLogoUpload}
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={isUploading}
              className="px-4 py-2 bg-white/10 hover:bg-white/20 text-white rounded-lg text-sm font-medium transition-colors border border-white/10 disabled:opacity-50"
            >
              {isUploading ? 'Uploading...' : 'Upload Logo'}
            </button>
            {uploadError && (
              <p className="text-red-400 text-xs max-w-[200px] text-right">{uploadError}</p>
            )}
          </div>
        </div>
        <div className="relative z-10 flex items-start justify-between">
          <div>
            <h2 className="text-3xl font-black text-white">{data.schoolName}</h2>
            <p className="text-white/60 mt-1">Tenant ID: {data.subdomain}</p>
            <div className="mt-4 flex flex-wrap gap-2">
              <span className="inline-flex items-center gap-1.5 rounded-full bg-cyan-500/10 px-3 py-1 text-xs font-semibold text-cyan-400 border border-cyan-500/20">
                <CheckCircle2 className="h-3.5 w-3.5" />
                {data.registrationStatus}
              </span>
              <span className="inline-flex items-center rounded-full bg-white/10 px-3 py-1 text-xs font-semibold text-white/80 border border-white/10">
                {data.schoolType}
              </span>
              <span className="inline-flex items-center rounded-full bg-white/10 px-3 py-1 text-xs font-semibold text-white/80 border border-white/10">
                {data.curriculum}
              </span>
            </div>
          </div>
        </div>
      </Card>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6">
          <h3 className="text-lg font-bold text-white mb-4 border-b border-white/10 pb-3">Contact Information</h3>
          <div className="space-y-4">
            <div className="flex items-center gap-3">
              <Mail className="h-5 w-5 text-white/40" />
              <div>
                <p className="text-xs font-semibold text-white/50 uppercase tracking-wider">Email Address</p>
                <p className="font-medium text-white">{data.contactInfo.email}</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <Phone className="h-5 w-5 text-white/40" />
              <div>
                <p className="text-xs font-semibold text-white/50 uppercase tracking-wider">Phone Number</p>
                <p className="font-medium text-white">{data.contactInfo.phone}</p>
              </div>
            </div>
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6">
          <h3 className="text-lg font-bold text-white mb-4 border-b border-white/10 pb-3">Location & Address</h3>
          <div className="space-y-4">
            <div className="flex items-center gap-3">
              <MapPin className="h-5 w-5 text-white/40" />
              <div>
                <p className="text-xs font-semibold text-white/50 uppercase tracking-wider">Region / County</p>
                <p className="font-medium text-white">{data.region || "Not specified"}</p>
              </div>
            </div>
          </div>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { Card } from "@/components/ui/card";
import { AlertCircle, Bell, Lock, Paintbrush, Monitor } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { useState } from "react";
import { toast } from "sonner";

type PrincipalSettingsData = {
  status: "active" | "degraded" | "setup_required";
  notifications: {
    emailAlerts: boolean;
    smsAlerts: boolean;
    dailyDigest: boolean;
  };
  dashboard: {
    theme: string;
    showTeachingWorkspace: boolean;
    defaultView: string;
  };
  security: {
    twoFactorAuth: boolean;
    lastPasswordChange: string;
  };
};

export function PrincipalSettingsWorkspace() {
  const { data, isLoading, error } = useSchoolQuery<PrincipalSettingsData>('/admin-command/principal/settings');
  const [actionBusy, setActionBusy] = useState<string | null>(null);

  const submitSettingsAction = async (action: string, title: string, message: string) => {
    setActionBusy(action);
    try {
      await requestDashboardApi("/admin-command/principal/settings/action", {
        method: "POST",
        body: { action, title, message, source_dashboard: "principal-settings" },
      });
      toast.success(title, { description: message });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Settings action could not be submitted.");
    } finally {
      setActionBusy(null);
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Settings</h2>
        </div>
      </Card>
    );
  }

  // A helper to trigger the custom event for teaching toggle
  const toggleTeaching = (e: React.ChangeEvent<HTMLInputElement>) => {
    const event = new CustomEvent("principal-teaching-toggle", { detail: e.target.checked });
    window.dispatchEvent(event);
  };

  return (
    <div className="space-y-6">
      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6">
          <div className="flex items-center gap-3 border-b border-white/10 pb-4 mb-4">
            <Monitor className="h-6 w-6 text-cyan-400" />
            <h2 className="text-xl font-bold text-white">Dashboard Preferences</h2>
          </div>
          
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="font-bold text-white">Show Teaching Workspace</p>
                <p className="text-xs text-white/60">Enable if you actively teach classes</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input 
                  type="checkbox" 
                  className="sr-only peer" 
                  defaultChecked={data.dashboard.showTeachingWorkspace}
                  onChange={toggleTeaching}
                />
                <div className="w-11 h-6 bg-white/10 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-cyan-500"></div>
              </label>
            </div>

            <div className="flex items-center justify-between">
              <div>
                <p className="font-bold text-white">Theme Preference</p>
                <p className="text-xs text-white/60">Current: {data.dashboard.theme}</p>
              </div>
              <button type="button" disabled={actionBusy === "theme_preference"} onClick={() => submitSettingsAction("theme_preference", "Theme change requested", `Principal requested a dashboard theme change from ${data.dashboard.theme}.`)} className="px-3 py-1.5 bg-white/10 hover:bg-white/20 text-white rounded text-sm transition disabled:opacity-50">
                {actionBusy === "theme_preference" ? "Saving..." : "Change"}
              </button>
            </div>
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6">
          <div className="flex items-center gap-3 border-b border-white/10 pb-4 mb-4">
            <Bell className="h-6 w-6 text-emerald-400" />
            <h2 className="text-xl font-bold text-white">Notifications</h2>
          </div>
          
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="font-bold text-white">Email Alerts</p>
                <p className="text-xs text-white/60">Receive important updates via email</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" className="sr-only peer" defaultChecked={data.notifications.emailAlerts} />
                <div className="w-11 h-6 bg-white/10 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500"></div>
              </label>
            </div>

            <div className="flex items-center justify-between">
              <div>
                <p className="font-bold text-white">Daily Digest</p>
                <p className="text-xs text-white/60">Receive a daily summary of school activities</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" className="sr-only peer" defaultChecked={data.notifications.dailyDigest} />
                <div className="w-11 h-6 bg-white/10 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500"></div>
              </label>
            </div>
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 md:col-span-2">
          <div className="flex items-center gap-3 border-b border-white/10 pb-4 mb-4">
            <Lock className="h-6 w-6 text-purple-400" />
            <h2 className="text-xl font-bold text-white">Security</h2>
          </div>
          
          <div className="grid md:grid-cols-2 gap-6">
            <div className="flex items-center justify-between p-4 bg-white/5 rounded-lg border border-white/10">
              <div>
                <p className="font-bold text-white">Two-Factor Authentication</p>
                <p className="text-xs text-white/60">Status: {data.security.twoFactorAuth ? "Enabled" : "Disabled"}</p>
              </div>
              <button type="button" disabled={actionBusy === "two_factor"} onClick={() => submitSettingsAction("two_factor", "Two-factor authentication change requested", `Principal requested to ${data.security.twoFactorAuth ? "disable" : "enable"} two-factor authentication.`)} className={`px-4 py-2 rounded text-sm font-bold transition disabled:opacity-50 ${data.security.twoFactorAuth ? 'bg-rose-500/20 text-rose-400 hover:bg-rose-500/30' : 'bg-emerald-500/20 text-emerald-400 hover:bg-emerald-500/30'}`}>
                {actionBusy === "two_factor" ? "Saving..." : data.security.twoFactorAuth ? "Disable" : "Enable"}
              </button>
            </div>

            <div className="flex items-center justify-between p-4 bg-white/5 rounded-lg border border-white/10">
              <div>
                <p className="font-bold text-white">Password</p>
                <p className="text-xs text-white/60">Last changed: {data.security.lastPasswordChange}</p>
              </div>
              <button type="button" disabled={actionBusy === "password_update"} onClick={() => submitSettingsAction("password_update", "Password update requested", "Principal requested a secure password update workflow.")} className="px-4 py-2 bg-white/10 hover:bg-white/20 text-white rounded text-sm font-bold transition disabled:opacity-50">
                {actionBusy === "password_update" ? "Saving..." : "Update"}
              </button>
            </div>
          </div>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { AlertCircle, UserPlus, Users, Plus, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { Modal } from "@/components/ui/modal";
import { Button } from "@/components/ui/button";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { UserManagementPanel } from "@/components/school/user-management-panel";
import { usePermissions } from "@/components/providers/permission-context";

type PrincipalStaffData = {
  status: "active" | "degraded" | "setup_required";
  totalStaff: number;
  teachingStaff: number;
  supportStaff: number;
  onLeave: number;
  staffDistribution: Array<{ label: string; value: number }>;
  recentOnboarding: Array<any>;
};

export function PrincipalStaffRolesWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<PrincipalStaffData>('/admin-command/principal/staff');
  const { data: termsData } = useSchoolQuery<any[]>('/academics/academic-terms');
  const { data: yearsData } = useSchoolQuery<any[]>('/academics/academic-years');
  const { data: classesData } = useSchoolQuery<any[]>('/academics/class-sections');
  const { data: subjectsData } = useSchoolQuery<any[]>('/academics/subjects');
  const { data: classTeachersData } = useSchoolQuery<any[]>('/academics/class-teachers');
  const { hasPermission } = usePermissions();

  const [isAssignModalOpen, setIsAssignModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  const [isClassTeacherModalOpen, setIsClassTeacherModalOpen] = useState(false);
  const [isSubmittingCT, setIsSubmittingCT] = useState(false);
  const [ctFormError, setCtFormError] = useState("");

  const hasPrerequisites = 
    termsData && termsData.length > 0 &&
    classesData && classesData.length > 0 &&
    subjectsData && subjectsData.length > 0;

  const hasCTPrerequisites = 
    yearsData && yearsData.length > 0 &&
    classesData && classesData.length > 0;

  const handleAssignTeacher = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/teacher-assignments', {
        method: "POST",
        body: {
          academic_term_id: formData.get("academic_term_id"),
          class_section_id: formData.get("class_section_id"),
          subject_id: formData.get("subject_id"),
          teacher_user_id: formData.get("teacher_user_id"),
        }
      });
      setIsAssignModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to assign teacher");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleAssignClassTeacher = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmittingCT(true);
    setCtFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/class-teachers', {
        method: "POST",
        body: {
          academic_year_id: formData.get("academic_year_id"),
          class_section_id: formData.get("class_section_id"),
          teacher_user_id: formData.get("teacher_user_id"),
        }
      });
      setIsClassTeacherModalOpen(false);
      refetch();
    } catch (err: any) {
      setCtFormError(err.message || "Failed to assign class teacher");
    } finally {
      setIsSubmittingCT(false);
    }
  };

  const handleArchiveClassTeacher = async (id: string) => {
    if (!confirm("Are you sure you want to remove this class teacher assignment?")) return;
    try {
      await requestDashboardApi(`/academics/class-teachers/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      toast.error(err.message || "Failed to archive class teacher");
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Staff Overview</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-end gap-2">
        {hasPermission('admin:write') && (
          <Button 
            variant="outline" 
            onClick={() => setIsAssignModalOpen(true)}
            disabled={!hasPrerequisites}
            title={!hasPrerequisites ? "Cannot assign teachers before terms, classes, and subjects exist" : ""}
          >
            <Plus className="h-4 w-4 mr-2" />
            Assign Teacher
          </Button>
        )}
      </div>

      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Total Active Staff</div>
          <div className="mt-2 text-2xl font-black text-white">{data.totalStaff}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Teaching Staff</div>
          <div className="mt-2 text-2xl font-black text-blue-400">{data.teachingStaff}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Support & Admin</div>
          <div className="mt-2 text-2xl font-black text-purple-400">{data.supportStaff}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">On Leave</div>
          <div className="mt-2 text-2xl font-black text-yellow-500">{data.onLeave}</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-6">Staff Distribution</h2>
          <div className="flex-1 flex items-end gap-2 mt-4 min-h-[200px]">
            {data.staffDistribution?.map((item) => (
              <div key={item.label} className="flex-1 flex flex-col items-center gap-2 group">
                <div className="w-full relative bg-white/5 rounded-t-sm" style={{ height: "150px" }}>
                  <div 
                    className="absolute bottom-0 w-full bg-teal-500/50 rounded-t-sm transition-all duration-500 group-hover:bg-teal-400/60"
                    style={{ height: `${Math.min((item.value / Math.max(data.totalStaff, 1)) * 100, 100)}%` }}
                  >
                    <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-opacity">
                      {item.value}
                    </div>
                  </div>
                </div>
                <span className="text-xs text-white/50">{item.label}</span>
              </div>
            ))}
          </div>
        </Card>

      </div>

      <div className="mt-6">
        <h2 className="text-xl font-bold text-white mb-4">Invite & Manage Staff</h2>
        <div className="rounded-[var(--radius-xl)] bg-white p-1">
          <UserManagementPanel />
        </div>
      </div>

      <div className="grid gap-6 md:grid-cols-2 mt-6">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Class Teachers</h2>
            {hasPermission('academics:assign-teachers') && (
              <Button 
                size="sm" 
                variant="outline" 
                onClick={() => setIsClassTeacherModalOpen(true)}
                disabled={!hasCTPrerequisites}
              >
                <Plus className="h-4 w-4 mr-1" /> Assign Class Teacher
              </Button>
            )}
          </div>
          
          {!classTeachersData || classTeachersData.length === 0 ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <Users className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60">No class teachers assigned</p>
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              {classTeachersData.map((ct: any) => (
                <div key={ct.id} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10">
                  <div>
                    <div className="font-medium text-white">Teacher ID: {ct.teacher_user_id}</div>
                    <div className="text-xs text-white/50">Section ID: {ct.class_section_id}</div>
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" variant="outline" className="text-red-400 border-red-500/20 hover:bg-red-500/20" onClick={() => handleArchiveClassTeacher(ct.id)}>
                      Remove
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <Modal open={isAssignModalOpen} onClose={() => setIsAssignModalOpen(false)} title="Assign Subject Teacher">
        <form onSubmit={handleAssignTeacher} className="space-y-4">
          {formError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {formError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Teacher User ID (UUID)</label>
            <input name="teacher_user_id" required className="input-base" placeholder="e.g. 123e4567-e89b-12d3-a456-426614174000" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Academic Term</label>
            <select name="academic_term_id" required className="input-base">
              <option value="">Select Term...</option>
              {termsData?.map(term => (
                <option key={term.id} value={term.id}>{term.name}</option>
              ))}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Class Section</label>
            <select name="class_section_id" required className="input-base">
              <option value="">Select Class Section...</option>
              {classesData?.map(c => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Subject</label>
            <select name="subject_id" required className="input-base">
              <option value="">Select Subject...</option>
              {subjectsData?.map(s => (
                <option key={s.id} value={s.id}>{s.name}</option>
              ))}
            </select>
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Assign Teacher
            </Button>
          </div>
        </form>
      </Modal>

      <Modal open={isClassTeacherModalOpen} onClose={() => setIsClassTeacherModalOpen(false)} title="Assign Class Teacher">
        <form onSubmit={handleAssignClassTeacher} className="space-y-4">
          {ctFormError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {ctFormError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Teacher User ID (UUID)</label>
            <input name="teacher_user_id" required className="input-base" placeholder="e.g. 123e4567-e89b-12d3-a456-426614174000" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Academic Year</label>
            <select name="academic_year_id" required className="input-base">
              <option value="">Select Academic Year...</option>
              {yearsData?.map(year => (
                <option key={year.id} value={year.id}>{year.name}</option>
              ))}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-foreground">Class Section</label>
            <select name="class_section_id" required className="input-base">
              <option value="">Select Class Section...</option>
              {classesData?.map(c => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmittingCT}>
              {isSubmittingCT && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Assign Class Teacher
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { Card } from "@/components/ui/card";
import { AlertCircle, Users, UserPlus, Plus } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useDashboardEventBus } from "@/lib/dashboard-communication/dashboard-communication-provider";
import { useState } from "react";
import { usePermissions } from "@/components/providers/permission-context";
import { Button } from "@/components/ui/button";
import { useRouter } from "next/navigation";
import { buildSchoolSectionHref } from "@/components/school/school-pages";

import { useStudentEvents } from "@/hooks/useStudentEvents";

type PrincipalStudentsData = {
  status: "active" | "degraded" | "setup_required";
  totalStudents: number;
  boys: number;
  girls: number;
  populationTrend: Array<{ label: string; value: number }>;
  recentAdmissions: Array<{ id: string; name: string; class: string; gender: string; admission_date: string }>;
};

export function PrincipalStudentsWorkspace() {
  useStudentEvents();
  const router = useRouter();
  const { data, isLoading, error } = useSchoolQuery<PrincipalStudentsData>('/admin-command/principal/students');
  const eventBus = useDashboardEventBus();
  const { hasPermission } = usePermissions();
  const openAdmissionsWorkspace = () => router.push(buildSchoolSectionHref("admissions", "admissions", "public"));

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Students Overview</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-bold text-white flex items-center gap-2">
          <Users className="h-5 w-5 text-cyan-400" />
          Students Directory
        </h2>
      </div>

      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Status</div>
          <div className="mt-2 text-2xl font-black text-white capitalize">{data.status}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Total Population</div>
          <div className="mt-2 text-2xl font-black text-white">{data.totalStudents}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Boys</div>
          <div className="mt-2 text-2xl font-black text-white">{data.boys}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Girls</div>
          <div className="mt-2 text-2xl font-black text-white">{data.girls}</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-6">Population Trend</h2>
          <div className="flex-1 flex items-end gap-2 mt-4 min-h-[200px]">
            {data.populationTrend?.map((item) => (
              <div key={item.label} className="flex-1 flex flex-col items-center gap-2 group">
                <div className="w-full relative bg-white/5 rounded-t-sm" style={{ height: "150px" }}>
                  <div 
                    className="absolute bottom-0 w-full bg-blue-500/50 rounded-t-sm transition-all duration-500 group-hover:bg-blue-400/60"
                    style={{ height: `${data.totalStudents > 0 ? (item.value / data.totalStudents) * 100 : 0}%` }}
                  >
                    <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-opacity">
                      {item.value}
                    </div>
                  </div>
                </div>
                <span className="text-xs text-white/50">{item.label}</span>
              </div>
            ))}
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Recent Admissions</h2>
            {hasPermission('school_admissions:write') && (
              <Button size="sm" variant="outline" className="text-xs bg-cyan-500/20 text-cyan-400 border-cyan-500/20 hover:bg-cyan-500/30" onClick={openAdmissionsWorkspace}>
                <Plus className="h-3 w-3 mr-1" />
                Admit New
              </Button>
            )}
          </div>
          
          {(!data.recentAdmissions || data.recentAdmissions.length === 0) ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <Users className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60 mb-4">No recent admissions found</p>
              {hasPermission('school_admissions:write') && (
                <Button size="sm" variant="outline" onClick={openAdmissionsWorkspace}>
                  <Plus className="h-4 w-4 mr-2" /> Admit Student
                </Button>
              )}
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              {data.recentAdmissions.map((student) => (
                <div key={student.id} className="p-4 rounded-lg bg-white/5 border border-white/10 hover:bg-white/10 transition-colors">
                  <div className="flex items-center justify-between">
                    <div>
                      <h4 className="font-medium text-white">{student.name}</h4>
                      <p className="text-sm text-white/60">{student.id} • {student.gender}</p>
                    </div>
                    <div className="text-right">
                      <div className="font-bold text-white">{student.class}</div>
                      <div className="text-xs text-white/40">Admitted: {student.admission_date}</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { AlertCircle, BookOpen, Layers, Plus, Loader2, Users2 } from "lucide-react";
import { toast } from "sonner";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { Modal } from "@/components/ui/modal";
import { Button } from "@/components/ui/button";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { usePermissions } from "@/components/providers/permission-context";

type PrincipalSubjectsData = {
  status: "active" | "degraded" | "setup_required";
  totalSubjects: number;
  coreSubjects: number;
  electiveSubjects: number;
  departments: number;
  subjectDistribution: Array<{ label: string; value: number }>;
  departmentHeads: Array<any>;
};

export function PrincipalSubjectsDepartmentsWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<PrincipalSubjectsData>('/admin-command/principal/subjects');
  const { data: yearsData } = useSchoolQuery<any[]>('/academics/academic-years');
  const { data: subjectsData } = useSchoolQuery<any[]>('/academics/subjects');
  const { data: departmentsData } = useSchoolQuery<any[]>('/academics/departments');
  const { hasPermission } = usePermissions();

  const [isSubjectModalOpen, setIsSubjectModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState("");
  const [isDepartmentModalOpen, setIsDepartmentModalOpen] = useState(false);
  const [isSubmittingDept, setIsSubmittingDept] = useState(false);
  const [deptFormError, setDeptFormError] = useState("");

  const hasYears = yearsData && yearsData.length > 0;

  const handleCreateSubject = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/subjects', {
        method: "POST",
        body: {
          code: formData.get("code"),
          name: formData.get("name"),
        }
      });
      setIsSubjectModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to create subject");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleArchiveSubject = async (id: string) => {
    if (!confirm("Are you sure you want to archive this subject?")) return;
    try {
      await requestDashboardApi(`/academics/subjects/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      toast.error(err.message || "Failed to archive subject");
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Subjects Overview</h2>
        </div>
      </Card>
    );
  }

  const handleCreateDepartment = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmittingDept(true);
    setDeptFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/departments', {
        method: "POST",
        body: {
          name: formData.get("name"),
          head_of_department_user_id: formData.get("head_of_department_user_id") || null,
        }
      });
      setIsDepartmentModalOpen(false);
      refetch();
    } catch (err: any) {
      setDeptFormError(err.message || "Failed to create department");
    } finally {
      setIsSubmittingDept(false);
    }
  };

  const handleArchiveDepartment = async (id: string) => {
    if (!confirm("Are you sure you want to archive this department?")) return;
    try {
      await requestDashboardApi(`/academics/departments/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      toast.error(err.message || "Failed to archive department");
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-end">
        {hasPermission('academics:write') && (
          <Button 
            variant="outline" 
            onClick={() => setIsSubjectModalOpen(true)}
            disabled={!hasYears}
            title={!hasYears ? "Cannot create subjects before an academic year is configured" : ""}
          >
            <Plus className="h-4 w-4 mr-2" />
            Create Subject
          </Button>
        )}
      </div>

      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Total Departments</div>
          <div className="mt-2 text-2xl font-black text-white">{data.departments}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Total Subjects</div>
          <div className="mt-2 text-2xl font-black text-white">{data.totalSubjects}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Core Subjects</div>
          <div className="mt-2 text-2xl font-black text-blue-400">{data.coreSubjects}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Elective Subjects</div>
          <div className="mt-2 text-2xl font-black text-green-400">{data.electiveSubjects}</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-white mb-6">Subject Distribution</h2>
          <div className="flex-1 flex items-end gap-2 mt-4 min-h-[200px]">
            {(!data.subjectDistribution || data.subjectDistribution.length === 0) ? (
              <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5 w-full">
                <BookOpen className="h-10 w-10 text-white/20 mb-3" />
                <p className="text-white/60">No subjects found</p>
                <p className="text-xs text-white/40 mt-1">Create subjects to see distribution</p>
              </div>
            ) : (
              data.subjectDistribution.map((item) => (
                <div key={item.label} className="flex-1 flex flex-col items-center gap-2 group">
                  <div className="w-full relative bg-white/5 rounded-t-sm" style={{ height: "150px" }}>
                    <div 
                      className="absolute bottom-0 w-full bg-orange-500/50 rounded-t-sm transition-all duration-500 group-hover:bg-orange-400/60"
                      style={{ height: `${Math.min((item.value / 10) * 100, 100)}%` }}
                    >
                      <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-opacity">
                        {item.value}
                      </div>
                    </div>
                  </div>
                  <span className="text-xs text-white/50">{item.label}</span>
                </div>
              ))
            )}
          </div>
        </Card>

        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Subjects</h2>
          </div>
          
          {!subjectsData || subjectsData.length === 0 ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <BookOpen className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60">No subjects configured</p>
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              {subjectsData.map((s: any) => (
                <div key={s.id} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10">
                  <div>
                    <div className="font-medium text-white">{s.name}</div>
                    <div className="text-xs text-white/50">Code: {s.code}</div>
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" variant="outline" className="text-red-400 border-red-500/20 hover:bg-red-500/20" onClick={() => handleArchiveSubject(s.id)}>
                      Archive
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2 mt-6">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-white">Departments</h2>
            {hasPermission('academics:write') && (
              <Button size="sm" variant="outline" onClick={() => setIsDepartmentModalOpen(true)}>
                <Plus className="h-4 w-4 mr-1" /> Add Department
              </Button>
            )}
          </div>
          
          {!departmentsData || departmentsData.length === 0 ? (
            <div className="flex flex-col items-center justify-center flex-1 py-8 text-center bg-white/5 rounded-lg border border-white/5">
              <Users2 className="h-10 w-10 text-white/20 mb-3" />
              <p className="text-white/60">No departments configured</p>
            </div>
          ) : (
            <div className="space-y-3 flex-1 overflow-y-auto pr-2">
              {departmentsData.map((d: any) => (
                <div key={d.id} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10">
                  <div>
                    <div className="font-medium text-white">{d.name}</div>
                    <div className="text-xs text-white/50">{d.head_of_department_user_id ? "Has HOD" : "No HOD assigned"}</div>
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" variant="outline" className="text-red-400 border-red-500/20 hover:bg-red-500/20" onClick={() => handleArchiveDepartment(d.id)}>
                      Archive
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      <Modal open={isSubjectModalOpen} onClose={() => setIsSubjectModalOpen(false)} title="Create Subject">
        <form onSubmit={handleCreateSubject} className="space-y-4">
          {formError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {formError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-medium">Subject Code</label>
            <input name="code" required className="w-full border rounded p-2 text-sm" placeholder="e.g. MAT, ENG, SCI" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">Subject Name</label>
            <input name="name" required className="w-full border rounded p-2 text-sm" placeholder="e.g. Mathematics" />
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Subject
            </Button>
          </div>
        </form>
      </Modal>

      <Modal open={isDepartmentModalOpen} onClose={() => setIsDepartmentModalOpen(false)} title="Create Department">
        <form onSubmit={handleCreateDepartment} className="space-y-4">
          {deptFormError && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm">
              {deptFormError}
            </div>
          )}
          <div className="space-y-2">
            <label className="text-sm font-medium">Department Name</label>
            <input name="name" required className="w-full border rounded p-2 text-sm" placeholder="e.g. Languages, Sciences" />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium">HOD User ID (Optional UUID)</label>
            <input name="head_of_department_user_id" className="w-full border rounded p-2 text-sm" placeholder="e.g. 123e4567-e89b-12d3-a456-426614174000" />
          </div>
          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={isSubmittingDept}>
              {isSubmittingDept && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Department
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";
import { useState } from "react";
import { Calendar, Plus } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, MetricCard, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { createAcademicYear, createTerm } from "./api-client";

type TermRecord = { id: string; name: string; start_date: string; end_date: string; status: string };
type AcademicYearRecord = { id: string; year: string; status: string; terms: TermRecord[] };

type AcademicSetupData = {
  metrics: { total_years: number; active_year: string; current_term: string; };
  years: AcademicYearRecord[];
};

export function AcademicSetupWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<AcademicSetupData>('/admin-command/principal/academic-setup');
  const [isCreating, setIsCreating] = useState(false);

  const years = data?.years || [];

  const getStatusTone = (s: string): Tone => {
    if (s === "Active" || s === "active") return "success";
    if (s === "Upcoming" || s === "upcoming") return "info";
    if (s === "Completed" || s === "completed") return "neutral";
    return "neutral";
  };

  const handleCreateYear = async () => {
    setIsCreating(true);
    try {
      await createAcademicYear({ year: new Date().getFullYear().toString() });
      await refetch();
      toast.success("Academic year created.");
    } catch {
      toast.error("Failed to create academic year.");
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <Panel
      title="Academic Setup"
      description="Manage academic years, terms, and the school calendar."
      icon={Calendar}
      actions={
        <button disabled={isCreating} onClick={handleCreateYear} className="inline-flex items-center gap-2 rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition disabled:opacity-50">
          <Plus className="h-4 w-4" />
          {isCreating ? "Creating…" : "Add Academic Year"}
        </button>
      }
    >
      <div className="grid gap-4 md:grid-cols-3 mb-6">
        <MetricCard label="Total Academic Years" value={isLoading ? "…" : data?.metrics?.total_years ?? 0} icon={Calendar} />
        <MetricCard label="Active Year" value={isLoading ? "…" : data?.metrics?.active_year ?? "None"} icon={Calendar} tone="success" />
        <MetricCard label="Current Term" value={isLoading ? "…" : data?.metrics?.current_term ?? "None"} icon={Calendar} tone="info" />
      </div>

      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Academic Year</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Terms</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={4} className="px-4 py-8 text-center text-[#64748B]">Loading academic setup…</td></tr>
            ) : years.length === 0 ? (
              <tr><td colSpan={4} className="px-4 py-8 text-center text-[#64748B]">No academic years configured. Add the first academic year to begin setting up your school calendar.</td></tr>
            ) : (
              years.map((yr) => (
                <tr key={yr.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{yr.year}</td>
                  <td className="px-4 py-3"><StatusChip label={yr.status} tone={getStatusTone(yr.status)} /></td>
                  <td className="px-4 py-3 text-[#64748B]">
                    {yr.terms.length === 0 ? "No terms" : yr.terms.map(t => t.name).join(", ")}
                  </td>
                  <td className="px-4 py-3 text-right">
                    <button className="text-blue-600 hover:underline font-semibold text-xs">Manage Terms</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

