"use client";
import { useState } from "react";
import { LayoutDashboard, Users, GraduationCap, DollarSign, UserCheck, UserX, AlertTriangle, ClipboardCheck, ShieldAlert } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, MetricCard, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";

type AlertItem = {
  id: string;
  title: string;
  category: string;
  severity: string;
  timestamp: string;
  status: string;
};

type OverviewData = {
  metrics: {
    total_students: number;
    total_staff: number;
    attendance_rate: number;
    fee_collection_rate: number;
    pending_approvals: number;
    open_discipline_cases: number;
  };
  alerts: AlertItem[];
};

export function OverviewWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<OverviewData>('/admin-command/principal/overview');
  const [isRefreshing, setIsRefreshing] = useState(false);

  const metrics = data?.metrics;
  const alerts = data?.alerts || [];

  const handleRefresh = async () => {
    setIsRefreshing(true);
    try {
      await refetch();
      toast.success("Dashboard refreshed.");
    } catch {
      toast.error("Failed to refresh dashboard.");
    } finally {
      setIsRefreshing(false);
    }
  };

  const getSeverityTone = (severity: string): Tone => {
    switch (severity?.toLowerCase()) {
      case "critical": return "danger";
      case "high": return "danger";
      case "medium": return "warning";
      case "low": return "info";
      default: return "neutral";
    }
  };

  const getStatusTone = (status: string): Tone => {
    switch (status?.toLowerCase()) {
      case "resolved": return "success";
      case "in_progress": case "in progress": return "info";
      case "pending": return "warning";
      case "open": return "danger";
      default: return "neutral";
    }
  };

  return (
    <Panel
      title="Principal Overview"
      description="School-wide snapshot — key metrics, alerts, and items requiring your attention."
      icon={LayoutDashboard}
      actions={
        <button disabled={isRefreshing} onClick={handleRefresh} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition disabled:opacity-50">
          {isRefreshing ? "Refreshing…" : "Refresh"}
        </button>
      }
    >
      {/* Metrics */}
      <div className="grid gap-4 md:grid-cols-3 lg:grid-cols-6 mb-6">
        <MetricCard label="Total Students" value={isLoading ? "…" : metrics?.total_students ?? 0} icon={GraduationCap} />
        <MetricCard label="Total Staff" value={isLoading ? "…" : metrics?.total_staff ?? 0} icon={Users} />
        <MetricCard label="Attendance Rate" value={isLoading ? "…" : `${metrics?.attendance_rate ?? 0}%`} icon={UserCheck} tone={(metrics?.attendance_rate ?? 100) < 80 ? "danger" : "success"} />
        <MetricCard label="Fee Collection" value={isLoading ? "…" : `${metrics?.fee_collection_rate ?? 0}%`} icon={DollarSign} tone={(metrics?.fee_collection_rate ?? 100) < 70 ? "warning" : "success"} />
        <MetricCard label="Pending Approvals" value={isLoading ? "…" : metrics?.pending_approvals ?? 0} icon={ClipboardCheck} tone={(metrics?.pending_approvals ?? 0) > 0 ? "warning" : "success"} />
        <MetricCard label="Discipline Cases" value={isLoading ? "…" : metrics?.open_discipline_cases ?? 0} icon={ShieldAlert} tone={(metrics?.open_discipline_cases ?? 0) > 0 ? "danger" : "success"} />
      </div>

      {/* Alerts Table */}
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Severity</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Alert</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Category</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Time</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">Loading school overview…</td></tr>
            ) : alerts.length === 0 ? (
              <tr><td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">No active alerts. Your school is running smoothly.</td></tr>
            ) : (
              alerts.map((alert) => (
                <tr key={alert.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3"><StatusChip label={alert.severity} tone={getSeverityTone(alert.severity)} /></td>
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{alert.title}</td>
                  <td className="px-4 py-3 text-[#64748B]">{alert.category}</td>
                  <td className="px-4 py-3 text-[#64748B]">{alert.timestamp}</td>
                  <td className="px-4 py-3"><StatusChip label={alert.status} tone={getStatusTone(alert.status)} /></td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";

import { useState, type FormEvent } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Search, ShoppingCart, FileText, Truck, DollarSign, LayoutDashboard, Plus, Package } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Modal } from "@/components/ui/modal";
import { StatusPill } from "@/components/ui/status-pill";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { buildSchoolSectionHref } from "./school-pages";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { openPrintDocument } from "@/lib/dashboard/export";
import { toast } from "sonner";

type ProcurementView = "overview" | "pos" | "suppliers" | "requisitions" | "budget";

function procurementActionSlug(message: string) {
  return message
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ".")
    .replace(/^\.+|\.+$/g, "") || "workflow.action";
}

async function recordProcurementAction(setNotice: (message: string | null) => void, message: string, title = "Procurement workflow action") {
  try {
    await requestDashboardApi("/api/admin-command/procurement-officer/actions", {
      method: "POST",
      body: {
        action: procurementActionSlug(message),
        title,
        description: message,
        priority: /approval|delivery|budget|blocked|overdue/i.test(message) ? "high" : "normal",
        source: "procurement-officer-dashboard",
      },
    });
    setNotice(message);
  } catch (error) {
    toast.error("Procurement action was not saved", {
      description: error instanceof Error ? error.message : "The procurement workflow could not be persisted for audit and follow-up.",
    });
  }
}

function openProcurementRecord(title: string, rows: Array<[string, string]>) {
  openPrintDocument({
    eyebrow: "MyShule Procurement",
    title,
    subtitle: `Generated ${new Date().toLocaleString()}`,
    rows: rows.map(([label, value]) => ({ label, value })),
    footer: "Procurement records are tenant-scoped and should match supplier, requisition, delivery, and audit records.",
  });
}

function Panel({ title, description, icon: Icon, children, actions }: { title: string; description?: string; icon?: any; children: React.ReactNode; actions?: React.ReactNode }) {
  return (
    <section className="rounded-2xl border border-[#D8E0EC] bg-white p-5 shadow-[0_18px_50px_rgba(7,29,73,0.08)]">
      <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 gap-3">
          {Icon && (
            <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#EEF5FF] text-[#1D4ED8]">
              <Icon className="h-5 w-5" aria-hidden="true" />
            </span>
          )}
          <div>
            <h2 className="text-xl font-black tracking-[-0.01em] text-[#071D49]">{title}</h2>
            {description && <p className="mt-1 text-sm leading-6 text-[#64748B]">{description}</p>}
          </div>
        </div>
        {actions && <div className="shrink-0">{actions}</div>}
      </div>
      {children}
    </section>
  );
}

function OverviewWorkspace() {
  const { data: posData } = useSchoolQuery<any>("/api/inventory/purchase-orders?limit=5");
  const { data: reqsData } = useSchoolQuery<any>("/api/inventory/requests?status=pending");
  const { data: summaryData } = useSchoolQuery<any>("/api/inventory/summary");

  const pendingReqs = reqsData?.meta?.total_items ?? 0;
  const activePOs = posData?.meta?.total_items ?? 0;
  const awaitingDelivery = summaryData?.awaiting_delivery ?? 0;
  const recentPOs = posData?.data ?? [];

  return (
    <>
      <div className="grid gap-6 md:grid-cols-3 mb-8">
        <Card className="p-6">
          <div className="text-sm font-semibold text-gray-500">Pending Requisitions</div>
          <div className="mt-2 text-3xl font-black text-[#071D49]">{pendingReqs}</div>
        </Card>
        <Card className="p-6">
          <div className="text-sm font-semibold text-gray-500">Active Purchase Orders</div>
          <div className="mt-2 text-3xl font-black text-[#071D49]">{activePOs}</div>
        </Card>
        <Card className="p-6">
          <div className="text-sm font-semibold text-gray-500">Awaiting Delivery</div>
          <div className="mt-2 text-3xl font-black text-[#071D49]">{awaitingDelivery}</div>
