    addLabExecutionLog(`${issue?.item ?? "Apparatus"} breakage recorded`, ["Breakage saved", "Replacement follow-up available"]);
    setLabNotice(`${issue?.item ?? "Apparatus"} breakage recorded for follow-up.`);
  }

