                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { ListOrdered, Plus, UserCheck, CheckCircle } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { callNextInQueue, completeQueueEntry } from "./api-client";

type QueueEntry = {
  id: string;
  ticket_number: string;
  visitor_name: string;
  purpose: string;
  person_to_see: string;
  arrival_time: string;
  status: string;
  wait_time_minutes: number;
};

type QueueData = {
  metrics: {
    total_in_queue: number;
    being_served: number;
    completed_today: number;
    avg_wait_minutes: number;
  };
  queue: QueueEntry[];
};

export function ReceptionQueueWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<QueueData>('/admin-command/secretary/reception-queue');
  const [actionId, setActionId] = useState<string | null>(null);

  const queue = data?.queue || [];
  const metrics = data?.metrics;

  const getStatusTone = (status: string): Tone => {
    switch (status) {
      case "Waiting": return "warning";
      case "Being Served": return "info";
      case "Completed": return "success";
      case "No Show": return "danger";
      default: return "neutral";
    }
  };

  const handleCallNext = async (id: string) => {
    setActionId(id);
    try {
      await callNextInQueue(id);
      toast.success("Visitor called. They are now being served.");
      refetch();
    } catch {
      toast.error("Failed to call visitor.");
    } finally {
      setActionId(null);
    }
  };

  const handleComplete = async (id: string) => {
    setActionId(id);
    try {
      await completeQueueEntry(id);
      toast.success(`Queue ticket ${id} closed and reception metrics refreshed.`);
      refetch();
    } catch {
      toast.error("Failed to complete visit.");
    } finally {
      setActionId(null);
    }
  };

  return (
    <Panel title="Reception Queue" description="Manage walk-in visitors and waiting queue." icon={ListOrdered}>
      {/* Metrics */}
      <div className="grid gap-4 md:grid-cols-4 mb-6">
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-4">
          <div className="text-sm font-semibold text-amber-700">In Queue</div>
          <div className="mt-1 text-2xl font-black text-amber-700">{isLoading ? "..." : metrics?.total_in_queue || 0}</div>
        </div>
        <div className="rounded-xl border border-blue-200 bg-blue-50 p-4">
          <div className="text-sm font-semibold text-blue-700">Being Served</div>
          <div className="mt-1 text-2xl font-black text-blue-700">{isLoading ? "..." : metrics?.being_served || 0}</div>
        </div>
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4">
          <div className="text-sm font-semibold text-emerald-700">Completed Today</div>
          <div className="mt-1 text-2xl font-black text-emerald-700">{isLoading ? "..." : metrics?.completed_today || 0}</div>
        </div>
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Avg Wait (min)</div>
          <div className="mt-1 text-2xl font-black text-[#071D49]">{isLoading ? "..." : metrics?.avg_wait_minutes || 0}</div>
        </div>
      </div>

      {/* Queue Table */}
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Ticket</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Visitor Name</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Purpose</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Person to See</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Arrival</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Wait (min)</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={8} className="px-4 py-8 text-center text-[#64748B]">Loading queue...</td></tr>
            ) : queue.length === 0 ? (
              <tr><td colSpan={8} className="px-4 py-8 text-center text-[#64748B]">No visitors in the queue. New walk-in visitors will appear here when checked in at reception.</td></tr>
            ) : (
              queue.map((entry) => (
                <tr key={entry.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-mono font-bold text-[#071D49]">{entry.ticket_number}</td>
                  <td className="px-4 py-3 font-medium text-[#071D49]">{entry.visitor_name}</td>
                  <td className="px-4 py-3 text-[#64748B]">{entry.purpose}</td>
                  <td className="px-4 py-3 text-[#64748B]">{entry.person_to_see}</td>
                  <td className="px-4 py-3 text-[#64748B]">{entry.arrival_time}</td>
                  <td className="px-4 py-3 text-[#64748B]">{entry.wait_time_minutes}</td>
                  <td className="px-4 py-3"><StatusChip label={entry.status} tone={getStatusTone(entry.status)} /></td>
                  <td className="px-4 py-3 text-right">
                    <div className="flex items-center justify-end gap-2">
                      {entry.status === "Waiting" && (
                        <button disabled={actionId === entry.id} onClick={() => handleCallNext(entry.id)} className="inline-flex items-center gap-1 rounded-lg bg-blue-600 px-3 py-1.5 text-xs font-bold text-white hover:bg-blue-700 disabled:opacity-50">
                          <UserCheck className="w-3 h-3" /> Call
                        </button>
                      )}
                      {entry.status === "Being Served" && (
                        <button disabled={actionId === entry.id} onClick={() => handleComplete(entry.id)} className="inline-flex items-center gap-1 rounded-lg bg-emerald-600 px-3 py-1.5 text-xs font-bold text-white hover:bg-emerald-700 disabled:opacity-50">
                          <CheckCircle className="w-3 h-3" /> Complete
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { ClipboardCheck, CheckCircle, Printer, UserX } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { approveClearanceStep, completeClearance, printClearanceForm } from "./api-client";

type ClearanceRecord = {
  id: string;
  student_name: string;
  admission_number: string;
  class: string;
  reason: string;
  initiated_by: string;
  initiated_date: string;
  status: string;
  steps_completed: number;
  total_steps: number;
  pending_departments: string[];
};

type ClearanceData = {
  metrics: {
    active_clearances: number;
    completed: number;
    pending_approval: number;
    blocked: number;
  };
  clearances: ClearanceRecord[];
};

export function StudentClearanceWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<ClearanceData>('/admin-command/secretary/student-clearance');
  const [actionId, setActionId] = useState<string | null>(null);

  const clearances = data?.clearances || [];
  const metrics = data?.metrics;

  const getStatusTone = (status: string): Tone => {
    switch (status) {
      case "Completed": return "success";
      case "In Progress": return "info";
      case "Pending": return "warning";
      case "Blocked": return "danger";
      default: return "neutral";
    }
  };

  const handleComplete = async (id: string) => {
    setActionId(id);
    try {
      await completeClearance(id);
      toast.success(`Clearance ${id} marked complete and department checklist refreshed.`);
      refetch();
    } catch {
      toast.error("Failed to complete clearance.");
    } finally {
      setActionId(null);
    }
  };

  const handlePrint = async (id: string) => {
    setActionId(id);
    try {
      await printClearanceForm(id);
      toast.success("Clearance form sent to printer.");
    } catch {
      toast.error("Failed to print clearance form.");
    } finally {
      setActionId(null);
    }
  };

  return (
    <Panel title="Student Clearance" description="Process student clearance for transfers, graduation, and departures." icon={ClipboardCheck}>
      {/* Metrics */}
      <div className="grid gap-4 md:grid-cols-4 mb-6">
        <div className="rounded-xl border border-blue-200 bg-blue-50 p-4">
          <div className="text-sm font-semibold text-blue-700">Active Clearances</div>
          <div className="mt-1 text-2xl font-black text-blue-700">{isLoading ? "..." : metrics?.active_clearances || 0}</div>
        </div>
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4">
          <div className="text-sm font-semibold text-emerald-700">Completed</div>
          <div className="mt-1 text-2xl font-black text-emerald-700">{isLoading ? "..." : metrics?.completed || 0}</div>
        </div>
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-4">
          <div className="text-sm font-semibold text-amber-700">Pending Approval</div>
          <div className="mt-1 text-2xl font-black text-amber-700">{isLoading ? "..." : metrics?.pending_approval || 0}</div>
        </div>
        <div className="rounded-xl border border-rose-200 bg-rose-50 p-4">
          <div className="flex items-center gap-2 text-sm font-semibold text-rose-700"><UserX className="w-4 h-4" /> Blocked</div>
          <div className="mt-1 text-2xl font-black text-rose-700">{isLoading ? "..." : metrics?.blocked || 0}</div>
        </div>
      </div>

      {/* Clearance Table */}
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Student</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Adm No.</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Class</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Reason</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Initiated</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Progress</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Pending Depts</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={9} className="px-4 py-8 text-center text-[#64748B]">Loading clearance records...</td></tr>
            ) : clearances.length === 0 ? (
              <tr><td colSpan={9} className="px-4 py-8 text-center text-[#64748B]">No active clearance requests. Initiate a clearance when a student is transferring, graduating, or departing.</td></tr>
            ) : (
              clearances.map((c) => (
                <tr key={c.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-medium text-[#071D49]">{c.student_name}</td>
                  <td className="px-4 py-3 font-mono text-[#64748B]">{c.admission_number}</td>
                  <td className="px-4 py-3 text-[#64748B]">{c.class}</td>
                  <td className="px-4 py-3 text-[#64748B]">{c.reason}</td>
                  <td className="px-4 py-3 text-[#64748B]">{c.initiated_date}</td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      <div className="h-2 w-20 rounded-full bg-slate-200 overflow-hidden">
                        <div className="h-full rounded-full bg-blue-500" style={{ width: `${c.total_steps > 0 ? (c.steps_completed / c.total_steps) * 100 : 0}%` }} />
                      </div>
                      <span className="text-xs font-bold text-[#64748B]">{c.steps_completed}/{c.total_steps}</span>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-[#64748B] text-xs">{c.pending_departments.length > 0 ? c.pending_departments.join(", ") : "—"}</td>
                  <td className="px-4 py-3"><StatusChip label={c.status} tone={getStatusTone(c.status)} /></td>
                  <td className="px-4 py-3 text-right">
                    <div className="flex items-center justify-end gap-2">
                      {c.status === "In Progress" && c.steps_completed === c.total_steps && (
                        <button disabled={actionId === c.id} onClick={() => handleComplete(c.id)} className="inline-flex items-center gap-1 rounded-lg bg-emerald-600 px-3 py-1.5 text-xs font-bold text-white hover:bg-emerald-700 disabled:opacity-50">
                          <CheckCircle className="w-3 h-3" /> Complete
                        </button>
                      )}
                      <button disabled={actionId === c.id} onClick={() => handlePrint(c.id)} className="inline-flex items-center gap-1 rounded-lg border border-[#D8E0EC] bg-white px-3 py-1.5 text-xs font-bold text-[#071D49] hover:bg-[#F8FAFC] disabled:opacity-50">
                        <Printer className="w-3 h-3" /> Print
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

