                  <td className="px-4 py-3 text-[#64748B]">{row.item_name}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.quantity}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.issued_to}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.department}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.date}</td>
                  <td className="px-4 py-3"><span className="inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-bold whitespace-nowrap">{row.status}</span></td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import { ClipboardList, Plus, CheckCircle } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { startStocktake, submitStocktakeCount, finalizeStocktake } from "./api-client";
import { Modal } from "@/components/ui/modal";
import { useForm } from "react-hook-form";

type StocktakeRecord = {
  id: string;
  title: string;
  category_scope: string;
  started_by: string;
  start_date: string;
  end_date: string | null;
  total_items_counted: number;
  total_items_expected: number;
  discrepancies: number;
  status: string;
};

type StocktakeData = {
  metrics: {
    total_stocktakes: number;
    in_progress: number;
    completed_this_term: number;
    total_discrepancies: number;
  };
  stocktakes: StocktakeRecord[];
};

type StartStocktakeFormData = {
  title: string;
  scope: string;
};

export function StocktakeWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<StocktakeData>('/admin-command/storekeeper/stocktake');
  const [isStarting, setIsStarting] = useState(false);
  const [finalizing, setFinalizing] = useState<string | null>(null);

  const [isStartOpen, setIsStartOpen] = useState(false);

  const startForm = useForm<StartStocktakeFormData>({
    defaultValues: {
      title: "",
      scope: "All",
    }
  });

  const stocktakes = data?.stocktakes || [];

  const getStatusTone = (status: string): Tone => {
    if (status === "Completed") return "success";
    if (status === "In Progress") return "info";
    if (status === "Pending Review") return "warning";
    if (status === "Discrepancies Found") return "danger";
    return "neutral";
  };

  const onSubmitStartStocktake = async (formData: StartStocktakeFormData) => {
    setIsStarting(true);
    try {
      await startStocktake({ title: formData.title, category_scope: formData.scope });
      toast.success(`Stocktake "${formData.title}" started.`);
      setIsStartOpen(false);
      startForm.reset();
      refetch();
    } catch {
      toast.error("Failed to start stocktake.");
    } finally {
      setIsStarting(false);
    }
  };

  const handleFinalize = async (st: StocktakeRecord) => {
    if (!confirm(`Finalize stocktake "${st.title}"? This will update inventory levels and log all discrepancies.`)) return;
    setFinalizing(st.id);
    try {
      await finalizeStocktake(st.id);
      toast.success(`Stocktake "${st.title}" finalized. Inventory updated.`);
      refetch();
    } catch {
      toast.error("Failed to finalize stocktake.");
    } finally {
      setFinalizing(null);
    }
  };

  return (
    <Panel
      title="Stocktake"
      description="Perform physical stock counts and reconcile with system records."
      icon={ClipboardList}
      actions={
        <button
          onClick={() => {
            startForm.reset();
            setIsStartOpen(true);
          }}
          className="inline-flex items-center gap-2 rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition disabled:opacity-50"
        >
          <Plus className="h-4 w-4" /> New Stocktake
        </button>
      }
    >
      {/* Metrics */}
      <div className="grid gap-4 md:grid-cols-4 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Total Stocktakes</div>
          <div className="mt-1 text-2xl font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total_stocktakes || 0}</div>
        </div>
        <div className="rounded-xl border border-blue-200 bg-blue-50 p-4">
          <div className="text-sm font-semibold text-blue-700">In Progress</div>
          <div className="mt-1 text-2xl font-black text-blue-700">{isLoading ? "..." : data?.metrics?.in_progress || 0}</div>
        </div>
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4">
          <div className="text-sm font-semibold text-emerald-700">Completed This Term</div>
          <div className="mt-1 text-2xl font-black text-emerald-700">{isLoading ? "..." : data?.metrics?.completed_this_term || 0}</div>
        </div>
        <div className="rounded-xl border border-rose-200 bg-rose-50 p-4">
          <div className="text-sm font-semibold text-rose-700">Discrepancies Found</div>
          <div className="mt-1 text-2xl font-black text-rose-700">{isLoading ? "..." : data?.metrics?.total_discrepancies || 0}</div>
        </div>
      </div>

      {/* Stocktakes Table */}
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Title</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Scope</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Started By</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Start Date</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Counted</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Discrepancies</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={8} className="px-4 py-8 text-center text-[#64748B]">Loading stocktakes...</td></tr>
            ) : stocktakes.length === 0 ? (
              <tr><td colSpan={8} className="px-4 py-8 text-center text-[#64748B]">No stocktakes recorded. Start a new stocktake to reconcile physical and system stock levels.</td></tr>
            ) : (
              stocktakes.map((st) => (
                <tr key={st.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{st.title}</td>
                  <td className="px-4 py-3 text-[#64748B]">{st.category_scope}</td>
                  <td className="px-4 py-3 text-[#64748B]">{st.started_by}</td>
                  <td className="px-4 py-3 text-[#64748B]">{st.start_date}</td>
                  <td className="px-4 py-3 text-[#071D49]">{st.total_items_counted}/{st.total_items_expected}</td>
                  <td className="px-4 py-3">
                    {st.discrepancies > 0 ? (
                      <span className="font-bold text-rose-600">{st.discrepancies}</span>
                    ) : (
                      <span className="text-emerald-600 font-bold">0</span>
                    )}
                  </td>
                  <td className="px-4 py-3"><StatusChip label={st.status} tone={getStatusTone(st.status)} /></td>
                  <td className="px-4 py-3 text-right">
                    {st.status === "In Progress" || st.status === "Pending Review" ? (
                      <button
                        disabled={finalizing === st.id}
                        onClick={() => handleFinalize(st)}
                        className="inline-flex items-center gap-1 text-emerald-600 hover:underline font-semibold text-xs disabled:opacity-50"
                      >
                        <CheckCircle className="h-3 w-3" /> {finalizing === st.id ? "Finalizing..." : "Finalize"}
                      </button>
                    ) : (
                      <span className="text-xs text-[#64748B]">View Report</span>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Start Stocktake Modal */}
      <Modal
        open={isStartOpen}
        onClose={() => setIsStartOpen(false)}
        title="Start New Stocktake"
      >
        <form onSubmit={startForm.handleSubmit(onSubmitStartStocktake)} className="space-y-4 py-4">
          <div className="space-y-1">
            <label className="text-sm font-medium">Stocktake Title</label>
            <input
              type="text"
              {...startForm.register("title", { required: "Title is required" })}
              className="w-full rounded border border-slate-300 p-2 text-sm text-[#071D49]"
              placeholder="e.g. Term 2 Full Stocktake"
            />
            {startForm.formState.errors.title && (
              <span className="text-xs text-red-500">{startForm.formState.errors.title.message}</span>
            )}
          </div>

          <div className="space-y-1">
            <label className="text-sm font-medium">Category Scope</label>
            <input
              type="text"
              {...startForm.register("scope", { required: "Scope is required" })}
              className="w-full rounded border border-slate-300 p-2 text-sm text-[#071D49]"
              placeholder="e.g. All, Stationery, Lab Supplies"
            />
            {startForm.formState.errors.scope && (
              <span className="text-xs text-red-500">{startForm.formState.errors.scope.message}</span>
            )}
          </div>

          <div className="flex justify-end space-x-3 pt-4 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setIsStartOpen(false)}
              className="px-4 py-2 border rounded text-sm font-medium hover:bg-slate-50 text-[#071D49]"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isStarting}
              className="px-4 py-2 bg-[#071D49] text-white rounded text-sm font-medium hover:bg-blue-900 disabled:opacity-50"
            >
              {isStarting ? "Starting..." : "Start Stocktake"}
            </button>
          </div>
        </form>
      </Modal>
    </Panel>
  );
}

"use client";

import { Calendar, BookOpen, GraduationCap, Award } from "lucide-react";
import { Card } from "@/components/ui/card";
import { useSchoolQuery } from "@/lib/data/school-hooks";

export function StudentCommandCenter({ routeMode, activeSection }: { routeMode?: "hosted" | "public", activeSection?: string }) {
  const { data: response, isLoading } = useSchoolQuery<any>("/api/student/dashboard");
  const dashboard = response?.data || response;

  return (
    <div className="min-h-screen bg-[#F3F6FA]">
      <div className="mx-auto max-w-7xl p-4 lg:p-6">
        
        {/* Main Content */}
        <main className="w-full">
          <div className="min-h-[calc(100vh-3rem)] rounded-2xl bg-white shadow-[0_2px_40px_rgba(7,29,73,0.04)] overflow-hidden">
            
            <header className="sticky top-0 z-20 border-b border-[#D8E0EC] bg-[#F3F6FA]/90 px-4 py-4 backdrop-blur sm:px-8">
              <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                <div className="flex items-center gap-4">
                  <div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#071D49] text-sm font-black text-white">MS</div>
                  <div>
                    <h1 className="text-2xl font-black text-[#071D49]">{isLoading ? "My Learner Portal" : `Welcome, ${dashboard?.profile?.name || "Student"}`}</h1>
                    <p className="text-sm font-semibold text-[#64748B]">
                      {isLoading ? "Loading..." : `${dashboard?.profile?.className || "Grade 10"} ${dashboard?.profile?.streamName || "West"} • Admission No: ${dashboard?.profile?.admissionNumber || "N/A"}`}
                    </p>
                  </div>
                </div>
              </div>
            </header>

            <div className="p-4 sm:p-8">
              <div className="grid gap-6 md:grid-cols-4 mb-8">
                <Card className="p-6 border-l-4 border-l-blue-500">
                  <div className="flex items-center gap-3 text-blue-600 mb-2">
                    <Calendar className="h-5 w-5" />
                    <span className="font-bold">Next Class</span>
                  </div>
                  <div className="text-2xl font-black text-[#071D49]">
                    {isLoading ? "..." : dashboard?.academics?.nextClass || "No Class"}
                  </div>
                  <div className="text-sm font-semibold text-gray-500">
                    {isLoading ? "..." : `${dashboard?.academics?.nextClassTime || "11:00 AM"} • ${dashboard?.academics?.nextClassRoom || "Room 4"}`}
                  </div>
                </Card>

                <Card className="p-6 border-l-4 border-l-orange-500">
                  <div className="flex items-center gap-3 text-orange-600 mb-2">
                    <BookOpen className="h-5 w-5" />
                    <span className="font-bold">Assignments</span>
                  </div>
                  <div className="text-2xl font-black text-[#071D49]">
                    {isLoading ? "..." : `${dashboard?.metrics?.pendingAssignments ?? dashboard?.assignments?.pendingCount ?? 0} Due`}
                  </div>
                  <div className="text-sm font-semibold text-gray-500">Pending tasks</div>
                </Card>

                <Card className="p-6 border-l-4 border-l-green-500">
                  <div className="flex items-center gap-3 text-green-600 mb-2">
                    <GraduationCap className="h-5 w-5" />
                    <span className="font-bold">Attendance</span>
                  </div>
                  <div className="text-2xl font-black text-[#071D49]">
                    {isLoading ? "..." : `${dashboard?.metrics?.attendanceRate ?? dashboard?.attendance?.percentage ?? 95}%`}
                  </div>
                  <div className="text-sm font-semibold text-gray-500">This Term</div>
                </Card>

                <Card className="p-6 border-l-4 border-l-purple-500">
                  <div className="flex items-center gap-3 text-purple-600 mb-2">
                    <Award className="h-5 w-5" />
                    <span className="font-bold">Average Grade</span>
                  </div>
                  <div className="text-2xl font-black text-[#071D49]">
                    {isLoading ? "..." : dashboard?.metrics?.averageGrade ?? "B+"}
                  </div>
                  <div className="text-sm font-semibold text-gray-500">
                    {isLoading ? "..." : dashboard?.exams?.latestTitle || "Overall average"}
                  </div>
                </Card>
              </div>

              <div className="grid gap-8 md:grid-cols-2">
                <Card className="p-6">
                  <h2 className="text-xl font-bold text-[#071D49] mb-4">My Timetable (Today)</h2>
                  <div className="space-y-4">
                    {isLoading ? (
                      <div className="p-4 text-center text-gray-500 text-sm">Loading timetable...</div>
                    ) : dashboard?.timetableToday?.length > 0 ? (
                      dashboard.timetableToday.map((slot: any, idx: number) => {
                        const isNow = slot.status === "Now";
                        const isDone = slot.status === "Completed";
                        return (
                          <div key={idx} className={`flex items-center justify-between p-3 rounded-lg border ${
                            isNow ? "bg-blue-50 border-blue-100" : isDone ? "bg-gray-50 border-gray-100" : "border-gray-100"
                          }`}>
                            <div>
                              <div className={`font-bold ${isNow ? "text-blue-900" : isDone ? "text-[#071D49]" : "text-gray-600"}`}>
                                {slot.time}
                              </div>
                              <div className={`text-sm ${isNow ? "text-blue-700" : isDone ? "text-gray-600" : "text-gray-500"}`}>
                                {slot.subject}
                              </div>
                            </div>
                            <span className={`px-2 py-1 text-xs font-bold rounded ${
                              isNow ? "bg-blue-200 text-blue-800 animate-pulse" : isDone ? "bg-gray-200" : "bg-gray-100 text-gray-500"
                            }`}>
                              {slot.status}
                            </span>
                          </div>
                        );
                      })
                    ) : (
                      <div className="p-4 text-center text-gray-500 text-sm">No classes scheduled for today.</div>
                    )}
                  </div>
                </Card>

                <Card className="p-6">
                  <h2 className="text-xl font-bold text-[#071D49] mb-4">Recent Activity & Grades</h2>
                  {isLoading ? (
                    <div className="text-center py-12 text-gray-500">Loading activity...</div>
                  ) : dashboard?.recentActivity?.length > 0 ? (
                    <div className="space-y-4">
                      {dashboard.recentActivity.map((act: any, idx: number) => (
                        <div key={idx} className="flex justify-between items-center p-3 rounded-lg border border-gray-100">
                          <div>
                            <p className="font-bold text-[#071D49]">{act.title || act.description}</p>
                            <p className="text-xs text-gray-500">{act.date ? new Date(act.date).toLocaleDateString() : ""}</p>
                          </div>
                          {act.score && (
                            <span className="px-2 py-1 text-xs font-bold rounded bg-green-100 text-green-800">
                              {act.score}
                            </span>
                          )}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="text-center py-12 text-gray-500">
                      <GraduationCap className="h-12 w-12 mx-auto mb-4 opacity-20" />
                      <p>Report cards and recent assessment results will appear here.</p>
                    </div>
                  )}
                </Card>
              </div>
            </div>
            
          </div>
        </main>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Download, BookOpen, Clock, CheckCircle, FileText } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { openPrintDocument } from "@/lib/dashboard/export";
import { toast } from "sonner";

export function AcademicsWorkspace() {
  // Fetch real data from the backend
  const { data: assignments, isLoading: assignLoading, refetch: refetchAssign } = useSchoolQuery('/api/academics/my-assignments');
  const { data: reportCards, isLoading: reportsLoading } = useSchoolQuery('/api/exams/report-cards');

  const activeAssignments = Array.isArray(assignments) ? assignments : [];
  const publishedReports = Array.isArray(reportCards) ? reportCards.slice(0, 3) : [];

  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleMarkDone = async (assignmentId: string) => {
    try {
      setIsSubmitting(true);
      const res: any = await requestDashboardApi("/api/student-portal/assignments/mark-done", {
        method: "POST",
        body: { assignmentId },
      });
      if (res.success) {
        toast.success("Assignment submitted as complete.");
        refetchAssign();
      } else {
        toast.error(res.error || "Failed to mark assignment as done");
      }
    } catch (err: any) {
      toast.error(err.message || "An error occurred");
    } finally {
      setIsSubmitting(false);
    }
  };

  const downloadReportCard = (report: any) => {
    openPrintDocument({
      eyebrow: "Student report card",
      title: report.title || report.term || "Published Report Card",
      subtitle: report.academic_year || report.exam_series_name || "Published academic record",
      rows: [
        { label: "Term", value: report.term || report.academic_term_name || "-" },
        { label: "Academic year", value: report.academic_year || report.academic_year_name || "-" },
        { label: "Average score", value: report.average_score ?? report.mean_score ?? "-" },
        { label: "Grade", value: report.grade ?? report.overall_grade ?? "-" },
        { label: "Status", value: report.status || "published" },
      ],
      footer: "student-report-card generated from published MyShule academic records.",
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 tracking-tight">My Academics & Homework</h2>
          <p className="text-sm text-slate-500 mt-1">Stay on top of your assignments and view your report cards.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-4">
          <h3 className="font-medium text-slate-900 mb-2">Pending Assignments</h3>
          
          {assignLoading ? (
             <Card className="p-8 border border-slate-200 text-center animate-pulse text-slate-500">
               Loading assignments...
             </Card>
          ) : activeAssignments.length > 0 ? (
             activeAssignments.map((task: any, idx: number) => (
                <Card key={idx} className="p-4 border border-slate-200 flex flex-col md:flex-row gap-4 justify-between group hover:border-blue-200 transition-colors">
                  <div className="flex gap-4">
                    <div className="w-10 h-10 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
                      <BookOpen className="w-5 h-5" />
                    </div>
                    <div>
                      <h4 className="font-medium text-slate-900">{task.title}</h4>
                      <p className="text-sm text-slate-500 mt-1">{task.subject || 'General'}</p>
                      {task.description && (
                        <p className="text-sm text-slate-600 mt-2 bg-slate-50 p-2 rounded">{task.description}</p>
                      )}
                      <div className="flex items-center gap-3 mt-3">
                        <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-xs font-medium bg-amber-50 text-amber-700 border border-amber-200/50">
                          <Clock className="w-3 h-3" /> Due {new Date(task.due_date).toLocaleDateString()}
                        </span>
                      </div>
                    </div>
                  </div>
                  <div className="flex justify-end items-end gap-2 text-sm">
                    <Button 
                      variant="outline" 
                      className="gap-2 text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50 border-emerald-200"
                      onClick={() => handleMarkDone(String(task.id))}
                      disabled={isSubmitting}
                    >
                      <CheckCircle className="w-4 h-4" /> Mark Done
                    </Button>
                  </div>
                </Card>
             ))
          ) : (
             <Card className="p-8 border border-slate-200 border-dashed text-center">
               <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-emerald-50 text-emerald-600 mb-4">
                 <CheckCircle className="w-6 h-6" />
               </div>
               <p className="text-slate-900 font-medium">All Caught Up!</p>
               <p className="text-sm text-slate-500 mt-1">You have no pending assignments right now.</p>
             </Card>
          )}
        </div>

        <div className="space-y-4">
          <h3 className="font-medium text-slate-900 mb-2">My Report Cards</h3>
          
          <div className="space-y-3">
            {reportsLoading ? (
               <Card className="p-6 border border-slate-200 text-center text-slate-500 animate-pulse">
                 Loading...
               </Card>
            ) : publishedReports.length > 0 ? (
               publishedReports.map((report: any, idx: number) => (
                  <Card key={idx} className="p-4 border border-slate-200 flex items-center justify-between hover:border-blue-200 transition-colors">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-rose-50 text-rose-600 rounded">
                        <FileText className="w-5 h-5" />
                      </div>
                      <div>
                        <h4 className="text-sm font-medium text-slate-900">{report.term || 'Term'}</h4>
                        <p className="text-xs text-slate-500">{report.academic_year || 'Year'}</p>
                      </div>
                    </div>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 text-blue-600"
                      aria-label={`Download report card for ${report.term || "published report"}`}
                      onClick={() => downloadReportCard(report)}
                    >
                      <Download className="w-4 h-4" />
                    </Button>
                  </Card>
               ))
            ) : (
               <Card className="p-6 border border-slate-200 text-center">
                 <p className="text-sm text-slate-500">No report cards have been published yet.</p>
               </Card>
            )}
          </div>
        </div>
