"use client";
import { Bus } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";

type OverviewRecord = {
  id: string;
  metric: string;
  value: string;
};

type OverviewData = {
  metrics: {
    total_vehicles: number;
    active_routes: number;
    students_transported: number;
    trips_today: number;
  };
  overviewList: OverviewRecord[];
};

export function OverviewWorkspace() {
  const { data, isLoading } = useSchoolQuery<OverviewData>('/admin-command/transport-manager/overview');
  const items = data?.overviewList || [];

  const getStatusTone = (st: string): Tone => {
    if (st === "Active" || st === "Available" || st === "Approved" || st === "Completed" || st === "Resolved" || st === "Present" || st === "Functional" || st === "On Track" || st === "Cleared") return "success";
    if (st === "Pending" || st === "In Progress" || st === "Pending Approval" || st === "Scheduled" || st === "On Loan" || st === "Behind" || st === "Departed" || st === "Warning" || st === "Pending Review") return "warning";
    if (st === "Overdue" || st === "Critical" || st === "Rejected" || st === "Escalated" || st === "Expired" || st === "Damaged" || st === "Flagged" || st === "Absent" || st === "Blacklisted" || st === "Disposed" || st === "Unauthorized") return "danger";
    if (st === "Issued" || st === "Checked In" || st === "Submitted" || st === "Booked" || st === "Sent" || st === "On Leave") return "info";
    return "neutral";
  };

  return (
    <Panel title="Transport Overview" description="High-level transport operations dashboard." icon={Bus}>
      <div className="grid gap-4 md:grid-cols-4 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Total Vehicles</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total_vehicles ?? 0}</div>
        </div>
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Active Routes</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.active_routes ?? 0}</div>
        </div>
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Students Transported</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.students_transported ?? 0}</div>
        </div>
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Trips Today</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.trips_today ?? 0}</div>
        </div>
      </div>
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold">Metric</th>
              <th className="px-4 py-3 font-bold">Value</th>
            </tr>
          </thead>
          <tbody>
            {isLoading ? (
              <tr><td colSpan={2} className="px-4 py-8 text-center text-[#64748B]">Loading...</td></tr>
            ) : items.length === 0 ? (
              <tr><td colSpan={2} className="px-4 py-8 text-center text-[#64748B]">No records found. Create the first entry to get started.</td></tr>
            ) : (
              items.map(row => (
                <tr key={row.id} className="border-t border-[#D8E0EC] hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 text-[#64748B]">{row.metric}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.value}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

import React, { useState } from 'react';
import { CheckCircle, XCircle, Inbox } from 'lucide-react';
import { useApprovals } from '../../hooks/useApprovals';
import { useRolePermissions } from '../../hooks/useRolePermissions'; // Assuming context exposes userId
import { ErrorState } from './error-state';

export const ApprovalInbox: React.FC<{ currentUserId: string }> = ({ currentUserId }) => {
  const { approvals, isLoading, approve, reject } = useApprovals();
  const [isOpen, setIsOpen] = useState(false);

  if (isLoading) return <div className="animate-pulse w-8 h-8 bg-slate-200 rounded-full" />;

  return (
    <div className="relative">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 rounded-full text-slate-400 hover:text-indigo-500 hover:bg-slate-100 transition-all duration-200"
      >
        <Inbox size={24} />
        {approvals.length > 0 && (
          <span className="absolute top-1 right-1 flex h-4 w-4 items-center justify-center rounded-full bg-amber-500 text-[10px] font-bold text-white shadow-sm ring-2 ring-white">
            {approvals.length > 9 ? '9+' : approvals.length}
          </span>
        )}
      </button>

      {isOpen && (
        <div className="absolute right-0 mt-2 w-96 rounded-xl bg-white shadow-2xl ring-1 ring-black/5 z-50 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50/80 backdrop-blur flex justify-between items-center">
            <h3 className="font-semibold text-slate-800">Pending Approvals</h3>
          </div>
          <div className="max-h-96 overflow-y-auto p-2">
            {approvals.length === 0 ? (
              <div className="p-8 text-center text-slate-500">
                <CheckCircle className="mx-auto h-8 w-8 text-slate-300 mb-2" />
                <p className="text-sm">You're all caught up!</p>
              </div>
            ) : (
              approvals.map((req) => (
                <div key={req.id} className="p-3 mb-2 rounded-lg border border-slate-100 bg-white hover:shadow-md transition-shadow">
                  <h4 className="text-sm font-semibold text-slate-800">{req.title}</h4>
                  <p className="text-xs text-slate-500 mt-1 line-clamp-2">{req.reason}</p>
                  <div className="flex justify-end gap-2 mt-3">
                    <button 
                      onClick={() => reject(req.id, currentUserId, 'Rejected from inbox')}
                      className="flex items-center text-xs font-medium text-red-600 bg-red-50 hover:bg-red-100 px-3 py-1.5 rounded-md transition-colors"
                    >
                      <XCircle size={14} className="mr-1" /> Reject
                    </button>
                    <button 
                      onClick={() => approve(req.id, currentUserId, 'Approved from inbox')}
                      className="flex items-center text-xs font-medium text-white bg-indigo-600 hover:bg-indigo-700 px-3 py-1.5 rounded-md transition-colors shadow-sm"
                    >
                      <CheckCircle size={14} className="mr-1" /> Approve
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
};

