import { Button } from "./button";
import { usePermissions } from "../providers/permission-context";
import { Lock, AlertTriangle, XCircle, Loader2 } from "lucide-react";
import { useState, useEffect } from "react";

export interface GovernedButtonProps extends React.ComponentProps<typeof Button> {
  requiredCapability?: string;
  actionName?: string;
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => Promise<any> | void;
  // External overrides
  isDegraded?: boolean;
  isFailed?: boolean;
  isLoading?: boolean;
}

export function GovernedButton({
  requiredCapability,
  actionName,
  children,
  onClick,
  variant = "primary",
  isDegraded,
  isFailed,
  isLoading,
  ...props
}: GovernedButtonProps) {
  const { hasPermission } = usePermissions();

  // Capability Check
  const hasAccess = requiredCapability ? hasPermission(requiredCapability) : true;

  // Internal State Machine
  const [internalState, setInternalState] = useState<'ACTIVE' | 'LOADING' | 'DEGRADED' | 'FAILED' | 'LOCKED'>(
    hasAccess ? 'ACTIVE' : 'LOCKED'
  );

  // Sync with external states if provided
  useEffect(() => {
    if (!hasAccess) {
      setInternalState('LOCKED');
    } else if (isLoading) {
      setInternalState('LOADING');
    } else if (isFailed) {
      setInternalState('FAILED');
    } else if (isDegraded) {
      setInternalState('DEGRADED');
    } else {
      setInternalState('ACTIVE');
    }
  }, [hasAccess, isLoading, isFailed, isDegraded]);

  const handleClick = async (e: React.MouseEvent<HTMLButtonElement>) => {
    if (internalState === 'LOCKED' || internalState === 'LOADING') {
      e.preventDefault();
      return;
    }

    if (!onClick) return;

    try {
      if (isLoading === undefined) setInternalState('LOADING');
      const result = await onClick(e);

      // Auto-detect degraded/fallback signatures from AGP backend
      if (result && typeof result === 'object' && ('degraded' in result || 'fallback' in result)) {
        if (isDegraded === undefined) setInternalState('DEGRADED');
      } else {
        if (isLoading === undefined) setInternalState('ACTIVE');
      }
    } catch (error) {
      if (isFailed === undefined) setInternalState('FAILED');
      // Autonomous self-healing console event
      console.warn(`[AGP Self-Healing Frontend] Button action failed: ${actionName || 'unknown_action'}`, error);
    }
  };

  const isLocked = internalState === 'LOCKED';
  const isCurrentlyLoading = internalState === 'LOADING';
  const isCurrentlyDegraded = internalState === 'DEGRADED';
  const isCurrentlyFailed = internalState === 'FAILED';

  // Override variant and styling based on health
  let finalVariant = variant;
  if (isLocked) finalVariant = 'outline';
  else if (isCurrentlyFailed) finalVariant = 'danger';

  return (
    <Button
      variant={finalVariant}
      onClick={handleClick}
      disabled={isLocked || props.disabled}
      className={`${props.className || ''} ${isCurrentlyDegraded ? 'ring-2 ring-warning/50 ring-offset-1 border-warning bg-warning-soft text-warning hover:bg-warning-soft/80' : ''}`}
      {...props}
    >
      {isCurrentlyLoading && <Loader2 className="w-4 h-4 animate-spin" />}
      {isLocked && <Lock className="w-4 h-4 text-muted-strong" />}
      {isCurrentlyDegraded && <AlertTriangle className="w-4 h-4 text-warning" />}
      {isCurrentlyFailed && <XCircle className="w-4 h-4 text-white" />}

      {/* Label wrapping */}
      <span className={isLocked ? 'text-muted-strong' : ''}>
        {isLocked ? `Locked (${requiredCapability})` : children}
      </span>
    </Button>
  );
}

import * as React from "react"

export interface TableProps extends React.HTMLAttributes<HTMLTableElement> {
  columns?: string[];
  data?: any[];
  renderRow?: (item: any) => React.ReactNode;
  emptyState?: React.ReactNode;
}

const Table = React.forwardRef<HTMLTableElement, TableProps>(
  ({ className = "", columns, data, renderRow, emptyState, children, ...props }, ref) => {
    if (columns && data && renderRow) {
      return (
        <div className="relative w-full overflow-auto rounded-xl border border-slate-200/60 bg-white shadow-sm ring-1 ring-slate-900/5">
          <table
            ref={ref}
            className={`w-full caption-bottom text-sm transition-colors ${className}`}
            {...props}
          >
            <thead className="bg-slate-50/80 backdrop-blur-md border-b border-slate-200/60">
              <tr className="group border-b border-slate-100 transition-all duration-200">
                {columns.map((col, i) => (
                  <th key={i} className="h-11 px-4 text-left align-middle text-[12px] font-semibold uppercase tracking-wider text-slate-500">{col}</th>
                ))}
              </tr>
            </thead>
            <tbody className="[&_tr:last-child]:border-0">
              {data.length === 0 && emptyState ? (
                <tr className="group border-b border-slate-100">
                  <td colSpan={columns.length} className="p-4 align-middle text-slate-700">
                    {emptyState}
                  </td>
                </tr>
              ) : (
                data.map((item, idx) => <React.Fragment key={idx}>{renderRow(item)}</React.Fragment>)
              )}
            </tbody>
          </table>
        </div>
      );
    }

    return (
      <div className="relative w-full overflow-auto rounded-xl border border-slate-200/60 bg-white shadow-sm ring-1 ring-slate-900/5">
        <table
          ref={ref}
          className={`w-full caption-bottom text-sm transition-colors ${className}`}
          {...props}
        >
          {children}
        </table>
      </div>
    );
  }
)
Table.displayName = "Table"

const TableHeader = React.forwardRef<
  HTMLTableSectionElement,
  React.HTMLAttributes<HTMLTableSectionElement>
>(({ className = "", ...props }, ref) => (
  <thead ref={ref} className={`bg-slate-50/80 backdrop-blur-md border-b border-slate-200/60 ${className}`} {...props} />
))
TableHeader.displayName = "TableHeader"

const TableBody = React.forwardRef<
  HTMLTableSectionElement,
  React.HTMLAttributes<HTMLTableSectionElement>
>(({ className = "", ...props }, ref) => (
  <tbody
    ref={ref}
    className={`[&_tr:last-child]:border-0 ${className}`}
    {...props}
  />
))
TableBody.displayName = "TableBody"

const TableFooter = React.forwardRef<
  HTMLTableSectionElement,
  React.HTMLAttributes<HTMLTableSectionElement>
>(({ className = "", ...props }, ref) => (
  <tfoot
    ref={ref}
    className={`border-t bg-muted/50 font-medium [&>tr]:last:border-b-0 ${className}`}
    {...props}
  />
))
TableFooter.displayName = "TableFooter"

const TableRow = React.forwardRef<
  HTMLTableRowElement,
  React.HTMLAttributes<HTMLTableRowElement>
>(({ className = "", ...props }, ref) => (
  <tr
    ref={ref}
    className={`group border-b border-slate-100 transition-all duration-200 hover:bg-slate-50/80 hover:shadow-[inset_0_1px_0_rgba(255,255,255,1),0_1px_3px_rgba(0,0,0,0.02)] data-[state=selected]:bg-slate-100/50 ${className}`}
    {...props}
  />
))
TableRow.displayName = "TableRow"

const TableHead = React.forwardRef<
  HTMLTableCellElement,
  React.ThHTMLAttributes<HTMLTableCellElement>
>(({ className = "", ...props }, ref) => (
  <th
    ref={ref}
    className={`h-11 px-4 text-left align-middle text-[12px] font-semibold uppercase tracking-wider text-slate-500 [&:has([role=checkbox])]:pr-0 [&>[role=checkbox]]:translate-y-[2px] ${className}`}
