import React from 'react';
import Link from 'next/link';
import { Check, X } from 'lucide-react';
import { Card } from '@/components/ui/card';
import { StatusPill } from '@/components/ui/status-pill';

interface ApprovalCardProps {
  id: string;
  title: string;
  description: string;
  requesterName: string;
  requesterRole: string;
  status: string;
  href: string;
  onApprove?: (note?: string) => void;
  onReject?: (note?: string) => void;
}

export function ApprovalCard({
  id,
  title,
  description,
  requesterName,
  requesterRole,
  status,
  href,
  onApprove,
  onReject,
}: ApprovalCardProps) {
  const isPending = status.toLowerCase() === 'pending';

  return (
    <Card className={`p-4 transition-colors ${isPending ? 'border-accent/40 bg-accent/5' : 'hover:bg-surface-muted'}`}>
      <div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2">
            <Link href={href} className="group min-w-0">
              <h4 className="text-sm font-semibold text-foreground group-hover:text-accent truncate">
                {title}
              </h4>
              <p className="mt-1 text-xs text-muted line-clamp-2">
                {description}
              </p>
            </Link>
            {!isPending && (
              <StatusPill 
                label={status} 
                tone={status.toLowerCase() === 'approved' ? 'ok' : 'critical'} 
                compact 
              />
            )}
          </div>

          <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-2">
            <div className="flex items-center gap-1.5">
              <span className="text-[11px] font-semibold uppercase tracking-wider text-muted">Requester:</span>
              <span className="text-xs font-medium text-foreground">{requesterName}</span>
              <StatusPill label={requesterRole} tone="ok" compact />
            </div>
          </div>
        </div>

        {isPending && (onApprove || onReject) && (
          <div className="mt-4 flex shrink-0 items-center gap-2 md:mt-0 md:ml-4">
            {onReject && (
              <button
                type="button"
                onClick={() => onReject()}
                className="inline-flex h-8 items-center justify-center gap-1.5 rounded-[var(--radius-sm)] border border-danger bg-surface px-3 text-[12px] font-semibold text-danger transition-colors hover:bg-danger/10"
              >
                <X className="h-3.5 w-3.5" />
                Reject
              </button>
            )}
            {onApprove && (
              <button
                type="button"
                onClick={() => onApprove()}
                className="inline-flex h-8 items-center justify-center gap-1.5 rounded-[var(--radius-sm)] bg-accent px-3 text-[12px] font-semibold text-white transition-colors hover:bg-accent-hover"
              >
                <Check className="h-3.5 w-3.5" />
                Approve
              </button>
            )}
          </div>
        )}
      </div>
    </Card>
  );
}

'use client';

import { useState } from 'react';
import { toast } from 'sonner';
import { ApprovalRequest, ApprovalsApi } from '@/lib/client/approvals-api';

interface ApprovalDetailDrawerProps {
  request: ApprovalRequest | null;
  isOpen: boolean;
  onClose: () => void;
  onProcessed: () => void;
}

export function ApprovalDetailDrawer({ request, isOpen, onClose, onProcessed }: ApprovalDetailDrawerProps) {
  const [comment, setComment] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  if (!isOpen || !request) return null;

  const handleAction = async (action: 'APPROVE' | 'REJECT' | 'REQUEST_CHANGES' | 'ESCALATE') => {
    try {
      setIsProcessing(true);
      await ApprovalsApi.processAction(request.id, action, comment);
      onProcessed();
      onClose();
    } catch (error) {
      console.error(error);
      toast.error(`Failed to ${action.toLowerCase()} request`);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex justify-end bg-black/50">
      <div className="w-[450px] h-full bg-white shadow-xl flex flex-col animate-in slide-in-from-right">
        <div className="p-4 border-b flex justify-between items-center bg-gray-50">
          <h2 className="text-lg font-semibold text-gray-800">Approval Details</h2>
          <button onClick={onClose} className="text-gray-500 hover:text-gray-700">
            &times; Close
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-6">
          <div>
            <h3 className="text-sm font-medium text-gray-500">Module</h3>
            <p className="mt-1 text-sm text-gray-900">{request.module}</p>
          </div>
          <div>
            <h3 className="text-sm font-medium text-gray-500">Action</h3>
            <p className="mt-1 text-sm text-gray-900">{request.action}</p>
          </div>
          <div>
            <h3 className="text-sm font-medium text-gray-500">Target</h3>
            <p className="mt-1 text-sm text-gray-900">{request.targetEntityType} #{request.targetEntityId}</p>
          </div>
          <div>
            <h3 className="text-sm font-medium text-gray-500">Status</h3>
            <span className="mt-1 inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
              {request.status}
            </span>
          </div>

          <div>
            <h3 className="text-sm font-medium text-gray-500">Reason / Context</h3>
            <div className="mt-1 p-3 bg-gray-50 rounded-md text-sm text-gray-700">
              {request.reason || 'No specific reason provided.'}
            </div>
          </div>

          {request.newValue && (
            <div>
              <h3 className="text-sm font-medium text-gray-500">Proposed Changes</h3>
              <pre className="mt-1 p-3 bg-gray-100 rounded-md text-xs overflow-x-auto text-gray-800">
                {JSON.stringify(request.newValue, null, 2)}
              </pre>
            </div>
          )}

          <div>
            <h3 className="text-sm font-medium text-gray-500">Audit Trail</h3>
            <ul className="mt-2 space-y-2">
              {request.auditLogs?.map((log: any, idx: number) => (
                <li key={idx} className="text-xs text-gray-600 border-l-2 border-gray-200 pl-3">
                  <span className="font-semibold">{log.action}</span> - {new Date(log.createdAt).toLocaleString()}
                  {log.comment && <div className="mt-1 text-gray-500 italic">"{log.comment}"</div>}
                </li>
              ))}
              {(!request.auditLogs || request.auditLogs.length === 0) && (
                <li className="text-xs text-gray-500">No logs available.</li>
              )}
            </ul>
          </div>
        </div>

        {request.status === 'PENDING_APPROVAL' && (
          <div className="p-4 border-t bg-gray-50 space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Approver Comment (Optional)</label>
              <textarea
                rows={2}
                className="w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                placeholder="Leave a comment..."
              />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <button
                disabled={isProcessing}
                onClick={() => handleAction('APPROVE')}
                className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-green-600 hover:bg-green-700 disabled:opacity-50"
              >
                Approve
              </button>
              <button
                disabled={isProcessing}
                onClick={() => handleAction('REJECT')}
                className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-red-600 hover:bg-red-700 disabled:opacity-50"
              >
                Reject
              </button>
              <button
                disabled={isProcessing}
                onClick={() => handleAction('REQUEST_CHANGES')}
                className="inline-flex justify-center py-2 px-4 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 disabled:opacity-50 col-span-2"
              >
                Request Changes
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { ApprovalRequest, ApprovalsApi } from '@/lib/client/approvals-api';
import { ApprovalDetailDrawer } from './ApprovalDetailDrawer';

export function ApprovalWorkspace() {
  const [activeTab, setActiveTab] = useState<'PENDING' | 'MY_REQUESTS'>('PENDING');
  const [requests, setRequests] = useState<ApprovalRequest[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedRequest, setSelectedRequest] = useState<ApprovalRequest | null>(null);

  const fetchRequests = async () => {
    setIsLoading(true);
    try {
      if (activeTab === 'PENDING') {
        const data = await ApprovalsApi.getPendingRequests();
        setRequests(data);
      } else {
        const data = await ApprovalsApi.getMyRequests();
        setRequests(data);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [activeTab]);

  return (
    <div className="flex flex-col h-full bg-white rounded-lg shadow-sm border border-gray-200">
      <div className="p-4 border-b border-gray-200">
        <h1 className="text-xl font-semibold text-gray-800">Approvals Workspace</h1>
        <p className="text-sm text-gray-500 mt-1">Manage and review pending system actions governed by AGP.</p>
      </div>

      <div className="flex border-b border-gray-200 bg-gray-50 px-4">
        <button
          className={`px-4 py-3 text-sm font-medium border-b-2 ${
            activeTab === 'PENDING'
              ? 'border-blue-500 text-blue-600'
              : 'border-transparent text-gray-500 hover:text-gray-700'
          }`}
          onClick={() => setActiveTab('PENDING')}
        >
          Pending Review
        </button>
        <button
          className={`px-4 py-3 text-sm font-medium border-b-2 ${
            activeTab === 'MY_REQUESTS'
              ? 'border-blue-500 text-blue-600'
              : 'border-transparent text-gray-500 hover:text-gray-700'
          }`}
          onClick={() => setActiveTab('MY_REQUESTS')}
        >
          My Requests
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
        {isLoading ? (
          <div className="flex justify-center items-center h-32">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
          </div>
        ) : requests.length === 0 ? (
          <div className="text-center py-12">
            <svg className="mx-auto h-12 w-12 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
            </svg>
            <h3 className="mt-2 text-sm font-medium text-gray-900">No requests found</h3>
            <p className="mt-1 text-sm text-gray-500">You're all caught up!</p>
          </div>
        ) : (
          <div className="space-y-4">
            {requests.map((req) => (
              <div 
                key={req.id} 
                className="bg-white border border-gray-200 rounded-lg p-4 shadow-sm hover:shadow-md transition-shadow cursor-pointer flex justify-between items-center"
                onClick={() => setSelectedRequest(req)}
              >
                <div>
                  <div className="flex items-center space-x-3">
                    <span className="text-sm font-semibold text-gray-800 uppercase tracking-wide">
                      {req.module}
                    </span>
                    <span className="text-gray-300">|</span>
                    <span className="text-sm text-gray-600 font-medium">
                      {req.action}
                    </span>
                  </div>
                  <div className="mt-1 text-sm text-gray-500 line-clamp-1">
                    {req.reason || 'No reason provided'}
                  </div>
                  <div className="mt-2 text-xs text-gray-400">
                    Requested on {new Date(req.createdAt).toLocaleDateString()}
                  </div>
                </div>
                <div>
                  <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                    req.status === 'APPROVED' ? 'bg-green-100 text-green-800' :
                    req.status === 'REJECTED' ? 'bg-red-100 text-red-800' :
                    req.status === 'CHANGES_REQUESTED' ? 'bg-yellow-100 text-yellow-800' :
                    req.status === 'PENDING_APPROVAL' ? 'bg-blue-100 text-blue-800' :
                    'bg-gray-100 text-gray-800'
